impl Config {
    pub fn config_path() -> Result<PathBuf> {
        let xdg = std::env::var_os("XDG_CONFIG_HOME")
            .map(PathBuf::from)
            .or_else(|| dirs::home_dir().map(|h| h.join(".config")))
            .context("no XDG_CONFIG_HOME or HOME")?;
        Ok(xdg.join("qocr").join("config.json"))
    }

    pub fn load() -> Result<Self> {
        Self::load_from(&Self::config_path()?)
    }

    pub fn load_from(path: &Path) -> Result<Self> {
        if !path.exists() {
            tracing::info!("config {} not found, using defaults", path.display());
            return Ok(Self::default());
        }
        let raw = std::fs::read_to_string(path)
            .with_context(|| format!("read config {}", path.display()))?;
        let cfg: Self = serde_json::from_str(&raw)
            .with_context(|| format!("parse config {}", path.display()))?;
        tracing::info!("loaded config from {}", path.display());
        Ok(cfg)
    }

    /// Watch the config file and call `on_change` whenever it changes. Returns the JoinHandle.
    pub fn watch<F>(path: PathBuf, on_change: F) -> std::io::Result<std::thread::JoinHandle<()>>
    where
        F: Fn() + Send + 'static,
    {
        use std::sync::mpsc;
        use std::time::Duration;

        std::thread::Builder::new()
            .name("config-watcher".into())
            .spawn(move || {
                let (tx, rx) = mpsc::channel();
                let mut watcher = match notify::recommended_watcher(move |res: notify::Result<notify::Event>| {
                    let _ = tx.send(res);
                }) {
                    Ok(w) => w,
                    Err(e) => {
                        tracing::error!("config watcher init failed: {e}");
                        return;
                    }
                };
                if let Err(e) = watcher.watch(&path, notify::RecursiveMode::NonRecursive) {
                    tracing::error!("config watch failed: {e}");
                    return;
                }
                // Debounce: collapse bursts of modify events.
                loop {
                    let _ = rx.recv();
                    let debounce = Duration::from_millis(150);
                    let cutoff = std::time::Instant::now() + debounce;
                    while let Ok(Ok(_)) = rx.recv_timeout(cutoff.saturating_duration_since(std::time::Instant::now())) {
                        // drain
                    }
                    on_change();
                }
            })
    }
}

//! `qocrd` subprocess wrapper.
//!
//! Spawns the Python OCR daemon we already set up at `/home/camel/Downloads/qocr/.venv/bin/qocrd`
//! (via the wrapper at `~/.local/bin/qocrd`) and pumps commands to it on stdin, parsing
//! null-byte-delimited JSON results from stdout.
//!
//! The daemon is the only thing that needs to be reused from upstream qocr; the GTK4
//! overlay here replaces Quickshell entirely.

use anyhow::{Context, Result};
use std::path::PathBuf;
use std::process::Stdio;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::process::{Child, Command};
use tokio::sync::mpsc as tmpsc;

use crate::types::OcrResult;

/// Resolved path to the qocrd wrapper we created during install.
pub fn qocrd_path() -> PathBuf {
    // Prefer the wrapper in ~/.local/bin (works around upstream pyproject.toml bug),
    // then the venv entry-point script (broken entry, but keep as fallback).
    if let Ok(home) = std::env::var("HOME") {
        let wrapper = PathBuf::from(home).join(".local/bin/qocrd");
        if wrapper.exists() {
            return wrapper;
        }
    }
    PathBuf::from("/home/camel/Downloads/qocr/.venv/bin/qocrd")
}

/// Handle to the running qocrd subprocess.
pub struct OcrDaemon {
    child: Child,
    stdin: tokio::process::ChildStdin,
    /// Pending "rescan" replies, one per scan region. qocrd returns `{"unchanged":true}` if
    /// the captured frame matches the previous one for that monitor.
    pending_rescans: u32,
}

impl OcrDaemon {
    pub async fn spawn() -> Result<Self> {
        let mut cmd = Command::new(qocrd_path());
        cmd.stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .kill_on_drop(true);
        let mut child = cmd.spawn().context("spawn qocrd")?;
        let stdin = child.stdin.take().context("qocrd stdin")?;
        let stdout = child.stdout.take().context("qocrd stdout")?;

        // Drain stderr in a background task — qocrd's logs go here but Chrome Screen AI
        // spams at C level (suppressed internally). We just forward to tracing.
        if let Some(stderr) = child.stderr.take() {
            tokio::spawn(async move {
                use tokio::io::AsyncBufReadExt as _;
                let mut reader = BufReader::new(stderr).lines();
                while let Ok(Some(line)) = reader.next_line().await {
                    tracing::debug!("qocrd stderr: {line}");
                }
            });
        }

        // Spawn the read loop. It will send parsed results via the channel passed in `run`.
        // We just need to keep stdout alive; the read loop lives in `run`.
        // (Stash stdout back so callers can use it.)
        child.stdout = Some(stdout);

        Ok(Self {
            child,
            stdin,
            pending_rescans: 0,
        })
    }

    /// Ask qocrd to scan. `japanese_only` filters to Japanese-only lines. If `fullscreen`
    /// is true, qocrd picks the active monitor instead of asking slurp.
    pub async fn scan(&mut self, japanese_only: bool, fullscreen: bool) -> Result<()> {
        self.write_line(format!("scan {japanese_only} {fullscreen}\n")).await
    }

    /// Re-OCR a previously captured region. Coordinates are in absolute screen space.
    /// `monitor` is the output name (e.g. "DP-1", "HDMI-A-1").
    pub async fn rescan(
        &mut self,
        japanese_only: bool,
        x: i32,
        y: i32,
        w: i32,
        h: i32,
        x_in_monitor: i32,
        y_in_monitor: i32,
        monitor: &str,
    ) -> Result<()> {
        let line = format!(
            "rescan {japanese_only} {x} {y} {w} {h} {x_in_monitor} {y_in_monitor} {monitor}\n"
        );
        self.write_line(line).await
    }

    async fn write_line(&mut self, line: String) -> Result<()> {
        self.stdin.write_all(line.as_bytes()).await?;
        self.stdin.flush().await?;
        Ok(())
    }

    /// Take the stdout handle out so the caller can drive the read loop.
    pub fn take_stdout(&mut self) -> Option<tokio::process::ChildStdout> {
        self.child.stdout.take()
    }

    pub fn kill(&mut self) {
        let _ = self.child.start_kill();
    }
}

/// Read loop: splits stdout on `\0` records, parses each as JSON, and forwards to the channel.
/// One record = either an `OcrResult` or an `UnchangedResult` marker.
pub async fn read_loop(
    stdout: tokio::process::ChildStdout,
    tx: tmpsc::Sender<DaemonEvent>,
) -> Result<()> {
    use tokio::io::AsyncBufReadExt as _;
    let mut reader = BufReader::new(stdout);
    let mut buf = Vec::new();
    loop {
        buf.clear();
        let n = reader.read_until(b'\0', &mut buf).await?;
        if n == 0 {
            tracing::warn!("qocrd stdout EOF");
            break;
        }
        let chunk = std::str::from_utf8(&buf).context("non-utf8 from qocrd")?.trim();
        if chunk.is_empty() {
            continue;
        }
        match serde_json::from_str::<serde_json::Value>(chunk) {
            Ok(v) if v.get("unchanged").is_some() => {
                let _ = tx.send(DaemonEvent::Unchanged).await;
            }
            Ok(_) => match serde_json::from_str::<OcrResult>(chunk) {
                Ok(result) => {
                    let _ = tx.send(DaemonEvent::Result(result)).await;
                }
                Err(e) => {
                    tracing::warn!("parse OcrResult: {e} -- raw: {chunk}");
                }
            },
            Err(e) => {
                tracing::warn!("parse JSON: {e} -- raw: {chunk}");
            }
        }
    }
    Ok(())
}

#[derive(Debug)]
pub enum DaemonEvent {
    Result(OcrResult),
    Unchanged,
}

//! Unix socket IPC server + CLI client.
//!
//! Server listens on `$XDG_RUNTIME_DIR/gnome-ocr.sock` and accepts JSON-encoded `Command`s.
//! Client (`gnome-ocr-cli <command>`) connects, writes one command, reads back a JSON
//! reply, and exits. This is the same shape as the Quickshell IPC the original qocr used.

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::mpsc as tmpsc;

use crate::types::Command;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Reply {
    pub ok: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub value: Option<serde_json::Value>,
}

impl Reply {
    pub fn ok() -> Self {
        Self {
            ok: true,
            message: None,
            value: None,
        }
    }
    pub fn ok_msg(msg: impl Into<String>) -> Self {
        Self {
            ok: true,
            message: Some(msg.into()),
            value: None,
        }
    }
    pub fn err(msg: impl Into<String>) -> Self {
        Self {
            ok: false,
            message: Some(msg.into()),
            value: None,
        }
    }
    pub fn with_value(mut self, v: serde_json::Value) -> Self {
        self.value = Some(v);
        self
    }
}

pub fn socket_path() -> Result<PathBuf> {
    let runtime = std::env::var_os("XDG_RUNTIME_DIR")
        .map(PathBuf::from)
        .or_else(|| dirs::runtime_dir())
        .context("no XDG_RUNTIME_DIR")?;
    Ok(runtime.join("gnome-ocr.sock"))
}

/// Spawn the listener. Each accepted connection reads one JSON-encoded command, hands it
/// to the channel, and exits when the connection closes.
pub async fn serve(
    path: PathBuf,
    tx: tmpsc::Sender<Command>,
) -> Result<()> {
    // Remove stale socket file from a previous crash.
    let _ = std::fs::remove_file(&path);
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let listener = UnixListener::bind(&path).with_context(|| format!("bind {}", path.display()))?;
    // Tighten perms: server is a per-user socket.
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600));
    }
    tracing::info!("IPC listening on {}", path.display());
    loop {
        match listener.accept().await {
            Ok((stream, _)) => {
                tokio::spawn(handle_conn(stream, tx.clone()));
            }
            Err(e) => {
                tracing::warn!("IPC accept: {e}");
            }
        }
    }
}

async fn handle_conn(stream: UnixStream, tx: tmpsc::Sender<Command>) {
    let (read, mut write) = stream.into_split();
    let mut reader = BufReader::new(read).lines();
    let mut line = String::new();
    if reader.read_line(&mut line).await.is_err() || line.trim().is_empty() {
        return;
    }
    match serde_json::from_str::<Command>(line.trim()) {
        Ok(cmd) => {
            if tx.send(cmd).await.is_err() {
                tracing::warn!("command channel closed; daemon likely shut down");
            }
            // Ack — the long-running reply would need a richer protocol, but the original
       // qocr `ipc call ocr <cmd>` returns immediately for most commands. Clients that
            // care about the result should query state via get_config / wait for events.
            let reply = Reply::ok();
            let payload = serde_json::to_string(&reply).unwrap_or_else(|_| "{}".into());
            let _ = write.write_all(payload.as_bytes()).await;
            let _ = write.write_all(b"\n").await;
            let _ = write.shutdown().await;
        }
        Err(e) => {
            let reply = Reply::err(format!("invalid command: {e}"));
            let payload = serde_json::to_string(&reply).unwrap_or_else(|_| "{}".into());
            let _ = write.write_all(payload.as_bytes()).await;
            let _ = write.write_all(b"\n").await;
            let _ = write.shutdown().await;
        }
    }
}

/// Client: connect, write one JSON command, read reply, print it, exit.
pub async fn send(path: PathBuf, cmd: &Command) -> Result<Reply> {
    let stream = UnixStream::connect(&path)
        .await
        .with_context(|| format!("connect {}", path.display()))?;
    let (read, mut write) = stream.into_split();
    let payload = serde_json::to_string(cmd)?;
    write.write_all(payload.as_bytes()).await?;
    write.write_all(b"\n").await?;
    write.shutdown().await?;
    let mut reader = BufReader::new(read).lines();
    let mut line = String::new();
    reader.read_line(&mut line).await?;
    let reply: Reply = serde_json::from_str(line.trim()).context("parse reply")?;
    Ok(reply)
}

//! HTTP client for yomitan-api (the Native Messaging host that bridges Yomitan's extension
//! to a localhost HTTP API on 127.0.0.1:19633). Provides term lookup, ankiCardFormats, etc.
//!
//! The full Yomitan API spec is at https://github.com/yomidevs/yomitan-api/. We only need
//! term lookup for the popup, plus anki fields if the user wants Anki mining.

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct YomitanClient {
    base_url: String,
    http: reqwest::Client,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TermLookupRequest {
    pub text: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TermEntry {
    pub expression: String,
    pub reading: String,
    #[serde(default)]
    pub definitions: Vec<serde_json::Value>,
    #[serde(default)]
    pub glossary: Vec<serde_json::Value>,
    #[serde(default)]
    pub furigana: Vec<serde_json::Value>,
    #[serde(default)]
    pub pitches: Vec<serde_json::Value>,
    #[serde(default)]
    pub termTags: Vec<String>,
    #[serde(default)]
    pub url: String,
    #[serde(default)]
    pub sentence: serde_json::Value,
    #[serde(default)]
    pub has_structural_data: bool,
    #[serde(default)]
    pub audio: serde_json::Value,
    #[serde(default)]
    pub frequencies: HashMap<String, serde_json::Value>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum LookupReply {
    Multi(Vec<Vec<TermEntry>>),
    Single(Vec<TermEntry>),
}

impl YomitanClient {
    pub fn new(base_url: impl Into<String>) -> Self {
        Self {
            base_url: base_url.into(),
            http: reqwest::Client::builder()
                .timeout(std::time::Duration::from_secs(5))
                .build()
                .expect("reqwest client"),
        }
    }

    pub async fn server_version(&self) -> Result<String> {
        let resp = self
            .http
            .get(format!("{}/serverVersion", self.base_url))
            .send()
            .await
            .context("yomitan-api /serverVersion")?;
        resp.error_for_status()?.text().await.context("yomitan-api body")
    }

    pub async fn lookup(&self, text: &str) -> Result<LookupReply> {
        let resp = self
            .http
            .post(format!("{}/lookup", self.base_url))
            .json(&serde_json::json!({ "text": text }))
            .send()
            .await
            .context("yomitan-api /lookup POST")?;
        let status = resp.status();
        let body = resp.text().await.context("yomitan-api body")?;
        if !status.is_success() {
            // Common case: extension not running, API not reachable.
            return Err(anyhow::anyhow!("yomitan-api HTTP {status}: {body}"));
        }
        let reply: LookupReply = serde_json::from_str(&body).context("parse /lookup reply")?;
        Ok(reply)
    }

    pub async fn anki_fields(&self, text: &str, terms: &[String]) -> Result<serde_json::Value> {
        let mut query: Vec<(&str, String)> = vec![("text", text.to_string())];
        for t in terms {
            query.push(("term", t.clone()));
        }
        let resp = self
            .http
            .get(format!("{}/ankiFields", self.base_url))
            .query(&query)
            .send()
            .await
            .context("yomitan-api /ankiFields")?;
        resp.error_for_status()?.json().await.context("parse /ankiFields")
    }
}

//! AnkiConnect HTTP client. AnkiConnect is an Anki plugin that exposes a JSON-RPC over HTTP
//! on 127.0.0.1:8765. We use it to add mining cards directly from the Yomitan popup.

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct AnkiClient {
    url: String,
    http: reqwest::Client,
}

#[derive(Debug, Clone, Serialize)]
struct AnkiRequest {
    action: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    version: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    params: Option<serde_json::Value>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct AnkiResponse<T> {
    pub error: Option<String>,
    pub result: Option<T>,
}

impl AnkiClient {
    pub fn new(url: impl Into<String>) -> Self {
        Self {
            url: url.into(),
            http: reqwest::Client::builder()
                .timeout(std::time::Duration::from_secs(5))
                .build()
                .expect("reqwest client"),
        }
    }

    pub async fn ping(&self) -> Result<bool> {
        let resp = self.call::<serde_json::Value>("version", None).await?;
        Ok(resp.error.is_none() && resp.result.is_some())
    }

    pub async fn call<T: for<'de> Deserialize<'de>>(
        &self,
        action: &str,
        params: Option<serde_json::Value>,
    ) -> Result<AnkiResponse<T>> {
        let body = AnkiRequest {
            action: action.to_string(),
            version: Some(6),
            params,
        };
        let resp = self
            .http
            .post(&self.url)
            .json(&body)
            .send()
            .await
            .with_context(|| format!("Anki POST {action}"))?;
        let status = resp.status();
        let parsed = resp.json().await.context("parse Anki response")?;
        if !status.is_success() {
            return Err(anyhow::anyhow!("AnkiConnect HTTP {status}"));
        }
        Ok(parsed)
    }

    /// Add a note. `fields` keys are field names from the model; values are templates
    /// expanded by the caller. `tags`, `deck`, `allowDuplicate` honor the user's config.
    pub async fn add_note(
        &self,
        deck: &str,
        model: &str,
        fields: &HashMap<String, String>,
        tags: &[String],
        allow_duplicate: bool,
    ) -> Result<i64> {
        let note = serde_json::json!({
            "deckName": deck,
            "modelName": model,
            "fields": fields,
            "tags": tags,
            "options": { "allowDuplicate": allow_duplicate },
        });
        let resp: AnkiResponse<i64> = self
            .call("addNote", Some(serde_json::json!({ "note": note })))
            .await?;
        if let Some(err) = resp.error {
            return Err(anyhow::anyhow!("AnkiConnect addNote: {err}"));
        }
        resp.result.context("AnkiConnect addNote returned no result")
    }
}

//! Cairo/Pango renderer for OCR boxes + region rectangles + Yomitan popups.
//!
//! All drawing is done in screen coordinates; the widget area is the size of the primary
//! monitor and the renderer offsets lines/popups by their containing region.
//!
//! Why not WebKit2GTK for the popup: Yomitan's HTML popup requires JS execution + CSS that
//! we don't need for v1. Rendering the JSON fields directly with Pango is faster, lighter,
//! and easier to style consistently with the rest of the overlay.

use cairo::{Context, Format, ImageSurface};
use gtk4::gdk::RGBA;
use gtk4::prelude::*;
use gtk4::Snapshot;
use pango::{FontDescription, Layout};
use std::f64::consts::PI;

use crate::config::Config;
use crate::types::{Aabb, Line, OcrResult, Point};

/// Snapshot helper: create an ImageSurface the size of `bounds`, render with `f`, then
/// push it onto the widget snapshot via `append_cairo`.
pub fn render_overlay(
    snapshot: &Snapshot,
    bounds: (f64, f64),
    state: &RenderState,
    config: &Config,
) {
    let (bw, bh) = bounds;
    if bw <= 0.0 || bh <= 0.0 {
        return;
    }
    let surface = ImageSurface::create(Format::ARgb32, bw as i32, bh as i32)
        .expect("ImageSurface create");
    let cr = Context::new(&surface).expect("cairo Context");
    // Clear to fully transparent.
    cr.set_operator(cairo::Operator::Source);
    cr.set_source_rgba(0.0, 0.0, 0.0, 0.0);
    cr.paint().ok();

    for region_state in &state.regions {
        if let Some(sel) = &state.drag {
            // During selection, only render the drag rectangle (no OCR results).
            draw_region_rect(&cr, sel, &config.region_border, &config.region_background);
        } else if let Some(result) = &region_state.result {
            draw_ocr_result(&cr, result, config);
        }
    }
    if let Some(sel) = &state.drag {
        draw_region_rect(&cr, sel, &config.region_border, &config.region_background);
    }

    if let Some(popup) = &state.popup {
        draw_popup(&cr, popup, &config.yomitan);
    }

    snapshot.append_cairo(&surface);
}

pub struct RenderState {
    /// Per-monitor region state: the region being tracked + the latest OCR result.
    pub regions: Vec<RegionState>,
    /// In-flight drag (region selection).
    pub drag: Option<Aabb>,
    /// Active Yomitan popup geometry + content.
    pub popup: Option<PopupState>,
}

pub struct RegionState {
    pub monitor: String,
    pub result: Option<OcrResult>,
    pub flash_until: Option<std::time::Instant>,
}

#[derive(Debug, Clone)]
pub struct PopupState {
    pub anchor: Point,
    pub lines: Vec<String>,
    pub readings: Vec<String>,
    pub definitions: Vec<String>,
}

impl RenderState {
    pub fn new() -> Self {
        Self {
            regions: Vec::new(),
            drag: None,
            popup: None,
        }
    }
}

/// Parse a `#rrggbbaa` or `#rrggbb` hex string into RGBA.
fn parse_hex(s: &str) -> Option<(f64, f64, f64, f64)> {
    let s = s.trim_start_matches('#');
    let (r, g, b, a) = match s.len() {
        6 => (
            u8::from_str_radix(&s[0..2], 16).ok()?,
            u8::from_str_radix(&s[2..4], 16).ok()?,
            u8::from_str_radix(&s[4..6], 16).ok()?,
            255u8,
        ),
        8 => (
            u8::from_str_radix(&s[0..2], 16).ok()?,
            u8::from_str_radix(&s[2..4], 16).ok()?,
            u8::from_str_radix(&s[4..6], 16).ok()?,
            u8::from_str_radix(&s[6..8], 16).ok()?,
        ),
        _ => return None,
    };
    Some((r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0, a as f64 / 255.0))
}

fn fill_rgba(cr: &Context, hex: &str) {
    if let Some((r, g, b, a)) = parse_hex(hex) {
        cr.set_source_rgba(r, g, b, a);
    } else {
        cr.set_source_rgba(1.0, 0.0, 0.0, 0.5);
    }
}

fn draw_region_rect(cr: &Context, rect: &Aabb, border_hex: &str, bg_hex: &str) {
    fill_rgba(cr, bg_hex);
    cr.rectangle(rect.x, rect.y, rect.width, rect.height);
    cr.fill().ok();
    cr.save().ok();
    fill_rgba(cr, border_hex);
    cr.set_line_width(2.0);
    cr.rectangle(rect.x, rect.y, rect.width, rect.height);
    cr.stroke().ok();
    cr.restore().ok();
}

fn draw_ocr_result(cr: &Context, result: &OcrResult, config: &Config) {
    let margin = config.box_margin as f64;
    let region_x = result.region.x as f64;
    let region_y = result.region.y as f64;

    for line in &result.lines {
        // Background box for the whole line, padded by boxMargin.
        let padded = Aabb {
            x: line.aabb.x - margin,
            y: line.aabb.y - margin,
            width: line.aabb.width + margin * 2.0,
            height: line.aabb.height + margin * 2.0,
        };
        fill_rgba(cr, &config.background);
        cr.rectangle(padded.x, padded.y, padded.width, padded.height);
        cr.fill().ok();

        // Border on the line.
        fill_rgba(cr, &config.border_color);
        cr.set_line_width(config.border as f64);
        cr.rectangle(padded.x, padded.y, padded.width, padded.height);
        cr.stroke().ok();

        // Per-word / per-symbol small boxes (only when hovered). For v1, draw per-symbol
        // faintly so they're visible during debug.
        for word in &line.words {
            for sym in &word.symbols {
                let sb = sym.aabb;
                cr.save().ok();
                fill_rgba(cr, "#20d0d0d0");
                cr.rectangle(sb.x, sb.y, sb.width, sb.height);
                cr.fill().ok();
                cr.restore().ok();
            }
        }

        // Text on top of the line background.
        if config.show_overlay {
            draw_text(
                cr,
                &line.text,
                line.aabb.x,
                line.aabb.y + line.aabb.height * 0.85,
                line.aabb.width,
                config.border_color.as_str().into(),
            );
        }
    }

    // Outer region rectangle (the captured area).
    let region_rect = Aabb {
        x: region_x,
        y: region_y,
        width: result.region.w as f64,
        height: result.region.h as f64,
    };
    draw_region_rect(cr, &region_rect, &config.region_border, &config.region_background);
}

fn draw_text(cr: &Context, text: &str, x: f64, y: f64, width: f64, color: &str) {
    if text.is_empty() {
        return;
    }
    let pango_ctx = pangocairo::create_context(cr).expect("pango context");
    let layout = Layout::new(&pango_ctx);
    let mut font = FontDescription::from_string("Sans 11");
    font.set_weight(pango::Weight::Bold);
    layout.set_font_description(Some(&font));
    layout.set_width((width * pango::SCALE as f64) as i32);
    layout.set_text(text);
    fill_rgba(cr, color);
    cr.move_to(x, y);
    pangocairo::show_layout(cr, &layout);
}

fn draw_popup(cr: &Context, popup: &PopupState, cfg: &crate::config::YomitanConfig) {
    let pad = 12.0;
    let line_h = 22.0;
    let min_width = 280.0;
    let total_lines = popup.lines.len() + popup.readings.len() + popup.definitions.len();
    let width = min_width;
    let height = (total_lines.max(1) as f64) * line_h + pad * 2.0;
    let x = popup.anchor.x.max(pad);
    let y = popup.anchor.y.max(pad);

    // Background.
    fill_rgba(cr, &cfg.background_color);
    rounded_rect(cr, x, y, width, height, 6.0);
    cr.fill().ok();

    // Border.
    fill_rgba(cr, &cfg.border_color);
    rounded_rect(cr, x, y, width, height, 6.0);
    cr.set_line_width(1.0);
    cr.stroke().ok();

    // Text rows.
    let pango_ctx = pangocairo::create_context(cr).expect("pango context");
    let mut yy = y + pad;
    for chunk in &[
        popup.lines.as_slice(),
        popup.readings.as_slice(),
        popup.definitions.as_slice(),
    ] {
        for line in chunk.iter() {
            let layout = Layout::new(&pango_ctx);
            let mut font = FontDescription::from_string("Sans 11");
            if std::ptr::eq(line.as_ptr(), popup.lines.as_ptr().cast::<String>()) {
                // intentionally not; we just style uniformly
            }
            font.set_weight(pango::Weight::Bold);
            layout.set_font_description(Some(&font));
            layout.set_width(((width - pad * 2.0) * pango::SCALE as f64) as i32);
            layout.set_text(line);
            fill_rgba(cr, &cfg.foreground_color);
            cr.move_to(x + pad, yy);
            pangocairo::show_layout(cr, &layout);
            yy += line_h;
        }
    }
    let _ = RGBA::black(); // silence unused-import lint
}

fn rounded_rect(cr: &Context, x: f64, y: f64, w: f64, h: f64, r: f64) {
    cr.new_sub_path();
    cr.arc(x + w - r, y + r, r, -PI / 2.0, 0.0);
    cr.arc(x + w - r, y + h - r, r, 0.0, PI / 2.0);
    cr.arc(x + r, y + h - r, r, PI / 2.0, PI);
    cr.arc(x + r, y + r, r, PI, 1.5 * PI);
    cr.close_path();
}

pub fn line_lines(line: &Line) -> &[String] {
    // Reserved for future per-line word-wrap. Kept for symmetry with renderer hook surface.
    let _ = line;
    &[]
}

//! Region selection on GNOME.
//!
//! `slurp` doesn't work because GNOME doesn't expose `zwlr-layer-shell-v1`. So we do the
//! selection ourselves inside our fullscreen overlay:
//!
//! 1. On `scan` command: overlay enters SELECTING mode, dim background, cursor becomes
//!    crosshair, mouse press + drag captures the region, release commits.
//! 2. The picked region is what we hand to qocrd.
//!
//! For simplicity v1 uses a single button (left) press. Esc cancels.

use crate::types::Aabb;
use gtk4::gdk::Button;
use gtk4::prelude::*;
use gtk4::{EventControllerKey, EventControllerMotion, GestureDrag};
use std::cell::RefCell;
use std::rc::Rc;

/// State and wiring for in-overlay region selection.
pub struct RegionSelector {
    /// Callback invoked when the user commits a selection.
    pub on_commit: Box<dyn Fn(Aabb)>,
    /// Callback when the user cancels (Esc).
    pub on_cancel: Box<dyn Fn()>,
    /// Whether we're currently in selection mode.
    pub active: Rc<RefCell<bool>>,
    /// The in-progress drag rectangle (in screen coords).
    pub rect: Rc<RefCell<Option<Aabb>>>,
    /// Drag origin.
    pub origin: Rc<RefCell<Option<(f64, f64)>>>,
}

impl RegionSelector {
    pub fn new(
        widget: &impl IsA<gtk4::Widget>,
        on_commit: Box<dyn Fn(Aabb)>,
        on_cancel: Box<dyn Fn()>,
    ) -> Self {
        let active = Rc::new(RefCell::new(false));
        let rect = Rc::new(RefCell::new(None::<Aabb>));
        let origin = Rc::new(RefCell::new(None::<(f64, f64)>));

        // Motion: track cursor for crosshair line (optional v1: just used to refresh).
        let motion = EventControllerMotion::new();
        let rect_m = rect.clone();
        let origin_m = origin.clone();
        motion.connect_motion(move |ev, x, y| {
            if let Some((ox, oy)) = *origin_m.read() {
                let x = x.max(0.0);
                let y = y.max(0.0);
                *rect_m.borrow_mut() = Some(Aabb {
                    x: ox.min(x),
                    y: oy.min(y),
                    width: (x - ox).abs(),
                    height: (y - oy).abs(),
                });
            }
        });
        widget.add_controller(motion);

        // Drag: begin/update/end (GestureDrag fires when there's a noticeable motion).
        // For our case we use a button-press + motion instead, since GestureDrag may not
        // emit anything for a tiny movement. So we also wire Button events below.
        let gesture = GestureDrag::new();
        let rect_g = rect.clone();
        let origin_g = origin.clone();
        let active_g = active.clone();
        let on_commit_g = on_commit_for(&on_commit);
        gesture.connect_drag_begin(move |_, x, y| {
            if !*active_g.borrow() {
                return;
            }
            *origin_g.borrow_mut() = Some((x, y));
            *rect_g.borrow_mut() = Some(Aabb {
                x,
                y,
                width: 0.0,
                height: 0.0,
            });
        });
        gesture.connect_drag_end(move |_, _x, _y| {
            if !*active_g.borrow() {
                return;
            }
            let committed = rect_g.borrow_mut().take();
            *origin_g.borrow_mut() = None;
            *active_g.borrow_mut() = false;
            if let Some(r) = committed {
                if r.width > 4.0 && r.height > 4.0 {
                    on_commit_g(r);
                }
            }
        });
        widget.add_controller(gesture);

        // Esc to cancel.
        let key = EventControllerKey::new();
        let active_k = active.clone();
        let on_cancel_k = on_cancel_for(&on_cancel);
        let rect_k = rect.clone();
        let origin_k = origin.clone();
        key.connect_key_pressed(move |_, keyval, _state| {
            if keyval == gtk4::gdk::Key::Escape && *active_k.borrow() {
                *active_k.borrow_mut() = false;
                *rect_k.borrow_mut() = None;
                *origin_k.borrow_mut() = None;
                on_cancel_k();
                return gtk4::glib::Propagation::Stop;
            }
            gtk4::glib::Propagation::Proceed
        });
        widget.add_controller(key);

        Self {
            on_commit,
            on_cancel,
            active,
            rect,
            origin,
        }
    }

    pub fn begin(&self) {
        *self.active.borrow_mut() = true;
        *self.rect.borrow_mut() = None;
        *self.origin.borrow_mut() = None;
    }

    pub fn is_active(&self) -> bool {
        *self.active.borrow()
    }

    pub fn cancel(&self) {
        *self.active.borrow_mut() = false;
        *self.rect.borrow_mut() = None;
        *self.origin.borrow_mut() = None;
    }

    pub fn current_rect(&self) -> Option<Aabb> {
        self.rect.borrow().clone()
    }
}

// Helpers: clone the boxed callback into a `Box<Fn>` for use in the closures.
// (Can't move the same Box into multiple closures directly.)
fn on_commit_for(_cb: &Box<dyn Fn(Aabb)>) -> Box<dyn Fn(Aabb)> {
    // We assume the underlying closure is `Fn` (no mutable capture), so cloning is cheap.
    // The Box<dyn Fn(Aabb)> is reference-counted internally by `dyn Fn`.
    // We approximate by wrapping a `Rc<dyn Fn(Aabb)>` once at construction; this helper
    // exists only to keep that pattern in one place.
    unreachable!("replaced below with Rc-based sharing")
}

//! Region selection on GNOME.
//!
//! `slurp` doesn't work because GNOME doesn't expose `zwlr-layer-shell-v1`. So we do the
//! selection ourselves inside our fullscreen overlay:
//!
//! 1. On `scan` command: overlay enters SELECTING mode, dim background, cursor becomes
//!    crosshair, mouse press + drag captures the region, release commits.
//! 2. The picked region is what we hand to qocrd.
//!
//! For simplicity v1 uses a single button (left) press. Esc cancels.

use crate::types::Aabb;
use gtk4::gdk::Button;
use gtk4::prelude::*;
use gtk4::{EventControllerKey, EventControllerMotion, GestureClick, GestureDrag};
use std::cell::RefCell;
use std::rc::Rc;

/// State and wiring for in-overlay region selection. Construct one per overlay widget.
pub struct RegionSelector {
    /// Callback invoked when the user commits a selection (release after drag).
    on_commit: Rc<Box<dyn Fn(Aabb)>>,
    /// Callback when the user cancels (Esc).
    on_cancel: Rc<Box<dyn Fn()>>,
    /// Whether we're currently in selection mode.
    pub active: Rc<RefCell<bool>>,
    /// The in-progress drag rectangle (in widget-local coords).
    pub rect: Rc<RefCell<Option<Aabb>>>,
    /// Drag origin.
    pub origin: Rc<RefCell<Option<(f64, f64)>>>,
}

impl RegionSelector {
    pub fn new(
        widget: &impl IsA<gtk4::Widget>,
        on_commit: impl Fn(Aabb) + 'static,
        on_cancel: impl Fn() + 'static,
    ) -> Self {
        let active: Rc<RefCell<bool>> = Rc::new(RefCell::new(false));
        let rect: Rc<RefCell<Option<Aabb>>> = Rc::new(RefCell::new(None));
        let origin: Rc<RefCell<Option<(f64, f64)>>> = Rc::new(RefCell::new(None));
        let on_commit: Rc<Box<dyn Fn(Aabb)>> = Rc::new(Box::new(on_commit));
        let on_cancel: Rc<Box<dyn Fn()>> = Rc::new(Box::new(on_cancel));

        // Button-press: start a drag.
        let click = GestureClick::new();
        click.set_button(0); // any button
        let origin_c = origin.clone();
        let active_c = active.clone();
        click.connect_pressed(move |gesture, _n_press, x, y| {
            if !*active_c.borrow() {
                return;
            }
            gesture.set_state(gtk4::EventSequenceState::Claimed);
            *origin_c.borrow_mut() = Some((x, y));
        });
        let rect_c = rect.clone();
        let active_c2 = active.clone();
        click.connect_released(move |_gesture, _n_press, _x, _y| {
            // Drag-end logic happens in the Motion controller; this just clears.
            if !*active_c2.borrow() {
                return;
            }
            *origin_c.borrow_mut() = None;
        });
        widget.add_controller(click);

        // Motion: keep rect updated as cursor moves after a press.
        let motion = EventControllerMotion::new();
        let rect_m = rect.clone();
        let origin_m = origin.clone();
        let active_m = active.clone();
        let on_commit_m = on_commit.clone();
        motion.connect_motion(move |_ev, x, y| {
            if !*active_m.borrow() {
                return;
            }
            if let Some((ox, oy)) = *origin_m.read() {
                let x = x.max(0.0);
                let y = y.max(0.0);
                let rect = Aabb {
                    x: ox.min(x),
                    y: oy.min(y),
                    width: (x - ox).abs(),
                    height: (y - oy).abs(),
                };
                *rect_m.borrow_mut() = Some(rect.clone());
                // Commit on any motion past a small threshold (so a single click doesn't
                // immediately commit a zero-area rect).
                if rect.width > 4.0 && rect.height > 4.0 {
                    // Hold off committing until release; for v1 we commit immediately to
                    // keep things simple. We can add explicit release detection later.
                    *active_m.borrow_mut() = false;
                    *origin_m.borrow_mut() = None;
                    on_commit_m(rect);
                }
            }
        });
        widget.add_controller(motion);

        // Esc to cancel.
        let key = EventControllerKey::new();
        let active_k = active.clone();
        let on_cancel_k = on_cancel.clone();
        let rect_k = rect.clone();
        let origin_k = origin.clone();
        key.connect_key_pressed(move |_, keyval, _state| {
            if keyval == gtk4::gdk::Key::Escape && *active_k.borrow() {
                *active_k.borrow_mut() = false;
                *rect_k.borrow_mut() = None;
                *origin_k.borrow_mut() = None;
                on_cancel_k();
                return gtk4::glib::Propagation::Stop;
            }
            gtk4::glib::Propagation::Proceed
        });
        widget.add_controller(key);

        // Silence unused-import warnings on Button (we reference it in docs only).
        let _ = std::mem::size_of::<Button>();

        // We still keep a GestureDrag handle around so future revs can swap to a true
        // press-drag-release model if commit-on-motion feels too aggressive.
        let _drag = GestureDrag::new();
        let _active_d = active.clone();

        Self {
            on_commit,
            on_cancel,
            active,
            rect,
            origin,
        }
    }

    pub fn begin(&self) {
        *self.active.borrow_mut() = true;
        *self.rect.borrow_mut() = None;
        *self.origin.borrow_mut() = None;
    }

    pub fn cancel(&self) {
        *self.active.borrow_mut() = false;
        *self.rect.borrow_mut() = None;
        *self.origin.borrow_mut() = None;
    }

    pub fn current_rect(&self) -> Option<Aabb> {
        self.rect.borrow().clone()
    }
}

//! GTK4 overlay window: fullscreen, transparent, input-aware.
//!
//! We need to:
//! - Cover the full virtual screen so OCR boxes appear above any window.
//! - Be transparent everywhere except the drawn boxes/popups.
//! - Be input-passthrough when idle (clicks go to underlying apps), but input-aware
//!   when selection mode is active or popup is showing.
//! - Get notified of monitor geometry so we can size per-monitor windows or one
//!   spanning window covering all monitors (v1 = one spanning window).
//!
//! Implementation choice: one fullscreen window with `decorated = false`,
//! `can_focus = false` for the passive state. When selection mode is on, the overlay
//! sets focus to itself; when off, the overlay requests focus to be released.

use anyhow::Result;
use gtk4::prelude::*;
use gtk4::{Application, ApplicationWindow, CssProvider, Display, StyleContext, Window};
use std::rc::Rc;
use std::sync::Arc;

use crate::config::Config;
use crate::renderer::{self, RenderState};

/// Build a transparent fullscreen window covering all outputs.
pub fn build_window(app: &Application, config: Rc<Config>, state: Rc<RefCell<RenderState>>) -> Result<ApplicationWindow> {
    let window = ApplicationWindow::builder()
        .application(app)
        .title("gnome-ocr")
        .decorated(false)
        .resizable(false)
        .default_width(1)
        .default_height(1)
        .build();

    // Transparent background CSS.
    let provider = CssProvider::new();
    provider.load_from_string(
        r#"
        window { background-color: rgba(0,0,0,0); }
        window decoration { background-color: rgba(0,0,0,0); }
        "#,
    );
    if let Some(display) = Display::default() {
        StyleContext::add_provider_for_display(
            &display,
            &provider,
            gtk4::STYLE_PROVIDER_PRIORITY_APPLICATION,
        );
    }

    // Make window passthrough when idle: input shape mask = 0 means no events.
    // (GTK4: setting input_region via gdk is the Wayland-friendly way; we update it
    // dynamically based on `state.popup.is_some() || selector.is_active()`.)
    window.set_can_focus(false);
    window.set_focusable(false);
    window.set_accept_focus(false);

    // Determine the screen size from GdkMonitor geometry.
    if let Some(display) = window.display() {
        if let Some(monitor) = display.primary_monitor().or_else(|| display.monitors().first().map(|m| m.unwrap())) {
            let geom = monitor.geometry();
            window.set_default_size(geom.width(), geom.height());
            // We use fullscreen-on-each-monitor strategy: pick the largest monitor
            // for v1 (single fullscreen window). Real multi-monitor would create one
            // window per output.
            let _ = geom;
        }
    }

    // Per-frame draw: use a GtkDrawingArea + set_draw_func.
    let drawing = gtk4::DrawingArea::new();
    drawing.set_hexpand(true);
    drawing.set_vexpand(true);
    drawing.set_can_focus(false);
    drawing.set_focusable(false);

    let cfg_draw = config.clone();
    let state_draw = state.clone();
    drawing.set_draw_func(move |_area, cr, w, h| {
        // Draw with Cairo directly. We rely on cr's existing transform.
        // Clear to fully transparent.
        cr.set_operator(cairo::Operator::Source);
        cr.set_source_rgba(0.0, 0.0, 0.0, 0.0);
        let _ = cr.paint();

        let rs = state_draw.borrow();
        let _ = cr;
        // Re-route to renderer (which currently wants a snapshot; we call the inner logic
        // via a quick image surface for the draw-func path).
        let surface = cairo::ImageSurface::create(cairo::Format::ARgb32, w, h).unwrap();
        let ctx_surf = cairo::Context::new(&surface).unwrap();
        ctx_surf.set_operator(cairo::Operator::Source);
        ctx_surf.set_source_rgba(0.0, 0.0, 0.0, 0.0);
        let _ = ctx_surf.paint();
        for region_state in &rs.regions {
            if let Some(sel) = &rs.drag {
                renderer::draw_region_rect_for_test(
                    &ctx_surf,
                    sel,
                    &cfg_draw.region_border,
                    &cfg_draw.region_background,
                );
            } else if let Some(result) = &region_state.result {
                renderer::draw_ocr_for_test(&ctx_surf, result, &cfg_draw);
            }
        }
        if let Some(sel) = &rs.drag {
            renderer::draw_region_rect_for_test(
                &ctx_surf,
                sel,
                &cfg_draw.region_border,
                &cfg_draw.region_background,
            );
        }
        if let Some(popup) = &rs.popup {
            renderer::draw_popup_for_test(&ctx_surf, popup, &cfg_draw.yomitan);
        }
        // Blit the surface onto the drawable.
        cr.set_source_surface(&surface, 0.0, 0.0).ok();
        let _ = cr.paint();
    });

    window.set_child(Some(&drawing));

    // Fullscreen on the primary monitor. For multi-monitor, this is good enough for v1.
    window.fullscreen();

    Ok(window)
}

use std::cell::RefCell;

/// Compute the desired input region shape (gtk4 wants a single list of rectangles).
/// Empty list = no input → clicks pass through to underlying apps.
pub fn input_shape_empty() -> gtk4::gdk::Rectangle {
    // Width/height 0 = compositor treats as input-transparent in most Wayland compositors.
    gtk4::gdk::Rectangle::new(0, 0, 0, 0)
}

//! Cairo/Pango renderer for OCR boxes + region rectangles + Yomitan popups.
//!
//! Each function takes a Cairo `Context` and draws directly onto it. The GTK4 overlay
//! hooks `GtkDrawingArea::set_draw_func` and calls into here.
//!
//! Why not WebKit2GTK for the popup: Yomitan's HTML popup requires JS execution + CSS that
//! we don't need for v1. Rendering the JSON fields directly with Pango is faster, lighter,
//! and easier to style consistently with the rest of the overlay.

use cairo::{Context, Format, ImageSurface};
use pango::{FontDescription, Layout};
use std::f64::consts::PI;

use crate::config::{Config, YomitanConfig};
use crate::types::{Aabb, Line, OcrResult, Point};

pub struct RenderState {
    pub regions: Vec<RegionState>,
    pub drag: Option<Aabb>,
    pub popup: Option<PopupState>,
}

pub struct RegionState {
    pub monitor: String,
    pub result: Option<OcrResult>,
    pub flash_until: Option<std::time::Instant>,
}

#[derive(Debug, Clone)]
pub struct PopupState {
    pub anchor: Point,
    pub lines: Vec<String>,
    pub readings: Vec<String>,
    pub definitions: Vec<String>,
}

impl RenderState {
    pub fn new() -> Self {
        Self {
            regions: Vec::new(),
            drag: None,
            popup: None,
        }
    }
}

fn parse_hex(s: &str) -> Option<(f64, f64, f64, f64)> {
    let s = s.trim_start_matches('#');
    let (r, g, b, a) = match s.len() {
        6 => (
            u8::from_str_radix(&s[0..2], 16).ok()?,
            u8::from_str_radix(&s[2..4], 16).ok()?,
            u8::from_str_radix(&s[4..6], 16).ok()?,
            255u8,
        ),
        8 => (
            u8::from_str_radix(&s[0..2], 16).ok()?,
            u8::from_str_radix(&s[2..4], 16).ok()?,
            u8::from_str_radix(&s[4..6], 16).ok()?,
            u8::from_str_radix(&s[6..8], 16).ok()?,
        ),
        _ => return None,
    };
    Some((r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0, a as f64 / 255.0))
}

fn fill_rgba(cr: &Context, hex: &str) {
    if let Some((r, g, b, a)) = parse_hex(hex) {
        cr.set_source_rgba(r, g, b, a);
    } else {
        cr.set_source_rgba(1.0, 0.0, 0.0, 0.5);
    }
}

/// Top-level draw function: walks all regions and renders them. Used by overlay.rs's
/// `GtkDrawingArea::set_draw_func`.
pub fn draw_state(cr: &Context, width: i32, height: i32, state: &RenderState, config: &Config) {
    // Clear to fully transparent.
    cr.set_operator(cairo::Operator::Source);
    cr.set_source_rgba(0.0, 0.0, 0.0, 0.0);
    cr.paint().ok();
    cr.set_operator(cairo::Operator::Over);

    for region_state in &state.regions {
        if let Some(sel) = &state.drag {
            draw_region_rect(cr, sel, &config.region_border, &config.region_background);
        } else if let Some(result) = &region_state.result {
            draw_ocr_result(cr, result, config);
        }
    }
    if let Some(sel) = &state.drag {
        draw_region_rect(cr, sel, &config.region_border, &config.region_background);
    }
    if let Some(popup) = &state.popup {
        draw_popup(cr, popup, &config.yomitan);
    }
    let _ = (width, height);
}

pub fn draw_region_rect(cr: &Context, rect: &Aabb, border_hex: &str, bg_hex: &str) {
    fill_rgba(cr, bg_hex);
    cr.rectangle(rect.x, rect.y, rect.width, rect.height);
    cr.fill().ok();
    fill_rgba(cr, border_hex);
    cr.set_line_width(2.0);
    cr.rectangle(rect.x, rect.y, rect.width, rect.height);
    cr.stroke().ok();
}

pub fn draw_ocr_result(cr: &Context, result: &OcrResult, config: &Config) {
    let margin = config.box_margin as f64;
    let region_x = result.region.x as f64;
    let region_y = result.region.y as f64;

    for line in &result.lines {
        let padded = Aabb {
            x: line.aabb.x - margin,
            y: line.aabb.y - margin,
            width: line.aabb.width + margin * 2.0,
            height: line.aabb.height + margin * 2.0,
        };
        fill_rgba(cr, &config.background);
        cr.rectangle(padded.x, padded.y, padded.width, padded.height);
        cr.fill().ok();

        fill_rgba(cr, &config.border_color);
        cr.set_line_width(config.border as f64);
        cr.rectangle(padded.x, padded.y, padded.width, padded.height);
        cr.stroke().ok();

        // Per-symbol faint boxes (debug-visible).
        for word in &line.words {
            for sym in &word.symbols {
                let sb = sym.aabb;
                fill_rgba(cr, "#20d0d0d0");
                cr.rectangle(sb.x, sb.y, sb.width, sb.height);
                cr.fill().ok();
            }
        }

        if config.show_overlay {
            draw_text(
                cr,
                &line.text,
                line.aabb.x,
                line.aabb.y + line.aabb.height * 0.85,
                line.aabb.width,
                &config.border_color,
            );
        }
        let _ = line;
    }

    let region_rect = Aabb {
        x: region_x,
        y: region_y,
        width: result.region.w as f64,
        height: result.region.h as f64,
    };
    draw_region_rect(cr, &region_rect, &config.region_border, &config.region_background);
}

fn draw_text(cr: &Context, text: &str, x: f64, y: f64, width: f64, color: &str) {
    if text.is_empty() {
        return;
    }
    let pango_ctx = pangocairo::create_context(cr).expect("pango context");
    let layout = Layout::new(&pango_ctx);
    let mut font = FontDescription::from_string("Sans 11");
    font.set_weight(pango::Weight::Bold);
    layout.set_font_description(Some(&font));
    layout.set_width((width.max(1.0) * pango::SCALE as f64) as i32);
    layout.set_text(text);
    fill_rgba(cr, color);
    cr.move_to(x, y);
    pangocairo::show_layout(cr, &layout);
}

pub fn draw_popup(cr: &Context, popup: &PopupState, cfg: &YomitanConfig) {
    let pad = 12.0;
    let line_h = 22.0;
    let min_width = 280.0;
    let total_lines = popup.lines.len() + popup.readings.len() + popup.definitions.len();
    let width = min_width;
    let height = (total_lines.max(1) as f64) * line_h + pad * 2.0;
    let x = popup.anchor.x.max(pad);
    let y = popup.anchor.y.max(pad);

    fill_rgba(cr, &cfg.background_color);
    rounded_rect(cr, x, y, width, height, 6.0);
    cr.fill().ok();

    fill_rgba(cr, &cfg.border_color);
    rounded_rect(cr, x, y, width, height, 6.0);
    cr.set_line_width(1.0);
    cr.stroke().ok();

    let pango_ctx = pangocairo::create_context(cr).expect("pango context");
    let mut yy = y + pad;
    for chunk in [&popup.lines, &popup.readings, &popup.definitions] {
        for line in chunk.iter() {
            let layout = Layout::new(&pango_ctx);
            let mut font = FontDescription::from_string("Sans 11");
            font.set_weight(pango::Weight::Bold);
            layout.set_font_description(Some(&font));
            layout.set_width(((width - pad * 2.0) * pango::SCALE as f64) as i32);
            layout.set_text(line);
            fill_rgba(cr, &cfg.foreground_color);
            cr.move_to(x + pad, yy);
            pangocairo::show_layout(cr, &layout);
            yy += line_h;
        }
    }
}

fn rounded_rect(cr: &Context, x: f64, y: f64, w: f64, h: f64, r: f64) {
    cr.new_sub_path();
    cr.arc(x + w - r, y + r, r, -PI / 2.0, 0.0);
    cr.arc(x + w - r, y + h - r, r, 0.0, PI / 2.0);
    cr.arc(x + r, y + h - r, r, PI / 2.0, PI);
    cr.arc(x + r, y + r, r, PI, 1.5 * PI);
    cr.close_path();
}

/// Convenience: render the whole state onto an ImageSurface the given size, return it.
pub fn render_to_surface(
    width: i32,
    height: i32,
    state: &RenderState,
    config: &Config,
) -> ImageSurface {
    let surface = ImageSurface::create(Format::ARgb32, width, height).expect("ImageSurface");
    let cr = Context::new(&surface).expect("cairo Context");
    draw_state(&cr, width, height, state, config);
    surface
}

/// Helper for callers that need a hex-string -> (r,g,b,a) tuple.
pub fn rgba(hex: &str) -> (f64, f64, f64, f64) {
    parse_hex(hex).unwrap_or((1.0, 0.0, 1.0, 0.5))
}

#[allow(dead_code)]
pub fn _unused_line(_line: &Line) {}

//! GTK4 overlay window: fullscreen, transparent, input-aware.
//!
//! We need to:
//! - Cover the full virtual screen so OCR boxes appear above any window.
//! - Be transparent everywhere except the drawn boxes/popups.
//! - Be input-passthrough when idle (clicks go to underlying apps), but input-aware
//!   when selection mode is active or popup is showing.
//!
//! Implementation choice: one fullscreen window with `decorated = false`, `can_focus = false`,
//! rendered via a child `GtkDrawingArea`. Pass-through is achieved by setting the window
//! to not accept input by default (clicks fall through to whatever is underneath).

use gtk4::prelude::*;
use gtk4::{Application, ApplicationWindow, CssProvider, Display, StyleContext};
use std::cell::RefCell;
use std::rc::Rc;

use crate::config::Config;
use crate::renderer::{self, RenderState};

pub fn build_window(
    app: &Application,
    config: Rc<Config>,
    state: Rc<RefCell<RenderState>>,
) -> ApplicationWindow {
    let window = ApplicationWindow::builder()
        .application(app)
        .title("gnome-ocr")
        .decorated(false)
        .resizable(false)
        .default_width(1)
        .default_height(1)
        .build();

    // Transparent background CSS.
    let provider = CssProvider::new();
    provider.load_from_string(
        r#"
        window { background-color: rgba(0,0,0,0); }
        window decoration { background-color: rgba(0,0,0,0); }
        "#,
    );
    if let Some(display) = Display::default() {
        StyleContext::add_provider_for_display(
            &display,
            &provider,
            gtk4::STYLE_PROVIDER_PRIORITY_APPLICATION,
        );
    }

    window.set_can_focus(false);
    window.set_focusable(false);
    window.set_accept_focus(false);

    let drawing = gtk4::DrawingArea::new();
    drawing.set_hexpand(true);
    drawing.set_vexpand(true);
    drawing.set_can_focus(false);
    drawing.set_focusable(false);

    let cfg_draw = config.clone();
    let state_draw = state.clone();
    drawing.set_draw_func(move |_area, cr, w, h| {
        let rs = state_draw.borrow();
        renderer::draw_state(cr, w, h, &rs, &cfg_draw);
    });

    window.set_child(Some(&drawing));

    // Set window to fullscreen. GdkScreen size determines the actual rect.
    if let Some(display) = window.display() {
        if let Some(monitor) = display.primary_monitor() {
            window.fullscreen_on_monitor(&monitor);
        } else {
            window.fullscreen();
        }
    } else {
        window.fullscreen();
    }

    window
}

//! Main entry point. Sets up the GTK application, owns the qocrd subprocess, the IPC
//! server, the Yomitan + Anki clients, and the state machine that ties them together.

mod anki;
mod config;
mod daemon;
mod ipc;
mod overlay;
mod region_select;
mod renderer;
mod types;
mod yomitan;

use anyhow::{Context, Result};
use gtk4::prelude::*;
use gtk4::{glib, Application};
use std::cell::RefCell;
use std::rc::Rc;
use tokio::sync::mpsc as tmpsc;
use tracing_subscriber::EnvFilter;

use crate::config::Config;
use crate::daemon::{read_loop, DaemonEvent, OcrDaemon};
use crate::ipc::socket_path;
use crate::renderer::{PopupState, RegionState, RenderState};
use crate::types::{Command, OcrResult, Point};

const APP_ID: &str = "dev.local.gnome-ocr";

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
        .init();

    // Tokio runtime on a dedicated thread so the GTK main loop stays on the main thread.
    let rt = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(2)
        .enable_all()
        .build()
        .context("tokio runtime")?;
    let _rt_guard = rt.enter();

    // Config (in a thread-safe wrapper so GTK + tokio can both read).
    let config = Rc::new(Config::load().unwrap_or_else(|e| {
        tracing::warn!("config load failed: {e}; using defaults");
        Config::default()
    }));

    // Build channels: GTK-thread state machine ↔ tokio tasks.
    let (cmd_tx, mut cmd_rx) = tmpsc::channel::<Command>(64);
    let (event_tx, mut event_rx) = tmpsc::channel::<DaemonEvent>(64);

    // Spawn the IPC server on the tokio runtime.
    let ipc_path = socket_path().context("socket path")?;
    let ipc_tx = cmd_tx.clone();
    let ipc_handle = rt.spawn(async move {
        if let Err(e) = ipc::serve(ipc_path, ipc_tx).await {
            tracing::error!("IPC server: {e}");
        }
    });

    // Spawn qocrd + read loop.
    let daemon_tx = event_tx.clone();
    let mut daemon_handle: RtHandle = rt.spawn(async move {
        let mut daemon = match OcrDaemon::spawn().await {
            Ok(d) => d,
            Err(e) => {
                tracing::error!("spawn qocrd: {e}");
                return;
            }
        };
        let stdout = match daemon.take_stdout() {
            Some(s) => s,
            None => return,
        };
        if let Err(e) = read_loop(stdout, daemon_tx).await {
            tracing::error!("qocrd read loop: {e}");
        }
    });

    // GTK application.
    let app = Application::builder().application_id(APP_ID).build();
    let state = Rc::new(RefCell::new(RenderState::new()));
    let cmd_tx_app = cmd_tx.clone();
    let config_for_app = config.clone();

    app.connect_activate(move |app| {
        let window = overlay::build_window(app, config_for_app.clone(), state.clone());
        window.present();

        // Drain DaemonEvents and update state.
        let state_drain = state.clone();
        glib::timeout_add_local(std::time::Duration::from_millis(100), move || {
            while let Ok(event) = event_rx.try_recv() {
                match event {
                    DaemonEvent::Result(result) => {
                        let mut s = state_drain.borrow_mut();
                        let monitor = result.monitor.clone();
                        // Replace the result for this monitor, or add a new region state.
                        if let Some(rs) = s.regions.iter_mut().find(|r| r.monitor == monitor) {
                            rs.result = Some(result);
                        } else {
                            s.regions.push(RegionState {
                                monitor,
                                result: Some(result),
                                flash_until: None,
                            });
                        }
                    }
                    DaemonEvent::Unchanged => {
                        // No visible change — request a redraw anyway in case state mutated.
                    }
                }
            }
            glib::ControlFlow::Continue
        });

        // Drain Commands from IPC and dispatch.
        let state_cmd = state.clone();
        let yomitan_url = config_for_app.yomitan.api_url.clone();
        let anki_url = config_for_app.anki.anki_connect_url.clone();
        let anki_enabled = config_for_app.anki.enable;
        let anki_deck = config_for_app.anki.deck.clone();
        let anki_model = config_for_app.anki.model.clone();
        let anki_tags = config_for_app.anki.tags.clone();
        let anki_allow_dup = config_for_app.anki.allow_duplicate;
        let anki_fields = config_for_app.anki.fields.clone();
        let japanese_only = config_for_app.japanese_only;

        glib::timeout_add_local(std::time::Duration::from_millis(50), move || {
            while let Ok(cmd) = cmd_rx.try_recv() {
                dispatch_command(
                    cmd,
                    &state_cmd,
                    cmd_tx_app.clone(),
                    &yomitan_url,
                    &anki_url,
                    anki_enabled,
                    &anki_deck,
                    &anki_model,
                    &anki_tags,
                    anki_allow_dup,
                    &anki_fields,
                    japanese_only,
                );
            }
            glib::ControlFlow::Continue
        });
    });

    // Hold these so they don't drop.
    std::mem::forget(ipc_handle);
    std::mem::forget(daemon_handle);

    app.run();
    Ok(())
}

type RtHandle = tokio::task::JoinHandle<()>;

#[allow(clippy::too_many_arguments)]
fn dispatch_command(
    cmd: Command,
    state: &Rc<RefCell<RenderState>>,
    cmd_tx: tmpsc::Sender<Command>,
    yomitan_url: &str,
    anki_url: &str,
    anki_enabled: bool,
    anki_deck: &str,
    anki_model: &str,
    anki_tags: &[String],
    anki_allow_dup: bool,
    anki_fields: &std::collections::HashMap<String, String>,
    japanese_only: bool,
) {
    match cmd {
        Command::Scan { japanese, fullscreen } => {
            tracing::info!("scan japanese={japanese} fullscreen={fullscreen}");
            // We'll dispatch this to qocrd via a small bridge: the GTK side doesn't hold
            // the daemon directly. Use the same channel to send a "do scan" message that
            // a dedicated tokio task forwards to the daemon.
            // For v1 we keep it simple: spawn a tokio task that talks to qocrd.
            let url = yomitan_url.to_string();
            tokio::spawn(async move {
                run_scan(japanese, fullscreen, url, state.clone()).await;
            });
        }
        Command::Rescan => {
            tracing::info!("rescan");
            // Re-OCR all tracked regions using the latest config.japanese_only.
            let _ = japanese_only;
            // We could iterate `state.regions` and call daemon.rescan(...). Deferred to v1.
        }
        Command::ClearOverlay => {
            let mut s = state.borrow_mut();
            for r in &mut s.regions {
                if let Some(ref mut result) = r.result {
                    result.lines.clear();
                }
            }
        }
        Command::ClearAll => {
            state.borrow_mut().regions.clear();
            state.borrow_mut().popup = None;
        }
        Command::ShowRegion => {
            let mut s = state.borrow_mut();
            let now = std::time::Instant::now();
            for r in &mut s.regions {
                r.flash_until = Some(now + std::time::Duration::from_millis(1500));
            }
        }
        Command::TriggerPopup { x, y, monitor } => {
            tracing::info!("trigger popup at ({x},{y}) on {monitor}");
            let url = yomitan_url.to_string();
            let anki_url = anki_url.to_string();
            let anki_enabled = anki_enabled;
            let anki_deck = anki_deck.to_string();
            let anki_model = anki_model.to_string();
            let anki_tags = anki_tags.to_vec();
            let anki_allow_dup = anki_allow_dup;
            let anki_fields = anki_fields.clone();
            let state_clone = state.clone();
            tokio::spawn(async move {
                run_popup(
                    state_clone,
                    url,
                    anki_url,
                    anki_enabled,
                    anki_deck,
                    anki_model,
                    anki_tags,
                    anki_allow_dup,
                    anki_fields,
                    x as f64,
                    y as f64,
                )
                .await;
            });
        }
        Command::HoverOn | Command::HoverOff => {
            // Hooked up in v2; v1 ignores.
        }
        Command::ToggleConfig { key } => {
            tracing::info!("toggle config {key} (unimplemented)");
        }
        Command::GetConfig { key } => {
            tracing::info!("get config {key} (unimplemented)");
        }
    }
    let _ = cmd_tx; // currently unused; future use for get_config replies
}

/// Run a scan: ask qocrd to scan, then update state with the result.
async fn run_scan(
    japanese: bool,
    fullscreen: bool,
    _yomitan_url: String,
    state: Rc<RefCell<RenderState>>,
) {
    let mut daemon = match OcrDaemon::spawn().await {
        Ok(d) => d,
        Err(e) => {
            tracing::error!("spawn qocrd for scan: {e}");
            return;
        }
    };
    if let Err(e) = daemon.scan(japanese, fullscreen).await {
        tracing::error!("scan: {e}");
        return;
    }
    let stdout = match daemon.take_stdout() {
        Some(s) => s,
        None => return,
    };
    let (tx, mut rx) = tmpsc::channel::<DaemonEvent>(4);
    tokio::spawn(async move {
        let _ = read_loop(stdout, tx).await;
    });
    // We only care about the first non-unchanged result for a single scan.
    while let Some(ev) = rx.recv().await {
        match ev {
            DaemonEvent::Result(result) => {
                let mut s = state.borrow_mut();
                let monitor = result.monitor.clone();
                if let Some(rs) = s.regions.iter_mut().find(|r| r.monitor == monitor) {
                    rs.result = Some(result);
                } else {
                    s.regions.push(RegionState {
                        monitor,
                        result: Some(result),
                        flash_until: None,
                    });
                }
                break;
            }
            DaemonEvent::Unchanged => continue,
        }
    }
    daemon.kill();
}

#[allow(clippy::too_many_arguments)]
async fn run_popup(
    state: Rc<RefCell<RenderState>>,
    yomitan_url: String,
    anki_url: String,
    anki_enabled: bool,
    anki_deck: String,
    anki_model: String,
    anki_tags: Vec<String>,
    anki_allow_dup: bool,
    anki_fields: std::collections::HashMap<String, String>,
    x: f64,
    y: f64,
) {
    let mut yc = yomitan::YomitanClient::new(&yomitan_url);
    // Use the most-recent OCR region's text near (x,y) as the term. For v1 we just take
    // the closest line's text.
    let term: Option<String> = {
        let s = state.borrow();
        s.regions
            .iter()
            .filter_map(|r| r.result.as_ref())
            .flat_map(|r: &OcrResult| r.lines.iter())
            .min_by(|a, b| {
                let da = ((a.aabb.x + a.aabb.width / 2.0) - x).powi(2)
                    + ((a.aabb.y + a.aabb.height / 2.0) - y).powi(2);
                let db = ((b.aabb.x + b.aabb.width / 2.0) - x).powi(2)
                    + ((b.aabb.y + b.aabb.height / 2.0) - y).powi(2);
                da.partial_cmp(&db).unwrap_or(std::cmp::Ordering::Equal)
            })
            .map(|l| l.text.clone())
    };
    let Some(term) = term else {
        tracing::info!("popup: no OCR text near ({x},{y})");
        return;
    };
    let reply = match yc.lookup(&term).await {
        Ok(r) => r,
        Err(e) => {
            tracing::warn!("yomitan lookup: {e}");
            // Yomitan likely not running. Show a "no lookup" popup anyway.
            let mut s = state.borrow_mut();
            s.popup = Some(PopupState {
                anchor: Point { x, y },
                lines: vec![term],
                readings: vec!["(yomitan-api unreachable)".into()],
                definitions: vec![format!("{e}")],
            });
            return;
        }
    };
    let entry = match reply {
        yomitan::LookupReply::Multi(v) => v.into_iter().flatten().next(),
        yomitan::LookupReply::Single(v) => v.into_iter().next(),
    };
    let (lines, readings, definitions) = match entry {
        Some(e) => {
            let lines = vec![e.expression.clone()];
            let readings = vec![e.reading.clone()];
            // Render a few definitions compactly.
            let mut defs = Vec::new();
            for (i, d) in e.glossary.iter().take(8).enumerate() {
                defs.push(format!("{}. {}", i + 1, d));
            }
            if defs.is_empty() {
                defs.push("(no definitions)".into());
            }
            (lines, readings, defs)
        }
        None => (vec![term.clone()], vec!["—".into()], vec!["(no entry)".into()]),
    };
    {
        let mut s = state.borrow_mut();
        s.popup = Some(PopupState {
            anchor: Point { x, y },
            lines,
            readings,
            definitions,
        });
    }

    // Optional Anki mining: only fire if user requested via a future IPC; for now, the
    // popup contains a "+" affordance is TBD. We keep anki config warm so it's ready.
    let _ = (&anki_url, anki_enabled, anki_deck, anki_model, anki_tags, anki_allow_dup, anki_fields);
}

//! CLI client that sends one command to the running `gnome-ocr` daemon and prints the reply.
//!
//! Usage: `gnome-ocr-cli scan`, `gnome-ocr-cli rescan`, `gnome-ocr-cli clear_all`, etc.
//!
//! Implemented as a separate binary (`gnome-ocr-cli`) so the daemon binary stays minimal.

use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use serde_json::json;
use tokio::sync::mpsc as tmpsc;

mod types;

use crate::types::Command;

#[derive(Debug, Parser)]
#[command(name = "gnome-ocr-cli", about = "Send IPC commands to gnome-ocr daemon")]
struct Cli {
    #[command(subcommand)]
    cmd: Cmd,
}

#[derive(Debug, Subcommand)]
enum Cmd {
    /// Begin a region-select drag, then OCR the picked region.
    Scan {
        #[arg(long, default_value_t = true)]
        japanese: bool,
        #[arg(long, default_value_t = false)]
        fullscreen: bool,
    },
    Rescan,
    ClearOverlay,
    ClearAll,
    ShowRegion,
    TriggerPopup {
        x: i32,
        y: i32,
        monitor: String,
    },
    HoverOn,
    HoverOff,
    ToggleConfig { key: String },
    GetConfig { key: String },
}

impl Cmd {
    fn into_command(self) -> Command {
        match self {
            Cmd::Scan { japanese, fullscreen } => Command::Scan { japanese, fullscreen },
            Cmd::Rescan => Command::Rescan,
            Cmd::ClearOverlay => Command::ClearOverlay,
            Cmd::ClearAll => Command::ClearAll,
            Cmd::ShowRegion => Command::ShowRegion,
            Cmd::TriggerPopup { x, y, monitor } => Command::TriggerPopup { x, y, monitor },
            Cmd::HoverOn => Command::HoverOn,
            Cmd::HoverOff => Command::HoverOff,
            Cmd::ToggleConfig { key } => Command::ToggleConfig { key },
            Cmd::GetConfig { key } => Command::GetConfig { key },
        }
    }
}

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    let cmd = cli.cmd.into_command();
    let path = ipc_path()?;
    let (tx, mut rx) = tmpsc::channel(1);
    ipc::send(path, &cmd).await?;
    let _ = tx;
    let _ = rx;
    // Reconstruct pretty reply printout from the raw shape we sent.
    // (We don't actually need the Reply here for the simple ACK; print JSON echo.)
    println!("{}", json!({ "sent": format!("{cmd:?}") }));
    Ok(())
}

fn ipc_path() -> Result<std::path::PathBuf> {
    let runtime = std::env::var_os("XDG_RUNTIME_DIR")
        .map(std::path::PathBuf::from)
        .or_else(|| dirs::runtime_dir())
        .context("no XDG_RUNTIME_DIR")?;
    Ok(runtime.join("gnome-ocr.sock"))
}

// Stub module imports so this standalone bin compiles. We only need `types` for the
// Command enum. We embed a minimal ipc::send here too, to avoid duplicating code across
// binaries (and avoid pulling in tokio at the daemon binary level from the CLI side).
mod ipc {
    use anyhow::{Context, Result};
    use std::path::PathBuf;
    use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
    use tokio::net::UnixStream;

    use super::types::Command;

    pub async fn send(path: PathBuf, cmd: &Command) -> Result<()> {
        let stream = UnixStream::connect(&path)
            .await
            .with_context(|| format!("connect {}", path.display()))?;
        let (read, mut write) = stream.into_split();
        let payload = serde_json::to_string(cmd)?;
        write.write_all(payload.as_bytes()).await?;
        write.write_all(b"\n").await?;
        write.shutdown().await?;
        let mut reader = BufReader::new(read).lines();
        let mut line = String::new();
        reader.read_line(&mut line).await?;
        println!("{}", line.trim());
        Ok(())
    }
}

//! CLI client. Separate binary `gnome-ocr-cli` that sends IPC commands to the daemon.
//! Shares modules with the daemon binary (single crate).

use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use serde_json::json;
use tokio::sync::mpsc as tmpsc;

mod ipc;
mod types;

use crate::ipc::socket_path;
use crate::types::Command;

#[derive(Debug, Parser)]
#[command(name = "gnome-ocr-cli", about = "Send IPC commands to gnome-ocr daemon")]
struct Cli {
    #[command(subcommand)]
    cmd: Cmd,
}

#[derive(Debug, Subcommand)]
enum Cmd {
    /// Begin a region-select drag, then OCR the picked region.
    Scan {
        #[arg(long, default_value_t = true)]
        japanese: bool,
        #[arg(long, default_value_t = false)]
        fullscreen: bool,
    },
    Rescan,
    ClearOverlay,
    ClearAll,
    ShowRegion,
    TriggerPopup { x: i32, y: i32, monitor: String },
    HoverOn,
    HoverOff,
    ToggleConfig { key: String },
    GetConfig { key: String },
}

impl Cmd {
    fn into_command(self) -> Command {
        match self {
            Cmd::Scan { japanese, fullscreen } => Command::Scan { japanese, fullscreen },
            Cmd::Rescan => Command::Rescan,
            Cmd::ClearOverlay => Command::ClearOverlay,
            Cmd::ClearAll => Command::ClearAll,
            Cmd::ShowRegion => Command::ShowRegion,
            Cmd::TriggerPopup { x, y, monitor } => Command::TriggerPopup { x, y, monitor },
            Cmd::HoverOn => Command::HoverOn,
            Cmd::HoverOff => Command::HoverOff,
            Cmd::ToggleConfig { key } => Command::ToggleConfig { key },
            Cmd::GetConfig { key } => Command::GetConfig { key },
        }
    }
}

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    let cmd = cli.cmd.into_command();
    let path = socket_path().context("socket path")?;
    let (_tx, _rx) = tmpsc::channel::<()>(1);
    let reply = ipc::send(path, &cmd).await?;
    println!("{}", json!({ "ok": reply.ok, "message": reply.message }));
    Ok(())
}

