pub fn new(
    widget: &impl IsA<gtk::Widget>,
    on_commit: impl Fn(Aabb) + 'static,
    on_cancel: impl Fn() + 'static,
) -> Self {
    let active: Rc<RefCell<bool>> = Rc::new(RefCell::new(false));
    let rect: Rc<RefCell<Option<Aabb>>> = Rc::new(RefCell::new(None));
    let origin: Rc<RefCell<Option<(f64, f64)>>> = Rc::new(RefCell::new(None));
    let on_commit: Rc<Box<dyn Fn(Aabb)>> = Rc::new(Box::new(on_commit));
    let on_cancel: Rc<Box<dyn Fn()>> = Rc::new(Box::new(on_cancel));

    // Button-press: start a drag.
    let click = GestureClick::new();
    click.set_button(0); // any button
    let origin_c = origin.clone();
    let active_c = active.clone();
    click.connect_pressed(move |gesture, _n_press, x, y| {
        if !*active_c.borrow() {
            return;
        }
        gesture.set_state(gtk::EventSequenceState::Claimed);
        *origin_c.borrow_mut() = Some((x, y));
    });
    let rect_c = rect.clone();
    let active_c2 = active.clone();
    click.connect_released(move |_gesture, _n_press, _x, _y| {
