// Fullscreen on the first available monitor. gtk-rs 0.11 dropped `primary_monitor`
    // in favor of `monitor_at_surface` / `monitors()`; for v1 we just fullscreen
    // (which Mutter will route to the active monitor).
    if let Some(display) = gdk::Display::default() {
        let monitors = display.monitors();
        // Pick the first monitor (if any) so fullscreen_on_monitor can target it;
        // otherwise fall back to whole-display fullscreen.
        if let Some(monitor_obj) = monitors.first() {
            if let Ok(monitor) = monitor_obj.downcast::<gdk::Monitor>() {
                window.fullscreen_on_monitor(&monitor);
                return;
            }
        }
    }
    window.fullscreen();

