## Recommended `src/overlay.rs` (full rewrite)

```rust
//! GTK4 overlay: fullscreen, transparent, click-through by default.
//!
//! Pattern: z13gui. Uses wl_surface::set_input_region (core Wayland protocol —
//! works on Mutter, no zwlr_layer_shell_v1 needed). Translucent RGBA surface
//! is GTK4 Wayland's default; we only need one CSS rule + an empty input region
//! in connect_realize.

use std::rc::Rc;
use std::sync::{Arc, Mutex};

use cairo::Region;
use gdk::prelude::*;
use gtk::prelude::*;
use gtk::{gdk, Application, ApplicationWindow, CssProvider};

use crate::config::Config;
use crate::renderer::{self, RenderState};

pub struct Overlay {
    pub window: ApplicationWindow,
    state: Arc<Mutex<RenderState>>,
}

impl Overlay {
    pub fn build(app: &Application, config: Rc<Config>, state: Arc<Mutex<RenderState>>) -> Self {
        // 1. CSS: one rule. window { background: transparent } matches GtkWindow's
        //    CSS node (GTK4 sets css-name "window" on GtkWindow). Nothing else.
        let provider = CssProvider::new();
        provider.load_from_string("window { background: transparent; }");
        if let Some(display) = gdk::Display::default() {
            gtk::style_context_add_provider_for_display(
                &display,
                &provider,
                gtk::STYLE_PROVIDER_PRIORITY_APPLICATION,
            );
        }

        // 2. Window: undecorated, non-resizable, NOT focusable (clicks must pass
        //    through by default), but accepting input in the painted regions later.
        let window = ApplicationWindow::builder()
            .application(app)
            .title("gnome-ocr")
            .decorated(false)
            .resizable(false)
            .can_focus(false)
            .focusable(false)
            .default_width(1)
            .default_height(1)
            .build();

        // 3. Drawing area: the only widget that paints. draw_func clears to
        //    rgba(0,0,0,0) then draws OCR boxes / popups.
        let drawing = gtk::DrawingArea::new();
        drawing.set_hexpand(true);
        drawing.set_vexpand(true);
        drawing.set_can_focus(false);

        let cfg = config.clone();
        let st = state.clone();
        drawing.set_draw_func(move |_area, cr, w, h| {
            let rs = st.lock().expect("state mutex");
            renderer::draw_state(cr, w, h, &rs, &cfg);
        });
        window.set_child(Some(&drawing));

        // 4. Fullscreen — required. Without it, Mutter may not honor the surface
        //    extent for input region / damage tracking, and the window won't
        //    cover the monitor. z13gui uses fullscreen() and it works.
        //    Pick the primary monitor explicitly to handle multi-monitor.
        let fullscreen_monitor = gdk::Display::default()
            .and_then(|d| d.monitors().item(0u32))
            .and_then(|m| m.downcast::<gdk::Monitor>().ok());
        if let Some(monitor) = fullscreen_monitor {
            window.fullscreen_on_monitor(&monitor);
        } else {
            window.fullscreen();
        }

        // 5. Empty input region = click-through (Mutter passes events to windows
        //    below). After realize, when OCR boxes / a popup exist, call
        //    overlay.update_input_region(Some(rects)) to capture those rects.
        let state_for_input = state.clone();
        window.connect_realize(move |w| {
            if let Some(surface) = w.surface() {
                // Empty region = pass all input through.
                surface.set_input_region(Some(&Region::create()));
            }
            // Re-apply region whenever state changes — draw_func triggers
            // surface invalidation, and we piggy-back on a glib idle to push
            // the current input region. Lightweight: just a few rect ops.
            let w_weak = w.downgrade();
            let st = state_for_input.clone();
            glib::idle_add_local(move || {
                let Some(w) = w_weak.upgrade() else { return glib::ControlFlow::Break; };
                let Some(surface) = w.surface() else { return glib::ControlFlow::Continue; };
                let region = compute_input_region(&st.lock().expect("state mutex"));
                surface.set_input_region(if region.is_empty() {
                    Some(&Region::create())
                } else {
                    Some(&region)
                });
                glib::ControlFlow::Continue
            });
        });

        Self { window, state }
    }

    /// Push a custom input region. Pass None to revert to full click-through.
    pub fn set_input_rects(&self, rects: &[gdk::Rectangle]) {
        let Some(surface) = self.window.surface() else { return };
        if rects.is_empty() {
            surface.set_input_region(Some(&Region::create()));
            return;
        }
        let region = Region::create();
        for r in rects {
            let ri = cairo::RectangleInt {
                x: r.x(),
                y: r.y(),
                width: r.width(),
                height: r.height(),
            };
            let _ = region.union_rectangle(&ri);
        }
        surface.set_input_region(Some(&region));
    }
}

/// Compute the input region from current render state: union of all visible
/// OCR box rects + popup rect, in monitor-local coordinates. Empty when idle.
fn compute_input_region(state: &RenderState) -> Region {
    let region = Region::create();
    for rs in &state.regions {
        if let Some(result) = &rs.result {
            let ri = cairo::RectangleInt {
                x: result.region.x as i32,
                y: result.region.y as i32,
                width: result.region.w as i32,
                height: result.region.h as i32,
            };
            let _ = region.union_rectangle(&ri);
        }
    }
    if let Some(popup) = &state.popup {
        let ri = cairo::RectangleInt {
            x: popup.anchor.x as i32,
            y: popup.anchor.y as i32,
            width: 300, // matches renderer::draw_popup min_width
            height: 22 * (popup.lines.len() + popup.readings.len() + popup.definitions.len()) as i32 + 32,
        };
        let _ = region.union_rectangle(&ri);
    }
    region
}
```

