```rust
//! Minimal reproducible: a fullscreen red rectangle that is click-through.
//! Run: cargo run --example transparent_smoke
//! Exit: Ctrl+C in the terminal that launched it.
//! Success = you see your real desktop with a red box hovering in the middle,
//!           and clicks pass through everywhere except the box.

use gtk::prelude::*;
use gtk::{gdk, Application, ApplicationWindow, CssProvider};

const APP_ID: &str = "dev.local.gnome-ocr.smoke";

fn main() {
    let app = Application::builder().application_id(APP_ID).build();

    app.connect_activate(|app| {
        // Single CSS rule — proven pattern from z13gui.
        let css = CssProvider::new();
        css.load_from_string("window { background: transparent; }");
        if let Some(d) = gdk::Display::default() {
            gtk::style_context_add_provider_for_display(&d, &css,
                gtk::STYLE_PROVIDER_PRIORITY_APPLICATION);
        }

        let win = ApplicationWindow::builder()
            .application(app)
            .title("transparent-smoke")
            .decorated(false)
            .resizable(false)
            .can_focus(false)
            .focusable(false)
            .build();

        let da = gtk::DrawingArea::new();
        da.set_draw_func(|_area, cr, w, h| {
            // Clear to transparent first.
            cr.set_operator(cairo::Operator::Source);
            cr.set_source_rgba(0.0, 0.0, 0.0, 0.0);
            cr.paint().ok();
            cr.set_operator(cairo::Operator::Over);
            // Red rectangle, 400x300, centered.
            let bw = 400.0_f64.min(w as f64);
            let bh = 300.0_f64.min(h as f64);
            let bx = (w as f64 - bw) / 2.0;
            let by = (h as f64 - bh) / 2.0;
            cr.set_source_rgba(1.0, 0.2, 0.2, 0.85);
            cr.rectangle(bx, by, bw, bh);
            cr.fill().ok();
        });
        win.set_child(Some(&da));

        // *** The two critical lines ***
        win.fullscreen();
        win.connect_realize(move |w| {
            if let Some(s) = w.surface() {
                // Empty Region = click-through everywhere.
                s.set_input_region(Some(&cairo::Region::create()));
            }
        });

        win.present();
    });

    app.run();
}
```

**Run it**:
