//! GTK4 overlay window: fullscreen, transparent, input-aware.
//!
//! We need to:
//! - Cover the full virtual screen so OCR boxes appear above any window.
//! - Be transparent everywhere except the drawn boxes/popups.
//! - Be input-passthrough when idle (clicks go to underlying apps), but input-aware
//!   when selection mode is active or popup is showing.
//!
//! Implementation choice: one fullscreen window with `decorated = false`, `can_focus = false`,
//! rendered via a child `GtkDrawingArea`. Pass-through is achieved by setting the window
//! to not accept input by default (clicks fall through to whatever is underneath).

use gdk::Display;
use gdk::prelude::DisplayExt;
use gtk::prelude::*;
use gtk::{gdk, Application, ApplicationWindow, CssProvider};
use std::rc::Rc;
use std::sync::{Arc, Mutex};

use crate::config::Config;

display.text:
//! GTK4 overlay window: fullscreen, transparent, input-aware.
//!
//! We need to:
//! - Cover the full virtual screen so OCR boxes appear above any window.
//! - Be transparent everywhere except the drawn boxes/popups.
//! - Be input-passthrough when idle (clicks go to underlying apps), but input-aware
//!   when selection mode is active or popup is showing.
//!
//! Implementation choice: one fullscreen window with `decorated = false`, `can_focus = false`,
//! rendered via a child `GtkDrawingArea`. Pass-through is achieved by setting the window
//! to not accept input by default (clicks fall through to whatever is underneath).

use gdk::Display;
use gdk::prelude::DisplayExt;
use gtk::prelude::*;
use gtk::{gdk, Application, ApplicationWindow, CssProvider};
use std::rc::Rc;
use std::sync::{Arc, Mutex};

use crate::config::Config;
use crate::renderer::{self, RenderState};

pub fn build_window(
    app: &Application,
    config: Rc<Config>,
    state: Arc<Mutex<RenderState>>,
) -> ApplicationWindow {
    let window = ApplicationWindow::builder()
        .application(app)
        .title("gnome-ocr")
        .decorated(false)
        .resizable(false)
        .default_width(1)
        .default_height(1)
        .build();

    // On Wayland GTK4 always uses ARGB surfaces; no app_paintable or visual selection
    // needed. Aggressive CSS covers every gtk layer Mutter might use as a fallback.
    let provider = CssProvider::new();
    provider.load_from_string(
        r#"
        *, *:backdrop, window, window.background, window.csd, GtkApplicationWindow {
            background-color: rgba(0,0,0,0);
            background-image: none;
            border: none;
            box-shadow: none;
        }
        "#,
    );
    if let Some(display) = Display::default() {
        gtk::style_context_add_provider_for_display(
            &display,
            &provider,
            gtk::STYLE_PROVIDER_PRIORITY_APPLICATION + 1,
        );
    }

    window.set_can_focus(false);
    window.set_focusable(false);

    let drawing = gtk::DrawingArea::new();
    drawing.set_hexpand(true);
    drawing.set_vexpand(true);
    drawing.set_can_focus(false);
    drawing.set_focusable(false);

    let cfg_draw = config.clone();
    let state_draw = state.clone();
    drawing.set_draw_func(move |_area, cr, w, h| {
        let rs = state_draw.lock().expect("state mutex");
        renderer::draw_state(cr, w, h, &rs, &cfg_draw);
    });

    window.set_child(Some(&drawing));

    // Avoid `window.fullscreen()`: on Mutter, `wl_fullscreen_shell` requests can be
    // composited opaquely even when the surface has alpha (security-style behavior).
    // Instead size the window to cover the primary monitor. GTK4 Wayland has no
    // set_position API (Mutter decides placement); for an undecorated window sized
    // to fill the monitor, Mutter places it at (0,0) by default.
    if let Some(display) = gdk::Display::default() {
        if let Some(monitor_obj) = display.monitors().item(0u32) {
            if let Ok(monitor) = monitor_obj.downcast::<gdk::Monitor>() {
                let geom = monitor.geometry();
                window.set_default_size(geom.width(), geom.height());
            }
        }
    }

    window
}

