## Section 4 — Standalone smoke test `examples/screencast_smoke.rs`

This is the smallest compilable-and-runnable variant. Drop into `examples/screencast_smoke.rs` and run `cargo run --example screencast_smoke`. It is self-contained; the section-3 file is the production version that also handles async correctly.

```rust
//! examples/screencast_smoke.rs
//! Run: cargo run --release --example screencast_smoke
//!
//! Pops the xdg-desktop-portal ScreenCast permission dialog, captures ONE frame,
//! and writes /tmp/screencast-test.png. Exits 0 on success, non-zero otherwise.

use std::os::fd::OwnedFd;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use anyhow::{Context, Result};
use ashpd::desktop::{
    PersistMode,
    screencast::{
        CursorMode, Screencast, SelectSourcesOptions, SourceType,
        Stream as ScreencastStream,
    },
};
use image::{ImageBuffer, Rgba};
use pipewire as pw;
use pipewire::properties::properties;
use pipewire::spa;
use pipewire::spa::param::format::{MediaSubtype, MediaType};

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<()> {
    // 1) Portal handshake ---------------------------------------------------
    let proxy = Screencast::new().await?;
    let session = proxy.create_session(Default::default()).await?;
    proxy
        .select_sources(
            &session,
            SelectSourcesOptions::default()
                .set_cursor_mode(CursorMode::Hidden)
                .set_sources(SourceType::Monitor)
                .set_multiple(false)
                .set_persist_mode(PersistMode::DoNot),
        )
        .await?;
    let response = proxy.start(&session, None, Default::default()).await?
        .response()?;
    let stream: ScreencastStream = response.streams().first().context("no streams")?.to_owned();
    let node_id: u32 = stream.pipe_wire_node_id();
    let fd: OwnedFd = proxy.open_pipe_wire_remote(&session, Default::default()).await?;

    eprintln!("[smoke] portal OK; pipewire node id = {node_id}");

    // 2) PipeWire capture on a dedicated thread -----------------------------
    let out = PathBuf::from("/tmp/screencast-test.png");
    let join = std::thread::Builder::new()
        .name("pw-capture".into())
        .spawn(move || -> Result<(u32, u32, Vec<u8>)> {
            pw::init();
            let mainloop = pw::main_loop::MainLoopBox::new(None)?;
            let context = pw::context::ContextBox::new(mainloop.loop_(), None)?;
            let core     = context.connect_fd(fd, None)?;

            let frame: Arc<Mutex<Option<(u32, u32, Vec<u8>)>>> =
                Arc::new(Mutex::new(None));
            let (tx, rx) = std::sync::mpsc::channel::<()>();
            let tx = Arc::new(Mutex::new(Some(tx)));

            let stream = pw::stream::StreamBox::new(
                &core,
                "gnome-ocr-smoke",
                properties! {
                    *pw::keys::MEDIA_TYPE     => "Video",
                    *pw::keys::MEDIA_CATEGORY => "Capture",
                    *pw::keys::MEDIA_ROLE     => "Screen",
                },
            )?;

            let mut info = pw::spa::param::video::VideoInfoRaw::new();
            stream
                .add_local_listener_with_user_data((frame.clone(), tx.clone()))
                .param_changed(|_, (frame, _tx), id, param| {
                    let Some(p) = param else { return; };
                    if id != pw::spa::param::ParamType::Format.as_raw() { return; }
                    let (mt, st) = match pw::spa::param::format_utils::parse_format(p) {
                        Ok(v) => v, Err(_) => return,
                    };
                    if mt != MediaType::Video || st != MediaSubtype::Raw { return; }
                    info.parse(p).expect("parse format");
                })
                .process(|stream, (frame, tx)| {
                    let mut buf = match stream.dequeue_buffer() { Some(b) => b, None => return };
                    let Some(d) = buf.datas_mut().first_mut() else { return };
                    let sz = d.chunk().size() as usize;
                    let stride = d.chunk().stride().unsigned_abs() as usize;
                    let width = info.size().width  as u32;
                    let height = info.size().height as u32;
                    let Some(src) = d.data() else { return };
                    let row_bytes = (width as usize * 4).min(stride);
                    let mut out = vec![0u8; width as usize * height as usize * 4];
                    for row in 0..height as usize {
                        let s = row * stride;
                        let dst = row * width as usize * 4;
                        if s + row_bytes > src.len() { break; }
                        out[dst..dst + row_bytes]
                            .copy_from_slice(&src[s..s + row_bytes]);
                    }
                    let _ = sz; // suppress unused
                    frame.lock().unwrap().replace((width, height, out));
                    if let Some(t) = tx.lock().unwrap().take() { let _ = t.send(()); }
                })
                .register()?;

            // Format enum: list BGRA / BGRx / RGBA — Mutter picks one.
            let obj = pw::spa::pod::object!(
                pw::spa::utils::SpaTypes::ObjectParamFormat,
                pw::spa::param::ParamType::EnumFormat,
                pw::spa::pod::property!(
                    pw::spa::param::format::FormatProperties::MediaType,
                    Id, MediaType::Video),
                pw::spa::pod::property!(
                    pw::spa::param::format::FormatProperties::MediaSubtype,
                    Id, MediaSubtype::Raw),
                pw::spa::pod::property!(
                    pw::spa::param::format::FormatProperties::VideoFormat,
                    Choice, Enum, Id,
                    pw::spa::param::video::VideoFormat::BGRA,
                    pw::spa::param::video::VideoFormat::BGRA,
                    pw::spa::param::video::VideoFormat::BGRx,
                    pw::spa::param::video::VideoFormat::BGRx,
                    pw::spa::param::video::VideoFormat::RGBA,
                    pw::spa::param::video::VideoFormat::RGBx,
                ),
                pw::spa::pod::property!(
                    pw::spa::param::format::FormatProperties::VideoSize,
                    Choice, Range, Rectangle,
                    pw::spa::utils::Rectangle { width: 1, height: 1 },
                    pw::spa::utils::Rectangle { width: 1, height: 1 },
                    pw::spa::utils::Rectangle { width: 16384, height: 16384 }),
                pw::spa::pod::property!(
                    pw::spa::param::format::FormatProperties::VideoFramerate,
                    Choice, Range, Fraction,
                    pw::spa::utils::Fraction { num: 30, denom: 1 },
                    pw::spa::utils::Fraction { num: 0,  denom: 1 },
                    pw::spa::utils::Fraction { num: 240, denom: 1 }),
            );
            let bytes = pw::spa::pod::serialize::PodSerializer::serialize(
                std::io::Cursor::new(Vec::new()),
                &pw::spa::pod::Value::Object(obj),
            )?.0.into_inner();
            let mut params = [pw::spa::pod::Pod::from_bytes(&bytes).unwrap()];

            stream.connect(
                spa::utils::Direction::Input,
                Some(node_id),
                pw::stream::StreamFlags::AUTOCONNECT
                    | pw::stream::StreamFlags::MAP_BUFFERS,
                &mut params,
            )?;

            let _ = rx.recv_timeout(std::time::Duration::from_secs(5));
            mainloop.quit();
            let g = frame.lock().unwrap().take()
                .context("no frame in 5 s")?;
            Ok(g)
        })?;

    let (w, h, mut px) = join.join().unwrap()?;
    // BGRA → RGBA swap (Mutter's BGRA / BGRx both have B at byte 0).
    for p in px.chunks_exact_mut(4) { p.swap(0, 2); }

    let img = ImageBuffer::<Rgba<u8>, _>::from_raw(w, h, px)
        .context("from_raw")?;
    img.save(&out).context("save png")?;
    println!("{}", out.display());
    Ok(())
}
```

**How to build and run** (Fedora 42 + GNOME 48 + Wayland, you are already in a graphical session):

```bash
# System deps (one-time)
sudo dnf install pipewire-devel gtk4-devel

# Add deps to Cargo.toml
cargo add ashpd@0.13 --no-default-features --features frontendcargo add pipewire@0.10 --features v0_3_77

# Run (a modal "Share your screen" dialog appears the first time only)
cargo run --example screencast_smoke
# → /tmp/screencast-test.png
```

**Important runtime caveat.** PipeWire connects to the per-session pipewire instance over `$XDG_RUNTIME_DIR/pipewire-0`. If you run from a `tmux`/`ssh` without that socket, you'll get a confusing error from `pw_context_connect_fd`. Run from the GUI desktop session, not over ssh.

