thiserror = "1"
tracing = "0.1"
tracing-subscriber = { version = "0.3", features = ["env-filter"] }
dirs = "5"
chrono = { version = "0.4", features = ["serde"] }
once_cell = "1"
url = "2"
notify = "6"

# Screen capture via xdg-desktop-portal ScreenCast (PipeWire backend)
ashpd = { version = "0.13", default-features = false, features = ["frontend", "tokio"] }
