    // Drive the mainloop on a watcher thread. run() blocks the calling
    // thread, so we need a separate thread to call mainloop.quit()
    // when the first frame arrives (or after 10 s).
    let ml_quit = mainloop.clone();
    std::thread::Builder::new()
        .name("pw-mainloop-driver".into())
        .spawn(move || {
            let _ = rx.recv_timeout(std::time::Duration::from_secs(10));
            ml_quit.quit();
        })
        .context("spawn mainloop driver thread")?;
    mainloop.run();

    let g = frame.lock().unwrap().take().context("no frame in 10 s")?;
    Ok(g)
})?;

