//! Main entry point. Sets up the GTK application, owns the qocrd subprocess, the IPC
//! server, the Yomitan + Anki clients, and the state machine that ties them together.

mod anki;
mod config;
mod daemon;
mod ipc;
mod overlay;
mod region_select;
mod renderer;
mod screencap;
mod types;
mod yomitan;

use anyhow::{Context, Result};
use gtk::prelude::*;
use gtk::{glib, Application};
use std::rc::Rc;
use std::sync::{Arc, Mutex};
use tokio::sync::mpsc as tmpsc;
use tracing_subscriber::EnvFilter;

use crate::config::Config;
use crate::daemon::{read_loop, DaemonEvent, OcrDaemon};
use crate::ipc::socket_path;
use crate::renderer::{PopupState, RegionState, RenderState};
use crate::types::{Command, OcrResult, Point};

const APP_ID: &str = "dev.local.gnome-ocr";

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
        .init();

    // Tokio runtime on a dedicated thread so the GTK main loop stays on the main thread.
    let rt = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(2)
        .enable_all()
        .build()
        .context("tokio runtime")?;
    let _rt_guard = rt.enter();

    // Config (in a thread-safe wrapper so GTK + tokio can both read).
    let config = Rc::new(Config::load().unwrap_or_else(|e| {
        tracing::warn!("config load failed: {e}; using defaults");
        Config::default()
    }));

    // Build channels: GTK-thread state machine ↔ tokio tasks.
    let (cmd_tx, cmd_rx) = tmpsc::channel::<Command>(64);
    let (event_tx, event_rx) = tmpsc::channel::<DaemonEvent>(64);

    // Spawn the IPC server on the tokio runtime.
    let ipc_path = socket_path().context("socket path")?;
    let ipc_tx = cmd_tx.clone();
    let ipc_handle = rt.spawn(async move {
        if let Err(e) = ipc::serve(ipc_path, ipc_tx).await {
            tracing::error!("IPC server: {e}");
        }
    });

    // Spawn qocrd + read loop.
    let daemon_tx = event_tx.clone();
    let daemon_handle: RtHandle = rt.spawn(async move {
        let mut daemon = match OcrDaemon::spawn().await {
            Ok(d) => d,
            Err(e) => {
                tracing::error!("spawn qocrd: {e}");
                return;
            }
        };
        let stdout = match daemon.take_stdout() {
            Some(s) => s,
            None => return,
        };
        if let Err(e) = read_loop(stdout, daemon_tx).await {
            tracing::error!("qocrd read loop: {e}");
        }
    });

    let app = Application::builder()
        .application_id(APP_ID)
        .flags(gtk::gio::ApplicationFlags::NON_UNIQUE)
        .build();
    let state = Arc::new(Mutex::new(RenderState::new()));
    let config_for_app = config.clone();

    // Wrap receivers in Arc<Mutex> so glib's Fn closures can borrow them mutably each tick
    // AND tokio tasks can send events across threads.
    let event_rx = Arc::new(Mutex::new(event_rx));
    let cmd_rx = Arc::new(Mutex::new(cmd_rx));

    app.connect_activate(move |app| {
        let window = overlay::build_window(app, config_for_app.clone(), state.clone());
        window.present();

        // Drain DaemonEvents and update state.
        let state_drain = state.clone();
        let event_rx_drain = event_rx.clone();
        glib::timeout_add_local(std::time::Duration::from_millis(100), move || {
            loop {
                let ev = {
                    let mut rx = event_rx_drain.lock().expect("event_rx mutex");
                    rx.try_recv()
                };
                match ev {
                    Ok(DaemonEvent::Result(result)) => {
                        let mut s = state_drain.lock().expect("state mutex");
                        let monitor = result.monitor.clone();
                        if let Some(rs) = s.regions.iter_mut().find(|r| r.monitor == monitor) {
                            rs.result = Some(result);
                        } else {
                            s.regions.push(RegionState {
                                monitor,
                                result: Some(result),
                                flash_until: None,
                            });
                        }
                    }
                    Ok(DaemonEvent::Unchanged) => continue,
                    Err(_) => break,
                }
            }
            glib::ControlFlow::Continue
        });

        // Drain Commands from IPC and dispatch.
        let state_cmd = state.clone();
        let yomitan_url = config_for_app.yomitan.api_url.clone();
        let anki_url = config_for_app.anki.anki_connect_url.clone();
        let anki_enabled = config_for_app.anki.enable;
        let anki_deck = config_for_app.anki.deck.clone();
        let anki_model = config_for_app.anki.model.clone();
        let anki_tags = config_for_app.anki.tags.clone();
        let anki_allow_dup = config_for_app.anki.allow_duplicate;
        let anki_fields = config_for_app.anki.fields.clone();
        let japanese_only = config_for_app.japanese_only;
        let cmd_rx_dispatch = cmd_rx.clone();
        let cmd_tx_dispatch = cmd_tx.clone();

        glib::timeout_add_local(std::time::Duration::from_millis(50), move || {
            loop {
                let cmd = {
                    let mut rx = cmd_rx_dispatch.lock().expect("cmd_rx mutex");
                    rx.try_recv()
                };
                match cmd {
                    Ok(cmd) => dispatch_command(
                        cmd,
                        &state_cmd,
                        cmd_tx_dispatch.clone(),
                        &yomitan_url,
                        &anki_url,
                        anki_enabled,
                        &anki_deck,
                        &anki_model,
                        &anki_tags,
                        anki_allow_dup,
                        &anki_fields,
                        japanese_only,
                    ),
                    Err(_) => break,
                }
            }
            glib::ControlFlow::Continue
        });
    });

    // Hold these so they don't drop.
    std::mem::forget(ipc_handle);
    std::mem::forget(daemon_handle);

    app.run();
    Ok(())
}

type RtHandle = tokio::task::JoinHandle<()>;

#[allow(clippy::too_many_arguments)]
fn dispatch_command(
    cmd: Command,
    state: &Arc<Mutex<RenderState>>,
    cmd_tx: tmpsc::Sender<Command>,
    yomitan_url: &str,
    anki_url: &str,
    anki_enabled: bool,
    anki_deck: &str,
    anki_model: &str,
    anki_tags: &[String],
    anki_allow_dup: bool,
    anki_fields: &std::collections::HashMap<String, String>,
    japanese_only: bool,
) {
    match cmd {
        Command::Scan { japanese, fullscreen } => {
            tracing::info!("scan japanese={japanese} fullscreen={fullscreen}");
            // We'll dispatch this to qocrd via a small bridge: the GTK side doesn't hold
            // the daemon directly. Use the same channel to send a "do scan" message that
            // a dedicated tokio task forwards to the daemon.
            // For v1 we keep it simple: spawn a tokio task that talks to qocrd.
            let url = yomitan_url.to_string();
            let state_owned = Arc::clone(state);
            tokio::spawn(async move {
                run_scan(japanese, fullscreen, url, state_owned).await;
            });
        }
        Command::Rescan => {
            tracing::info!("rescan");
            // Re-OCR all tracked regions using the latest config.japanese_only.
            let _ = japanese_only;
            // We could iterate `state.regions` and call daemon.rescan(...). Deferred to v1.
        }
        Command::ClearOverlay => {
            let mut s = state.lock().expect("state mutex");
            for r in &mut s.regions {
                if let Some(ref mut result) = r.result {
                    result.lines.clear();
                }
            }
        }
        Command::ClearAll => {
            state.lock().expect("state mutex").regions.clear();
            state.lock().expect("state mutex").popup = None;
        }
        Command::ShowRegion => {
            let mut s = state.lock().expect("state mutex");
            let now = std::time::Instant::now();
            for r in &mut s.regions {
                r.flash_until = Some(now + std::time::Duration::from_millis(1500));
            }
        }
        Command::TriggerPopup { x, y, monitor } => {
            tracing::info!("trigger popup at ({x},{y}) on {monitor}");
            let url = yomitan_url.to_string();
            let anki_url = anki_url.to_string();
            let anki_enabled = anki_enabled;
            let anki_deck = anki_deck.to_string();
            let anki_model = anki_model.to_string();
            let anki_tags = anki_tags.to_vec();
            let anki_allow_dup = anki_allow_dup;
            let anki_fields = anki_fields.clone();
            let state_clone = state.clone();
            tokio::spawn(async move {
                run_popup(
                    state_clone,
                    url,
                    anki_url,
                    anki_enabled,
                    anki_deck,
                    anki_model,
                    anki_tags,
                    anki_allow_dup,
                    anki_fields,
                    x as f64,
                    y as f64,
                )
                .await;
            });
        }
        Command::HoverOn | Command::HoverOff => {
            // Hooked up in v2; v1 ignores.
        }
        Command::ToggleConfig { key } => {
            tracing::info!("toggle config {key} (unimplemented)");
        }
        Command::GetConfig { key } => {
            tracing::info!("get config {key} (unimplemented)");
        }
    }
    let _ = cmd_tx; // currently unused; future use for get_config replies
}

/// Run a scan: ask qocrd to scan, then update state with the result.
async fn run_scan(
    japanese: bool,
    fullscreen: bool,
    _yomitan_url: String,
    state: Arc<Mutex<RenderState>>,
) {
    let mut daemon = match OcrDaemon::spawn().await {
        Ok(d) => d,
        Err(e) => {
            tracing::error!("spawn qocrd for scan: {e}");
            return;
        }
    };
    if let Err(e) = daemon.scan(japanese, fullscreen).await {
        tracing::error!("scan: {e}");
        return;
    }
    let stdout = match daemon.take_stdout() {
        Some(s) => s,
        None => return,
    };
    let (tx, mut rx) = tmpsc::channel::<DaemonEvent>(4);
    tokio::spawn(async move {
        let _ = read_loop(stdout, tx).await;
    });
    // We only care about the first non-unchanged result for a single scan.
    while let Some(ev) = rx.recv().await {
        match ev {
            DaemonEvent::Result(result) => {
                let mut s = state.lock().expect("state mutex");
                let monitor = result.monitor.clone();
                if let Some(rs) = s.regions.iter_mut().find(|r| r.monitor == monitor) {
                    rs.result = Some(result);
                } else {
                    s.regions.push(RegionState {
                        monitor,
                        result: Some(result),
                        flash_until: None,
                    });
                }
                break;
            }
            DaemonEvent::Unchanged => continue,
        }
    }
    daemon.kill();
}

#[allow(clippy::too_many_arguments)]
async fn run_popup(
    state: Arc<Mutex<RenderState>>,
    yomitan_url: String,
    anki_url: String,
    anki_enabled: bool,
    anki_deck: String,
    anki_model: String,
    anki_tags: Vec<String>,
    anki_allow_dup: bool,
    anki_fields: std::collections::HashMap<String, String>,
    x: f64,
    y: f64,
) {
    let yc = yomitan::YomitanClient::new(&yomitan_url);
    // Use the most-recent OCR region's text near (x,y) as the term. For v1 we just take
    // the closest line's text.
    let term: Option<String> = {
        let s = state.lock().expect("state mutex");
        s.regions
            .iter()
            .filter_map(|r| r.result.as_ref())
            .flat_map(|r: &OcrResult| r.lines.iter())
            .min_by(|a, b| {
                let da = ((a.aabb.x + a.aabb.width / 2.0) - x).powi(2)
                    + ((a.aabb.y + a.aabb.height / 2.0) - y).powi(2);
                let db = ((b.aabb.x + b.aabb.width / 2.0) - x).powi(2)
                    + ((b.aabb.y + b.aabb.height / 2.0) - y).powi(2);
                da.partial_cmp(&db).unwrap_or(std::cmp::Ordering::Equal)
            })
            .map(|l| l.text.clone())
    };
    let Some(term) = term else {
        tracing::info!("popup: no OCR text near ({x},{y})");
        return;
    };
    let reply = match yc.lookup(&term).await {
        Ok(r) => r,
        Err(e) => {
            tracing::warn!("yomitan lookup: {e}");
            // Yomitan likely not running. Show a "no lookup" popup anyway.
            let mut s = state.lock().expect("state mutex");
            s.popup = Some(PopupState {
                anchor: Point { x, y },
                lines: vec![term],
                readings: vec!["(yomitan-api unreachable)".into()],
                definitions: vec![format!("{e}")],
            });
            return;
        }
    };
    let entry = match reply {
        yomitan::LookupReply::Multi(v) => v.into_iter().flatten().next(),
        yomitan::LookupReply::Single(v) => v.into_iter().next(),
    };
    let (lines, readings, definitions) = match entry {
        Some(e) => {
            let lines = vec![e.expression.clone()];
            let readings = vec![e.reading.clone()];
            // Render a few definitions compactly.
            let mut defs = Vec::new();
            for (i, d) in e.glossary.iter().take(8).enumerate() {
                defs.push(format!("{}. {}", i + 1, d));
            }
            if defs.is_empty() {
                defs.push("(no definitions)".into());
            }
            (lines, readings, defs)
        }
        None => (vec![term.clone()], vec!["—".into()], vec!["(no entry)".into()]),
    };
    {
        let mut s = state.lock().expect("state mutex");
        s.popup = Some(PopupState {
            anchor: Point { x, y },
            lines,
            readings,
            definitions,
        });
    }

    // Optional Anki mining: only fire if user requested via a future IPC; for now, the
    // popup contains a "+" affordance is TBD. We keep anki config warm so it's ready.
    let _ = (&anki_url, anki_enabled, anki_deck, anki_model, anki_tags, anki_allow_dup, anki_fields);
}

