                    "Glossary": "{glossary}",
                    "IsWordAndSentenceCard": "x",
                    "PitchPosition": "{pitch-accent-positions}",
                    "PitchCategories": "{pitch-accent-categories}",
                    "Frequency": "{frequency-harmonic-rank}",
                    "FreqSort": "{frequency-harmonic-rank}"
                }
            }
        }
    }

    Connections {
        target: root.config
        function onAutoRescanChanged() {
            if (root.config.autoRescan)
                ocrProc.rescan();
        }
        function onShowOverlayChanged() {
            root.showOverlay = root.config.showOverlay;
        }
    }

    function updateMonitor(monitor, data) {
        var updated = Object.assign({}, root.ocrData); // copies to trigger bindings
        updated[monitor] = data;
        root.ocrData = updated;
    }

    Process {
        id: ocrProc
        command: ["qocrd"]
        stdinEnabled: true
        stdout: SplitParser {
            splitMarker: "\0"
            onRead: data => {
                // console.log(data);
                root.showOverlay = root.config.showOverlay;
                try {
                    var parsed = JSON.parse(data);
                    if (parsed.unchanged) {
                        rescanTimer.interval = root.config.autoRescanDelayUnchanged;
                    } else {
                        root.updateMonitor(parsed.monitor, parsed);
                        rescanTimer.interval = root.config.autoRescanDelay;
                    }
                } catch (e) {
                    console.log("Parse error:", e);
                }
                if (root.config.autoRescan) {
                    ocrProc.pendingRescans--;
                    if (ocrProc.pendingRescans <= 0)
                        rescanTimer.running = true;
                }
            }
        }
        stderr: SplitParser {
            onRead: data => {
                console.log("qocrd stderr:", data);
            }
        }
        // qmllint disable signal-handler-parameters
        onExited: (c, s) => console.log(c, s)
        // qmllint enable signal-handler-parameters
        running: true

        property int pendingRescans: 0
        function rescan() {
            var entries = Object.entries(root.ocrData);
            pendingRescans = entries.length;
            if (root.config.hideOverlayOnRescan)
                root.showOverlay = false;
            entries.forEach(([monitor, data]) => {
                var r = data.region;
                ocrProc.write(`rescan ${root.config.japaneseOnly} ${r.x} ${r.y} ${r.w} ${r.h} ${r.X} ${r.Y} ${monitor}\n`);
            });
        }
    }

    Item {
        id: ocr
        property bool showRegion: false
        IpcHandler {
            target: "ocr"

            function scan(): void {
                ocrProc.write(`scan ${root.config.japaneseOnly} false\n`);
            }
            function scan_fullscreen(): void {
                ocrProc.write(`scan ${root.config.japaneseOnly} true\n`);
            }
            function scan_output(output: string): void {
                var panel = root.panels[output];
                if (!panel)
                    return;
                root.ocrData[output] = {
                    monitor: output,
                    region: {
                        x: panel.screen.x,
                        y: panel.screen.y,
                        w: panel.screen.width,
                        h: panel.screen.height,
                        X: 0,
                        Y: 0
                    }
                };
                ocrProc.rescan();
            }
            function scan_region(output: string, x: int, y: int, w: int, h: int): void {
                var panel = root.panels[output];
                if (!panel)
                    return;
                root.ocrData[output] = {
                    monitor: output,
                    region: {
                        x: x,
                        y: y,
                        w: w,
                        h: h,
                        X: x - panel.screen.x,
                        Y: y - panel.screen.y
                    }
                };
                ocrProc.rescan();
            }
            function rescan(): void {
                ocrProc.rescan();
            }
            function clear_overlay(): void {
                var updated = {};
                Object.keys(root.ocrData).forEach(function (key) {
                    var old = root.ocrData[key];
                    var copy = Object.assign({}, old);
                    copy.lines = [];
                    updated[key] = copy;
                });
                root.ocrData = updated;
            }
            function clear_all(): void {
                root.ocrData = {};
            }
            function show_region(): void {
                ocr.showRegion = true;
                regionTimer.restart();
            }
            function set_config(setting: string, value: string): void {
                var parts = setting.split(".");
                var target = parts.length > 1 ? root.config[parts[0]] : root.config;
                var key = parts[parts.length - 1];
                if (value.toLowerCase() === "true")
                    target[key] = true;
                else if (value.toLowerCase() === "false")
                    target[key] = false;
                else if (!isNaN(value))
                    target[key] = Number(value);
                else
                    target[key] = value;
            }
            function toggle_config(setting: string): void {
                var parts = setting.split(".");
                var target = parts.length > 1 ? root.config[parts[0]] : root.config;
                var key = parts[parts.length - 1];
                target[key] = !target[key];
            }
            function get_config(setting: string): string {
                var parts = setting.split(".");
                var target = parts.length > 1 ? root.config[parts[0]] : root.config;
                var key = parts[parts.length - 1];
                return target[key];
            }
            function trigger_popup(x: int, y: int, monitor: string): void {
                var panel = root.panels[monitor];
                if (!panel)
                    return;

                panel.yomitanLookup.lookup({
                    x: x,
                    y: y
                });
            }
            function trigger_popup_term(x: int, y: int, monitor: string, term: string, full_line: string, term_index: int): void {
                var panel = root.panels[monitor];
                if (!panel)
                    return;

                panel.yomitanPopup.lookup(term, {
                    x: x,
                    y: y
                }, full_line, term_index);
            }
            function hover_on(): string {
                var old = root.hoverPopup;
                root.hoverPopup = true;
                return !old;
            }
            function hover_off(): void {
                root.hoverPopup = false;
            }
            function close_popup(): void {
                Object.values(root.panels).forEach(function (panel) {
                    panel.yomitanPopup.clear();
                });
            }
        }
    }

    Timer {
        id: rescanTimer
        interval: root.config.autoRescanDelay * 1000
        onTriggered: ocrProc.rescan()
    }

    Timer {
        id: regionTimer
        interval: 1500
        onTriggered: ocr.showRegion = false
    }

    Variants {
        model: Quickshell.screens

        PanelWindow { // qmllint disable uncreatable-type
            id: panel

            required property var modelData
            screen: modelData

            property var lineRects: []
            property var regionItems: []
            property var ocrData: root.ocrData[screen.name] ?? {}
            property var lines: ocrData.lines ?? []
            property var region: ocrData.region

            Component.onCompleted: {
                root.panels[screen.name] = panel;
            }

            Component.onDestruction: {
                delete root.panels[screen.name];
            }

            onLineRectsChanged: updateRegions()
            onOcrDataChanged: {
                panel.lineRects = [];
            }

            function updateRegions() {
                panel.regionItems = (root.config.showOverlay || root.hoverPopup) ? panel.lineRects : [];
            }

            color: "transparent"
            exclusionMode: ExclusionMode.Ignore
            WlrLayershell.layer: WlrLayer.Overlay

            anchors {
                top: true
                bottom: true
                left: true
                right: true
            }

            mask: Region {
                regions: _regions.instances
            }

            Variants {
                id: _regions
                model: panel.regionItems
                delegate: Region {
                    required property var modelData
                    item: modelData
                }
            }

            Item {
                id: regionItem

                Rectangle {
                    visible: ocr.showRegion && panel.region !== null
                    x: panel.region ? panel.region.X : 0
                    y: panel.region ? panel.region.Y : 0
                    width: panel.region ? panel.region.w : 0
                    height: panel.region ? panel.region.h : 0
                    color: root.config.regionBackground
                    border.color: root.config.regionBorder
                    border.width: 2
                }
            }

            HoverHandler {
                id: hover
                enabled: root.config.overlayOnHover
                property var hoveredLines: ({})

                function updateHovered(pos) {
                    for (var li = 0; li < panel.lines.length; li++) {
                        var b = panel.lines[li].aabb;
                        hoveredLines[li] = pos.x < b.x + b.width + root.config.boxMargin && pos.x > b.x - root.config.boxMargin && pos.y < b.y + b.height + root.config.boxMargin && pos.y > b.y - root.config.boxMargin;
                    }
                    hoveredLines = Object.assign({}, hoveredLines); // trigger binding
                }

                onPointChanged: {
                    hover.updateHovered(point.position);
                    if (root.hoverPopup) {
                        yomitanLookup.lookup(point.position);
                    }
                }
                onHoveredChanged: if (!hovered) {
                    hover.hoveredLines = {};
                }
            }

            Selector {
                id: selector
                lines: panel.lines
            }

            CombinedLineRects {
                id: combined
                rects: panel.lineRects
            }

            property alias yomitanLookup: yomitanLookup
            YomitanLookup {
                id: yomitanLookup
                anchors.fill: parent
                lines: panel.lines
                popup: yomitanPopup
                config: root.config.yomitan
            }

            property alias yomitanPopup: yomitanPopup
            YomitanPopup {
                id: yomitanPopup
                config: root.config.yomitan
                ankiConfig: root.config.anki
                onVisibleChanged: panel.updateRegions()
                screen: panel.screen
            }

            Item {
                id: overlay
                anchors.fill: parent
                visible: root.showOverlay

                Repeater {
                    model: panel.lines
                    delegate: Item {
                        id: line
                        required property var modelData
                        required property int index
                        property bool isVertical: modelData.is_vertical ?? false
                        property string text: modelData.text
                        property bool hovered: (hover.hoveredLines[line.index] ?? false)

                        Rectangle {
                            id: lineRect
                            property bool _visible: overlay.visible && (!root.config.overlayOnHover || line.hovered)
                            visible: false
                            x: parent.modelData.aabb.x - root.config.boxMargin
                            y: parent.modelData.aabb.y - root.config.boxMargin
                            width: parent.modelData.aabb.width + root.config.boxMargin * 2
                            height: parent.modelData.aabb.height + root.config.boxMargin * 2

                            color: root.config.background
                            border.color: root.config.borderColor
                            border.width: root.config.border
                        }

                        Component.onCompleted: {
                            var arr = panel.lineRects.slice();
                            arr.push(lineRect);
                            panel.lineRects = arr;
                        }

                        Repeater {
                            model: parent.modelData.words
                            delegate: Item {
                                id: word
                                required property var modelData
                                required property int index
                                property string text: modelData.text
                                property bool isVertical: line.isVertical

                                Rectangle {
                                    id: wordSpaceRect
                                    visible: selector.dragging && (selector.selWords[line.index + "-" + word.index] !== undefined)
                                    x: parent.modelData.whitespace_box.x ?? 0
                                    y: parent.modelData.whitespace_box.y ?? 0
                                    width: parent.modelData.whitespace_box.width
                                    height: parent.modelData.whitespace_box.height
                                    rotation: Math.abs(parent.modelData.whitespace_box.angle ?? 0) <= 5 ? 0 : parent.modelData.whitespace_box.angle
                                    transformOrigin: Item.TopLeft
                                    color: root.config.selectedBackground
                                }
                                Repeater {
                                    model: parent.modelData.symbols
                                    delegate: Item {
                                        id: symbol
                                        required property var modelData
                                        required property int index
                                        property string text: modelData.text
                                        property bool selected: selector.dragging && (selector.selWords[line.index + "-" + word.index + "-" + symbol.index] !== undefined)

                                        Rectangle {
                                            id: symbolRect
                                            visible: parent.selected
                                            x: parent.modelData.box.x
                                            y: parent.modelData.box.y
                                            width: parent.modelData.box.width
                                            height: parent.modelData.box.height
                                            rotation: Math.abs(parent.modelData.box.angle) <= 5 ? 0 : parent.modelData.box.angle
                                            transformOrigin: Item.TopLeft
                                            color: root.config.selectedBackground
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

import QtQuick
import Quickshell
import Quickshell.Wayland
import QtWebEngine
import QtWebChannel

Rectangle {
    id: root

    anchors.fill: parent
    visible: yomitanResponse !== ""
    color: "transparent"

    property alias popupWidth: popup.width
    property alias popupHeight: popup.height

    required property var config
    required property var ankiConfig
    required property var screen
    property var yomitanResponse: ""
    property var line: ""
    property var symbolIndex
    property var term
    property int gen: 0

    function yomitanRequest(endpoint, body, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", config.apiUrl + "/" + endpoint);
        xhr.onreadystatechange = function () {
            if (xhr.readyState === XMLHttpRequest.DONE && xhr.status === 200)
                callback(JSON.parse(xhr.responseText));
        };
        xhr.send(JSON.stringify(body));
    }

    function ankiConnectRequest(action, version, params, callback) {
        const xhr = new XMLHttpRequest();
        xhr.open('POST', ankiConfig.ankiConnectUrl);
        xhr.onreadystatechange = function () {
            if (xhr.readyState === XMLHttpRequest.DONE && xhr.status === 200) {
                const response = JSON.parse(xhr.responseText);
                if (response.error) {
                    throw response.error;
                } else {
                    if (response.hasOwnProperty('result'))
                        callback(response.result);
                }
            }
        };
        xhr.send(JSON.stringify({
            action,
            version,
            params
        }));
    }

    function lookup(term, newPos, line, index) {
        if (term !== root.term) {
            root.term = term;
            root.gen++;
            var gen = root.gen;
            yomitanRequest("termEntries", {
                term: term
            }, function (data) {
                if (gen !== root.gen) {
                    return;
                }
                if ((data.dictionaryEntries?.length ?? 0) > 0) {
                    view.loadHtml("");
                    yomitanResponse = data;
                    root.line = line;
                    root.symbolIndex = index;
                    view.loadHtml(root.buildHtml(yomitanResponse, term), "http://dummy.domain/");
                    if (ankiConfig.enable) {
                        checkAnki(term, gen);
                    }
                    getMedia(term, gen);
                    if (newPos) {
                        popup.x = Math.round(newPos.x);
                        popup.y = Math.round(newPos.y);
                    }
                }
            });
        } else {
            if (newPos) {
                popup.x = newPos.x;
                popup.y = newPos.y;
            }
            root.line = line;
            root.symbolIndex = index;
        }
    }

    function replaceCloze(field, entryIndex) {
        if (!/\{cloze-.*?\}/.test(field) || root.line == null || root.symbolIndex == null) {
            return field;
        }

        var primarySource = null;
        for (let i = 0; i < yomitanResponse.dictionaryEntries[entryIndex].headwords.length; i++) {
            primarySource = yomitanResponse.dictionaryEntries[entryIndex].headwords[i].sources.find(s => s.isPrimary);
            if (primarySource)
                break;
        }
        if (!primarySource) {
            return field;
        }

        const clozeBody = primarySource.originalText;
        const clozePrefix = root.line.slice(0, root.symbolIndex);
        const clozeSuffix = root.line.slice(root.symbolIndex + clozeBody.length);

        field = field.replace(/{cloze-prefix}/g, clozePrefix);
        field = field.replace(/{cloze-body}/g, clozeBody);
        field = field.replace(/{cloze-suffix}/g, clozeSuffix);

        return field;
    }

    function addToAnki(term, index, gen) {
        var yomitanAnkiFields = [];
        for (const [key, value] of Object.entries(ankiConfig.fields)) {
            var rx = /\{([^}]+)\}/g;
            var match;
            while (match = rx.exec(value)) {
                if (!yomitanAnkiFields.includes(match[1])) {
                    yomitanAnkiFields.push(match[1]);
                }
            }
        }

        yomitanRequest("ankiFields", {
            text: term,
            type: "term",
            markers: yomitanAnkiFields,
            includeMedia: true,
            maxEntries: index + 1
        }, function (data) {
            var ankiFields = {};
            for (const [key, value] of Object.entries(ankiConfig.fields)) {
                var ankiField = value;
                for (const [kkey, vvalue] of Object.entries(data.fields[index])) { // assumes termEntries and ankiFields match
                    ankiField = replaceCloze(ankiField, index);
                    ankiField = ankiField.replace(new RegExp(`\\{${kkey}\\}`, 'g'), vvalue);
                }
                ankiFields[key] = ankiField;
            }

            for (var i = 0; i < data.dictionaryMedia.length; i++) {
                if (Object.values(ankiFields).some(v => v.includes(data.dictionaryMedia[i].ankiFilename)))
                    ankiConnectRequest('storeMediaFile', 6, {
                        filename: data.dictionaryMedia[i].ankiFilename,
                        data: data.dictionaryMedia[i].content
                    }, function (res) {
                        console.log("added media " + res);
                    });
            }

            for (var i = 0; i < data.audioMedia.length; i++) {
                if (Object.values(ankiFields).some(v => v.includes(data.audioMedia[i].ankiFilename)))
                    ankiConnectRequest('storeMediaFile', 6, {
                        filename: data.audioMedia[i].ankiFilename,
                        data: data.audioMedia[i].content
                    }, function (res) {
                        console.log("added media " + res);
                    });
            }

            ankiConnectRequest('addNote', 6, {
                note: {
                    deckName: ankiConfig.deck,
                    modelName: ankiConfig.model,
                    tags: ankiConfig.tags,
                    fields: ankiFields,
                    options: {
                        allowDuplicate: ankiConfig.allowDuplicate
                    }
                }
            }, function (res) {
                console.log("added card " + res);
                checkAnki(term, gen);
            });
        });
    }

    function checkAnki(term, gen) {
        ankiConnectRequest('modelFieldNames', 6, {
            modelName: ankiConfig.model
        }, function (modelFieldNamesResult) {
            if (gen !== root.gen) {
                return;
            }
            var yomitanAnkiFields = [];
            const firstFieldName = modelFieldNamesResult[0];
            const firstFieldValue = ankiConfig.fields[firstFieldName];
            var rx = /\{([^}]+)\}/g;
            var match;
            while (match = rx.exec(firstFieldValue)) {
                if (!yomitanAnkiFields.includes(match[1])) {
                    yomitanAnkiFields.push(match[1]);
                }
            }

            yomitanRequest("ankiFields", {
                text: term,
                type: "term",
                markers: yomitanAnkiFields,
                includeMedia: false
            }, function (ankiFieldsResult) {
                if (gen !== root.gen) {
                    return;
                }
                var notes = [];
                var notesIndexes = new Map();
                for (var i = 0; i < ankiFieldsResult.fields.length; i++) {
                    var ankiField = firstFieldValue;
                    for (const [kkey, vvalue] of Object.entries(ankiFieldsResult.fields[i])) { // assumes termEntries and ankiFields match
                        ankiField = replaceCloze(ankiField, i);
                        ankiField = ankiField.replace(new RegExp(`\\{${kkey}\\}`, 'g'), vvalue);
                    }

                    if (!notesIndexes.has(ankiField)) {
                        notesIndexes.set(ankiField, [i]);
                    } else {
                        notesIndexes.get(ankiField).push(i);
                        continue;
                    }

                    notes.push({
                        deckName: ankiConfig.deck,
                        modelName: ankiConfig.model,
                        fields: {
                            [firstFieldName]: ankiField
                        },
                        options: {
                            allowDuplicate: false
                        }
                    });
                }

                ankiConnectRequest('canAddNotesWithErrorDetail', 6, {
                    notes: notes
                }, function (canAddNotesResult) {
                    if (gen !== root.gen) {
                        return;
                    }
                    var actions = [];
                    var actionsIndexes = [];

                    for (var i = 0; i < canAddNotesResult.length; i++) {
                        const res = canAddNotesResult[i];
                        if (res.error === "cannot create note because it is a duplicate") {
                            const ankiField = notes[i].fields[firstFieldName];
                            actionsIndexes.push(notesIndexes.get(ankiField));
                            actions.push({
                                action: "findCards",
                                version: 6,
                                params: {
                                    query: `"${firstFieldName}:${ankiField}" "deck:${ankiConfig.deck}"`
                                }
                            });
                        }
                    }

                    ankiConnectRequest('multi', 6, {
                        actions: actions
                    }, function (findCardsResults) {
                        if (gen !== root.gen) {
                            return;
                        }
                        var cards = [];
                        var cardsIndexes = new Map();
                        for (var i = 0; i < findCardsResults.length; i++) {
                            for (var j = 0; j < findCardsResults[i].result.length; j++) {
                                const id = findCardsResults[i].result[j];
                                cardsIndexes.set(id, actionsIndexes[i]);
                                cards.push(id);
                            }
                        }

                        ankiConnectRequest('areSuspended', 6, {
                            cards: cards
                        }, function (areSuspendedResult) {
                            if (gen !== root.gen) {
                                return;
                            }
                            let entriesInfo = {};

                            for (var i = 0; i < findCardsResults.length; i++) {
                                const cardIds = findCardsResults[i].result;
                                if (cardIds.length < 1) {
                                    continue;
                                }
                                const allSuspended = cardIds.every(id => areSuspendedResult[cards.indexOf(id)]);

                                const entryIndexes = cardsIndexes.get(cardIds[0]); // assumes all duplicates map to same note

                                for (const ei of entryIndexes) {
                                    entriesInfo[ei] = {
                                        suspended: allSuspended,
                                        cardIds: cardIds
                                    };
                                }
                            }

                            view.runJavaScript(`
                                (function() {
                                    const entriesInfo = ${JSON.stringify(entriesInfo)};
                                    function updateEntry(idx) {
                                        const entry = document.querySelector('.entry[data-index="' + idx + '"]');
                                        if (!entry) {
                                            return false;
                                        }

                                        const entryInfo = entriesInfo[idx];
                                        const header = entry.querySelector('.entry-header');
                                        const addButton = entry.querySelector('.anki-add');

                                        if (addButton) {
                                            addButton.classList.remove("anki-suspended");
                                            if (entryInfo.suspended) {
                                                addButton.classList.add("anki-suspended");
                                            }
                                            addButton.classList.add("anki-duplicate");
                                            addButton.innerText = "✓";
                                        }

                                        const existingViewButton = entry.querySelector('.anki-view');
                                        if (existingViewButton) {
                                            existingViewButton.remove();
                                        }
                                        if (header && addButton) {
                                            const viewButton = document.createElement('button');
                                            viewButton.className = 'anki anki-view';
                                            if (entryInfo.suspended) {
                                                viewButton.classList.add("anki-suspended");
                                            }
                                            viewButton.innerText = "↗";
                                            viewButton.onclick = () => {
                                                if (bridge) {
                                                    bridge.viewInAnki(entryInfo.cardIds);
                                                }
                                            };
                                            header.insertBefore(viewButton, addButton);
                                        }
                                        return true;
                                    }

                                    function applyAll() {
                                        const keys = Object.keys(entriesInfo);
                                        for (let i = 0; i < keys.length; i++) {
                                            const idx = keys[i];
                                            if (updateEntry(idx)) {
                                                delete entriesInfo[idx];
                                            }
                                        }
                                    }

                                    applyAll();

                                    if (Object.keys(entriesInfo).length > 0) {
                                        const observer = new MutationObserver((mutations, obs) => {
                                            applyAll();
                                            if (Object.keys(entriesInfo).length === 0) {
                                                obs.disconnect();
                                            }
                                        });
                                        observer.observe(document.body, { childList: true, subtree: true });
                                    }
                                })();
                            `);
                        });
                    });
                });
            });
        });
    }

    function viewInAnki(ids) {
        ankiConnectRequest('guiBrowse', 6, {
            query: "cid:" + ids.join(',')
        }, function (res) {
            console.log("opened cards " + res);
        });
    }

    function getMedia(term, gen) {
        yomitanRequest("ankiFields", {
            text: term,
            type: "term",
            markers: ["glossary", ...(config.fetchAudio ? ["audio"] : [])],
            includeMedia: true
        }, function (ankiFieldsResult) {
            if (gen !== root.gen) {
                return;
            }
            if (config.fetchAudio) {
                view.runJavaScript(`
                    (function() {
                        var audioMedia = ${JSON.stringify(ankiFieldsResult.audioMedia)};
                        var fields = ${JSON.stringify(ankiFieldsResult.fields)};

                        if (${config.autoPlayFirstAudio}) {
                            const audio = audioMedia[0];
                            new Audio('data:' + audio.mediaType + ';base64,' + audio.content).play();
                        }

                        function updateMedia() {
                            const entries = document.querySelectorAll('.entry');
                            if (entries.length !== ${yomitanResponse.dictionaryEntries.length}) {
                                return false;
                            }
                            for (let i = 0; i < entries.length; i++) {
                                const entry = entries[i];
                                const header = entry.querySelector('.entry-header');

                                if (header) {
                                    const audioButton = document.createElement('button');
                                    audioButton.className = 'audio';
                                    audioButton.innerHTML = '<svg viewBox="0 0 10 10" width="0.8em" height="0.8em"><polygon points="2,1 9,5 2,9" fill="currentColor"/></svg>';
                                    audioButton.onclick = () => {
                                        const filename = fields[i].audio.slice(7, -1); // remove "[sound:" "]"
                                        const audio = audioMedia.find(m => m.ankiFilename === filename);
                                        if (audio) {
                                            new Audio('data:' + audio.mediaType + ';base64,' + audio.content).play()
                                        }
                                    };
                                    header.appendChild(audioButton);
                                }
                            }

                            return true;
                        }

                        if (!updateMedia()) {
                            const observer = new MutationObserver((mutations, obs) => {
                                if (updateMedia()) {
                                    obs.disconnect();
                                }
                            });
                            observer.observe(document.body, { childList: true, subtree: true });
                        }
                    })();
                `);
            }

            view.runJavaScript(`
                (function() {
                    var mediaInfo = ${JSON.stringify(ankiFieldsResult.dictionaryMedia)};
                    function updateMedia(media) {
                        const imgs = document.querySelectorAll('img[data-dict-path="' + media.path + '"][data-dict-name="' + media.dictionary + '"]');
                        if (imgs.length === 0) {
                            return false;
                        }
                        for (let i = 0; i < imgs.length; i++) {
                            imgs[i].src = 'data:' + media.mediaType + ';base64,' + media.content;
                        }
                        return true;
                    }

                    function applyAll() {
                        var remaining = [];
                        for (let i = 0; i < mediaInfo.length; i++) {
                            if (!updateMedia(mediaInfo[i])) {
                              remaining.push(mediaInfo[i]);
                            }
                        }
                        mediaInfo = remaining;
                    }

                    applyAll();

                    if (mediaInfo.length > 0) {
                        const observer = new MutationObserver((mutations, obs) => {
                            applyAll();
                            if (mediaInfo.length === 0) {
                                obs.disconnect();
                            }
                        });
                        observer.observe(document.body, { childList: true, subtree: true });
                    }
                })();
            `);
        });
    }

    function clear() {
        view.loadHtml("");
        gen++;
        term = null;
        line = null;
        symbolIndex = null;
        yomitanResponse = "";
    }

    function buildHtml(data, term) {
        var entries = data.dictionaryEntries ?? [];

        var body = `
          <form onsubmit="submitQuery(); return false;" class="lookup">
            <input type="text" id="lquery" value='${term.replace(/&/g, "&amp;").replace(/'/g, "&apos;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;")}'>
            <button type="submit">Lookup</button>
          </form>
          <script src="qrc:///qtwebchannel/qwebchannel.js"></script>
          <script>
          let bridge = null;
          new QWebChannel(qt.webChannelTransport, function(channel) {
              bridge = channel.objects.bridge;
          });
          function submitQuery() {
              var q = document.getElementById("lquery").value;
              if (bridge) {
                  bridge.lookup(q);
              }
          }
          function addToAnki(term, index) {
              if (bridge) {
                  bridge.addToAnki(term, index);
              }
          }
          </script>
        `;

        for (var ei = 0; ei < entries.length; ei++) {
            var entry = entries[ei];
            if (ei > 0)
                body += '<hr class="entry-sep">';
            body += buildEntry(entry, term, ei);
        }

        return `<!DOCTYPE html><html><head><meta charset="utf-8">
        <style>
        html, body {
            background: ${config.backgroundColor};
            color: ${config.foregroundColor};
            font-family: sans-serif;
            font-size: 14px;
            padding: 5px 6px;
            margin: 0;
            --fg: ${config.foregroundColor};
            --text-color: ${config.foregroundColor};
            --background-color: ${config.backgroundColor};
            --font-size-no-units: 14;
        }

        table { border-collapse: collapse; }
        td, th { border: 1px solid ${config.separatorColor}; padding: 0.2em; }
        th { background: ${config.backgroundSecondaryColor}; }
        hr.entry-sep {
            border: none;
            border-top: 1px solid ${config.separatorColor};
            margin: 8px -12px;
        }
        .entry-header { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }
        .term    { font-size: 2em; }
        .reading { font-size: 1.2em; color: #66d9ee; }
        .inflections { font-size: 0.9em; color: ${config.foregroundSecondaryColor}; margin-bottom: 0.2em; }
        .freqs { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 6px; }
        .freq-pill { display: inline-flex; border: 1px solid #489148; border-radius: 0.25em }
        .freq-name { background: #489148; font-size: 0.8em; color: white; font-weight: bold; padding: 0.4em 0.2em; }
        .freq-val  { padding: 0.2em 0.2em; }
        .def-header { display: flex; flex-wrap: wrap; align-items: center; gap: 0.2em; margin-bottom: 0.2em; }
        .badge {
            display: inline-block;
            font-size: 0.8em;
            font-weight: bold;
            padding: 0.2em 0.3em;
            word-break: keep-all;
            border-radius: 0.25em;
            vertical-align: text-bottom;
            color: white;
        }
        .badge-star { background: #025CAA; }
        .badge-dict { background: #9057AD; }

        .lookup {
            display: flex;
            gap: 6px;
            margin-bottom: 8px;
        }
        .lookup input {
            flex: 1;
            background: transparent;
            color: ${config.foregroundColor};
            border: 1px solid ${config.separatorColor};
            border-radius: 0.25em;
            padding: 0.2em 0.3em;
            font-size: 1em;
            outline: none;
        }
        .lookup button, .anki, .audio {
            background: ${config.foregroundColor};
            color: ${config.backgroundColor};
            border: none;
            border-radius: 0.25em;
            padding: 0.2em 0.3em;
            font-size: 1em;
            cursor: pointer;
        }
        .lookup input:focus { border-color: ${config.foregroundSecondaryColor}; }
        .lookup button:hover { filter: brightness(1.1); }
        .lookup button:active { filter: brightness(0.9); }

        button.anki:first-of-type {
            margin-left: auto;
        }
        .anki:hover { filter: brightness(1.1); }
        .anki:active { filter: brightness(0.9); }
        .anki-duplicate { background-color: #489148; }
        .anki-add.anki-suspended { background-color: #d4c96e; }

        .anki, .audio {
            width: 1.5em;
            height: 1.5em;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 0;
        }

        ::-webkit-scrollbar { width: 6px; }
        ::-webkit-scrollbar-track { background: ${config.backgroundColor}; }
        ::-webkit-scrollbar-thumb { background: ${config.foregroundSecondaryColor}; border-radius: 3px; }
        ${config.extraCss}
        </style>
        </head><body>${body}</body></html>`;
    }

    function buildEntry(entry, term, index) {
        var hw = entry.headwords?.[0] ?? {};
        var html = `<div class="entry" data-index="${index}">`;

        // term + reading + anki button header
        html += '<div class="entry-header">';
        html += '<span class="term">' + (hw.term ?? "") + '</span>';
        if (hw.reading && hw.reading !== hw.term)
            html += '<span class="reading">' + (hw.reading) + '</span>';
        if (ankiConfig.enable) {
            html += `<button class="anki anki-add" onclick='addToAnki(${JSON.stringify(term).replace(/'/g, "&apos;")}, ${index})'>＋</button>`;
        }
        html += '</div>';

        // inflections
        var rules = entry.inflectionRuleChainCandidates?.[0]?.inflectionRules ?? [];
        if (rules.length > 0) {
            html += '<div class="inflections">';
            html += rules.map(r => "• " + (r.name ?? r)).join("  ");
            html += '</div>';
        }

        // frequencies
        var freqs = groupFrequencies(entry.frequencies ?? []);
        if (freqs.length > 0) {
            html += '<div class="freqs">';
            for (var fi = 0; fi < freqs.length; fi++) {
                var freq = freqs[fi];
                html += '<span class="freq-pill"><span class="freq-name">' + (freq.name) + '</span>';
                html += '<span class="freq-val">';
                for (var fvi = 0; fvi < freq.values.length; fvi++) {
                    if (fvi > 0 && fvi - 1 < freq.values.length)
                        html += ", ";
                    html += (freq.values[fvi]);
                }
                html += '</span></span>';
            }
            html += '</div>';
        }

        // pronunciations: not planned for now

        // definitions
        var defs = entry.definitions ?? [];
        for (var di = 0; di < defs.length; di++) {
            var def = defs[di];
            html += '<div class="def-block">';
            html += '<div class="def-header">';

            // tags (★ etc.) as blue badges
            var tags = def.tags ?? [];
            for (var ti = 0; ti < tags.length; ti++) {
                var tag = tags[ti];
                var tip = (tag.content ?? []).join(", ");
                html += '<span class="badge badge-star" title="' + tip + '">' + (tag.name ?? "") + '</span>';
            }
            // dictionary name as purple badge
            if (def.dictionary)
                html += '<span class="badge badge-dict">' + def.dictionary + '</span>';
            html += '</div>';

            var entries = def.entries ?? [];
            for (var ei = 0; ei < entries.length; ei++) {
                var ent = entries[ei];
                if (ent.type === "structured-content")
                    html += renderNode(ent.content, def.dictionary);
                else if (typeof ent === "string")
                    html += '<div style="white-space: pre-wrap">' + ent + "</div>";
            }
            html += '</div>';
        }

        html += '</div>';
        return html;
    }

    // Recursively render a dictionary's structured-content node to HTML.
    function renderNode(node, dictionary) {
        if (typeof node === "string")
            return node;
        if (Array.isArray(node)) {
            var s = "";
            for (var i = 0; i < node.length; i++)
                s += renderNode(node[i], dictionary);
            return s;
        }

        var tag = node.tag;

        if (tag === "br")
            return "<br>";

        if (!tag)
            return renderNode(node.content, dictionary);

        var attrs = "";

        if (node.lang)
            attrs += ' lang="' + node.lang + '"';
        if (node.href)
            attrs += ' href="' + node.href + '"';
        if (node.title)
            attrs += ' title="' + node.title + '"';
        if (node.rowSpan)
            attrs += ' rowspan="' + node.rowSpan + '"';
        if (node.colSpan)
            attrs += ' colspan="' + node.colSpan + '"';

        if (node.style) {
            var styleStr = styleObjToString(node.style);
            if (styleStr)
                attrs += ' style="' + styleStr + '"';
        }

        if (node.data) {
            for (var k in node.data)
                attrs += ' data-' + k + '="' + (String(node.data[k])) + '"';
        }

        if (tag === "img" && node.path) {
            attrs += ' data-dict-name="' + dictionary + '"';
            attrs += ' data-dict-path="' + node.path + '"';

            let style = "";
            const sizeUnits = node.sizeUnits || "px";
            const width = node.preferredWidth || node.width;
            const height = node.preferredHeight || node.height;

            if (width)
                style += `width:${width}${sizeUnits};`;
            if (height)
                style += `height:${height}${sizeUnits};`;
            if (node.verticalAlign)
                style += `vertical-align:${node.verticalAlign};`;

            attrs += ' style="' + style + '"';

            if (node.alt) {
                attrs += ' alt="' + node.alt + '"';
            }
        }

        if (node.content)
            var inner = renderNode(node.content, dictionary);
        else
            inner = "";

        return "<" + tag + attrs + ">" + inner + "</" + tag + ">";
    }

    function styleObjToString(styleObj) {
        var parts = [];
        for (var prop in styleObj) {
            var val = String(styleObj[prop]);
            var cssProp = prop.replace(/([A-Z])/g, m => "-" + m.toLowerCase());
            parts.push(cssProp + ":" + val);
        }
        return parts.join(";");
    }

    function groupFrequencies(freqs) {
        var groups = [], map = {};
        for (var i = 0; i < freqs.length; i++) {
            var f = freqs[i];
            var name = f.dictionaryAlias || f.dictionary;
            if (!map[name]) {
                map[name] = {
                    name: name,
                    values: []
                };
                groups.push(map[name]);
            }
            map[name].values.push(f.displayValue ?? String(f.frequency));
        }
        return groups;
    }

    TapHandler {
        acceptedButtons: Qt.LeftButton | Qt.RightButton | Qt.MiddleButton
        onTapped: root.clear()
    }

    PanelWindow {
        screen: root.screen
        anchors {
            left: true
            right: true
            top: true
            bottom: true
        }
        exclusionMode: ExclusionMode.Ignore
        color: "transparent"
        visible: root.visible
        WlrLayershell.keyboardFocus: WlrKeyboardFocus.OnDemand
        WlrLayershell.layer: WlrLayer.Top // below the popup
        Shortcut {
            sequence: "Escape"
            onActivated: root.clear()
        }

        TapHandler {
            acceptedButtons: Qt.LeftButton | Qt.RightButton | Qt.MiddleButton
            onTapped: root.clear()
        }
    }

    PanelWindow {
        screen: root.screen
        anchors {
            left: true
            right: true
            top: true
            bottom: true
        }
        exclusionMode: ExclusionMode.Ignore
        color: "transparent"
        visible: root.visible
        WlrLayershell.keyboardFocus: WlrKeyboardFocus.OnDemand
        WlrLayershell.layer: WlrLayer.Overlay
        Shortcut {
            sequence: "Escape"
            onActivated: root.clear()
        }

        mask: Region {
            item: popup
        }

        Rectangle {
            id: popup

            width: 400
            height: 480
            color: root.config.backgroundColor

            WebEngineView {
                id: view
                anchors.fill: parent
                anchors.margins: borderRect.border.width
                backgroundColor: root.config.backgroundColor

                settings.playbackRequiresUserGesture: false

                onContextMenuRequested: function (req) {
                    req.accepted = true;
                }
                webChannel: channel
                WebChannel {
                    id: channel
                    registeredObjects: [bridge]
                }
                QtObject {
                    id: bridge
                    WebChannel.id: "bridge"

                    function lookup(term) {
                        root.lookup(term, null, null, null);
                    }
                    function addToAnki(term, index) {
                        root.addToAnki(term, index, root.gen);
                    }
                    function viewInAnki(ids) {
                        root.viewInAnki(ids);
                    }
                }
                onNavigationRequested: function (req) {
                    if (req.navigationType === WebEngineNavigationRequest.LinkClickedNavigation) {
                        req.reject();
                        var url = req.url.toString();
                        if (url.startsWith("http://dummy.domain/")) {
                            var params = new URLSearchParams(req.url.toString().split("?")[1] ?? "");
                            if (params.has("query")) {
                                var term = decodeURIComponent(params.get("query"));
                                root.lookup(term, null, null, null);
                            }
                        } else {
                            Qt.openUrlExternally(req.url);
                        }
                    }
                }
            }

            Rectangle {
                id: borderRect
                anchors.fill: parent
                color: "transparent"
                border.color: root.config.borderColor
                border.width: 1
            }
        }
    }
}

