input.content:
{
  "uuid": "gnome-ocr-overlay@gnome-ocr.local",
  "name": "GNOME OCR Overlay",
  "description": "Transparent overlay for OCR text highlighting. POC for gnome-ocr.",
  "shell-version": ["48"]
}

// POC: prove that a transparent Clutter actor in Main.uiGroup renders above
// ordinary app windows on Mutter 48, is click-through, and supports runtime
// redraw for moving the highlight.
//
// What this does on enable():
//   1. Creates a Clutter.Actor sized to the full primary monitor.
//   2. Sets reactive=false so clicks pass through to apps below.
//   3. Adds it to Main.uiGroup (above windows, below modal dialogs).
//   4. Wires a Clutter.Canvas to draw a hard-coded red rectangle at
//      (200, 200) 400x300 — visible above any app window.
//   5. Updates the rectangle position every 2s to prove runtime redraw works.

import Clutter from 'gi://Clutter';
import GLib from 'gi://GLib';
import St from 'gi://St';

import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';
import * as Main from 'resource:///org/gnome/shell/ui/main.js';

const TEST_RECT_INITIAL = {x: 200, y: 200, w: 400, h: 300};
const TEST_RECT_STEP = {dx: 60, dy: 40};

export default class GnomeOcrOverlayExtension extends Extension {
    enable() {
        log('[gnome-ocr-overlay] enable()');
        log(`[gnome-ocr-overlay] screen: ${global.screen_width}x${global.screen_height}`);

        const w = global.screen_width;
        const h = global.screen_height;

        this._actor = new Clutter.Actor();
        this._actor.set_reactive(false);
        this._actor.set_size(w, h);
        this._actor.set_position(0, 0);

        const canvas = new Clutter.Canvas();
        canvas.set_size(w, h);

        this._rect = {...TEST_RECT_INITIAL};

        canvas.connect('draw', (canvas, cr, canvasW, canvasH) => {
            // Background fully transparent — overlay must be see-through.
            cr.setSourceRGBA(0, 0, 0, 0);
            cr.setOperator(0); // CAIRO_OPERATOR_CLEAR
            cr.paint();
            cr.setOperator(1); // CAIRO_OPERATOR_SOURCE

            // Hard-coded red rect — proves the overlay is on top of apps.
            cr.setSourceRGBA(1.0, 0.2, 0.2, 0.85);
            cr.rectangle(this._rect.x, this._rect.y, this._rect.w, this._rect.h);
            cr.fill();

            // Border for clarity.
            cr.setSourceRGBA(1.0, 1.0, 1.0, 1.0);
            cr.setLineWidth(2);
            cr.rectangle(this._rect.x, this._rect.y, this._rect.w, this._rect.h);
            cr.stroke();

            log(`[gnome-ocr-overlay] drew rect at (${this._rect.x},${this._rect.y}) ${this._rect.w}x${this._rect.h}`);
        });

        this._canvas = canvas;
        this._actor.set_content(canvas);
        canvas.invalidate();

        Main.uiGroup.add_child(this._actor);
        log('[gnome-ocr-overlay] actor added to uiGroup');

        // Move the rect every 2s to prove we can update at runtime.
        this._timeoutId = GLib.timeout_add(GLib.PRIORITY_DEFAULT, 2000, () => {
            this._rect.x += TEST_RECT_STEP.dx;
            this._rect.y += TEST_RECT_STEP.dy;
            if (this._rect.x + this._rect.w > w) this._rect.x = TEST_RECT_INITIAL.x;
            if (this._rect.y + this._rect.h > h) this._rect.y = TEST_RECT_INITIAL.y;
            this._canvas.invalidate();
            return GLib.SOURCE_CONTINUE;
        });
    }

    disable() {
        log('[gnome-ocr-overlay] disable()');
        if (this._timeoutId) {
            GLib.source_remove(this._timeoutId);
            this._timeoutId = null;
        }
        if (this._actor) {
            Main.uiGroup.remove_child(this._actor);
            this._actor.destroy();
            this._actor = null;
        }
        this._canvas = null;
    }
}

