// GNOME Shell extension for gnome-ocr.
//
// Why this exists: Mutter 48.8 does NOT implement zwlr-layer-shell-v1 (Rofi
// 2.0 confirms this on GNOME Shell 48.4, Nov 2025). xdg-shell fullscreen is
// force-opacified by Mutter, and xdg-shell non-fullscreen is below other apps
// in the stack. The only way to render above all app windows on stock
// Mutter is to inject a Clutter actor into Main.uiGroup, which is what
// GNOME Shell itself does for its own UI. This requires being a GNOME
// Shell extension.
//
// D-Bus interface (dev.local.gnome_ocr.Overlay, /dev/local/gnome_ocr/Overlay):
//   - Show(json: s)  — receive a JSON list of highlight boxes
//   - Clear()        — remove all highlights
//   - Clicked(x,y)   — signal emitted when the user clicks on a highlight
//
// Rust app calls Show/Clear; receives Clicked.

import Clutter from 'gi://Clutter';
import Gio from 'gi://Gio';
import GLib from 'gi://GLib';

import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';
import * as Main from 'resource:///org/gnome/shell/ui/main.js';

const DBUS_IFACE = 'dev.local.gnome_ocr.Overlay';
const DBUS_PATH = '/dev/local/gnome_ocr/Overlay';

const DBusInterfaceXml = `
<node>
  <interface name="${DBUS_IFACE}">
    <method name="Show">
      <arg type="s" name="json" direction="in"/>
    </method>
    <method name="Clear"/>
    <signal name="Clicked">
      <arg type="i" name="x"/>
      <arg type="i" name="y"/>
    </signal>
  </interface>
</node>`;

export default class GnomeOcrOverlayExtension extends Extension {
    enable() {
        log('[gnome-ocr-overlay] enable()');
        log(`[gnome-ocr-overlay] screen: ${global.screen_width}x${global.screen_height}`);

        this._boxes = [];
        this._clickTargets = [];

        const w = global.screen_width;
        const h = global.screen_height;

        // Root overlay actor — covers the screen, paints the boxes,
        // click-through by default.
        this._rootActor = new Clutter.Actor();
        this._rootActor.set_reactive(false);
        this._rootActor.set_size(w, h);
        this._rootActor.set_position(0, 0);

        this._canvas = new Clutter.Canvas();
        this._canvas.set_size(w, h);
        this._canvas.connect('draw', (canvas, cr) => {
            for (const box of this._boxes)
                this._drawBox(cr, box);
        });
        this._rootActor.set_content(this._canvas);

        Main.uiGroup.add_child(this._rootActor);
        log('[gnome-ocr-overlay] root actor added to uiGroup');

        // Export the D-Bus interface.
        this._dbus = Gio.DBusExportedObject.wrapJSObject(DBusInterfaceXml, this);
        this._dbus.export(Gio.DBus.session, DBUS_PATH);
        log(`[gnome-ocr-overlay] D-Bus exported at ${DBUS_PATH}`);
    }

    disable() {
        log('[gnome-ocr-overlay] disable()');
        if (this._dbus) {
            this._dbus.unexport();
            this._dbus = null;
        }
        this._removeClickTargets();
        if (this._rootActor) {
            Main.uiGroup.remove_child(this._rootActor);
            this._rootActor.destroy();
            this._rootActor = null;
        }
        this._canvas = null;
        this._boxes = [];
    }

    // ====== D-Bus methods (called by Rust app) ======

    Show(json) {
        log(`[gnome-ocr-overlay] Show(${json.length} chars)`);
        let parsed;
        try {
            parsed = JSON.parse(json);
        } catch (e) {
            log(`[gnome-ocr-overlay] Show: JSON parse failed: ${e}`);
            return;
        }
        const boxes = Array.isArray(parsed?.boxes) ? parsed.boxes : [];
        this._setBoxes(boxes);
    }

    Clear() {
        log('[gnome-ocr-overlay] Clear()');
        this._setBoxes([]);
    }

    // ====== internal ======

    _setBoxes(boxes) {
        this._boxes = boxes;
        this._removeClickTargets();
        for (const box of boxes) {
            if (typeof box.x !== 'number' || typeof box.y !== 'number' ||
                typeof box.w !== 'number' || typeof box.h !== 'number')
                continue;
            const target = new Clutter.Actor();
            target.set_reactive(true);
            target.set_position(box.x, box.y);
            target.set_size(box.w, box.h);
            target.set_opacity(0); // invisible click target
            target.connect('button-release-event', (actor, event) => {
                const [x, y] = event.get_coords();
                log(`[gnome-ocr-overlay] clicked at (${x}, ${y})`);
                if (this._dbus) {
                    this._dbus.emit_signal(
                        'Clicked',
                        new GLib.Variant('(ii)', [x, y])
                    );
                }
                return Clutter.EVENT_STOP;
            });
            this._rootActor.add_child(target);
            this._clickTargets.push(target);
        }
        this._canvas.invalidate();
        log(`[gnome-ocr-overlay] drew ${boxes.length} boxes, ${this._clickTargets.length} click targets`);
    }

    _removeClickTargets() {
        for (const t of this._clickTargets) {
            this._rootActor.remove_child(t);
            t.destroy();
        }
        this._clickTargets = [];
    }

    _drawBox(cr, box) {
        // Soft green fill, sharper green border — easy to spot on any wallpaper.
        cr.setSourceRGBA(0.2, 0.8, 0.4, 0.30);
        cr.rectangle(box.x, box.y, box.w, box.h);
        cr.fill();
        cr.setSourceRGBA(0.2, 0.8, 0.4, 0.95);
        cr.setLineWidth(2);
        cr.rectangle(box.x, box.y, box.w, box.h);
        cr.stroke();
    }
}

//! D-Bus client that talks to the GNOME Shell extension that owns the
//! overlay surface. The extension registers itself on the session bus as
//! `dev.local.gnome_ocr.Overlay` at `/dev/local/gnome_ocr/Overlay`.
//!
//! Protocol (JSON payload to `Show`):
//! ```json
//! {"boxes":[{"x":100,"y":200,"w":400,"h":50}, ...]}
//! ```
//!
//! The extension emits a `Clicked(x, y)` signal when the user clicks on a
//! highlight box. Coordinates are global screen coords.

use anyhow::{Context, Result};
use futures::StreamExt;
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::sync::mpsc as tmpsc;
use tracing::{info, warn};
use zbus::{proxy, Connection};

pub const DBUS_IFACE: &str = "dev.local.gnome_ocr.Overlay";
pub const DBUS_PATH: &str = "/dev/local/gnome_ocr/Overlay";

#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
pub struct Box {
    pub x: f64,
    pub y: f64,
    pub w: f64,
    pub h: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ShowPayload {
    boxes: Vec<Box>,
}

#[proxy(
    interface = "dev.local.gnome_ocr.Overlay",
    default_service = "dev.local.gnome_ocr.Overlay",
    default_path = "/dev/local/gnome_ocr/Overlay"
)]
trait Overlay {
    async fn show(&self, json: String) -> zbus::Result<()>;
    async fn clear(&self) -> zbus::Result<()>;

    #[zbus(signal)]
    async fn clicked(&self, x: i32, y: i32) -> zbus::Result<()>;
}

#[derive(Clone)]
pub struct OverlayClient {
    conn: Connection,
}

impl OverlayClient {
    /// Connect to the session bus and prepare a proxy. The actual D-Bus
    /// calls happen later — the extension must be enabled in GNOME Shell for
    /// them to succeed. `Ok(())` here only means we reached the bus.
    pub async fn new() -> Result<Self> {
        let conn = Connection::session().await.context("session D-Bus")?;
        Ok(Self { conn })
    }

    /// Send a list of boxes to the extension. Returns Err if the call fails
    /// (e.g. extension not enabled) — the caller should log and keep going.
    pub async fn show(&self, boxes: Vec<Box>) -> Result<()> {
        let proxy = OverlayProxy::new(&self.conn).await
            .context("create overlay proxy (is the gnome-shell extension enabled?)")?;
        let payload = serde_json::to_string(&ShowPayload { boxes })?;
        proxy.show(payload).await.context("Show D-Bus call")?;
        Ok(())
    }

    /// Clear all boxes.
    pub async fn clear(&self) -> Result<()> {
        let proxy = OverlayProxy::new(&self.conn).await
            .context("create overlay proxy")?;
        proxy.clear().await.context("Clear D-Bus call")?;
        Ok(())
    }

    /// Spawn a task that forwards `Clicked(x, y)` signals to the given
    /// channel. Returns the JoinHandle so the caller can cancel it.
    pub fn spawn_click_listener(self, tx: tmpsc::Sender<(i32, i32)>) -> tokio::task::JoinHandle<()> {
        tokio::spawn(async move {
            // Try to build the proxy; if the extension isn't enabled, retry
            // every 2s for 30s, then give up (it'll be re-tried on the next
            // show() call if the user enables the extension later).
            let mut proxy = None;
            for _ in 0..15 {
                match OverlayProxy::new(&self.conn).await {
                    Ok(p) => { proxy = Some(p); break; }
                    Err(e) => {
                        warn!("overlay proxy unavailable ({e}); retrying in 2s");
                        tokio::time::sleep(std::time::Duration::from_secs(2)).await;
                    }
                }
            }
            let Some(proxy) = proxy else {
                warn!("gave up waiting for overlay extension");
                return;
            };
            let mut stream = match proxy.receive_clicked().await {
                Ok(s) => s,
                Err(e) => { warn!("receive_clicked: {e}"); return; }
            };
            info!("overlay Clicked listener up");
            while let Some(sig) = stream.next().await {
                let args = match sig.args() {
                    Ok(a) => a,
                    Err(e) => { warn!("clicked args: {e}"); continue; }
                };
                if tx.send((args.x, args.y)).await.is_err() {
                    info!("clicked channel closed; stopping listener");
                    break;
                }
            }
        })
    }
}

/// Convert one OCR result's lines into highlight boxes with a configurable
/// margin. Coordinates are absolute screen pixels.
pub fn boxes_from_ocr(
    result: &crate::types::OcrResult,
    margin: f64,
) -> Vec<Box> {
    result.lines.iter().map(|l| Box {
        x: l.aabb.x - margin,
        y: l.aabb.y - margin,
        w: l.aabb.width + margin * 2.0,
        h: l.aabb.height + margin * 2.0,
    }).collect()
}

/// Helper for callers that already hold a connection via Arc.
pub async fn try_show(conn: &Arc<Connection>, boxes: Vec<Box>) {
    if let Ok(proxy) = OverlayProxy::new(conn.as_ref()).await {
        let payload = serde_json::to_string(&ShowPayload { boxes }).unwrap_or_default();
        if let Err(e) = proxy.show(payload).await {
            warn!("overlay Show failed: {e}");
        }
    } else {
        warn!("overlay extension not available (not enabled?)");
    }
}

