enable() {
    log('[gnome-ocr-overlay] enable()');
    log(`[gnome-ocr-overlay] screen: ${global.screen_width}x${global.screen_height}`);

    this._boxes = [];
    this._clickTargets = [];

    const w = global.screen_width;
    const h = global.screen_height;

    // Root overlay actor — covers the screen, paints the boxes,
    // click-through by default.
    this._rootActor = new Clutter.Actor();
    this._rootActor.set_reactive(false);
    this._rootActor.set_size(w, h);
    this._rootActor.set_position(0, 0);

    this._canvas = new Clutter.Canvas();
    this._canvas.set_size(w, h);
    this._canvas.connect('draw', (canvas, cr) => {
        for (const box of this._boxes)
            this._drawBox(cr, box);
    });
    this._rootActor.set_content(this._canvas);

    Main.uiGroup.add_child(this._rootActor);
    log('[gnome-ocr-overlay] root actor added to uiGroup');

    // Own the well-known bus name and export the object on it.
    this._dbus = Gio.DBusExportedObject.wrapJSObject(DBusInterfaceXml, this);
    this._nameOwnerId = Gio.DBus.session.own_name(
        DBUS_NAME,
        Gio.BusNameOwnerFlags.NONE,
        (connection, name) => {
            log(`[gnome-ocr-overlay] acquired bus name ${name}`);
            this._dbus.export(connection, DBUS_PATH);
            log(`[gnome-ocr-overlay] D-Bus exported at ${DBUS_PATH}`);
        },
        (connection, name) => {
            log(`[gnome-ocr-overlay] lost bus name ${name}`);
        }
    );
}

disable() {
    log('[gnome-ocr-overlay] disable()');
    if (this._nameOwnerId) {
        Gio.DBus.session.unown_name(this._nameOwnerId);
        this._nameOwnerId = 0;
    }
    if (this._dbus) {
        try { this._dbus.unexport(); } catch (e) { log(`unexport: ${e}`); }
        this._dbus = null;
    }
    this._removeClickTargets();
    if (this._rootActor) {
        Main.uiGroup.remove_child(this._rootActor);
        this._rootActor.destroy();
        this._rootActor = null;
    }
    this._canvas = null;
    this._boxes = [];
}

