//! Main entry point. Sets up the GTK application, owns the qocrd subprocess, the IPC
//! server, the Yomitan + Anki clients, and the state machine that ties them together.

mod anki;
mod config;
mod daemon;
mod ipc;
mod overlay;
mod overlay_dbus;
mod region_select;
mod renderer;
mod screencap;
mod types;
mod yomitan;

use anyhow::{Context, Result};
use gtk::prelude::*;
use gtk::{glib, Application};
use std::rc::Rc;
use std::sync::{Arc, Mutex};
use tokio::sync::mpsc as tmpsc;
use tracing_subscriber::EnvFilter;

use crate::config::Config;
use crate::daemon::{read_loop, DaemonEvent, OcrDaemon};
use crate::ipc::socket_path;
use crate::renderer::{PopupState, RegionState, RenderState};
use crate::types::{Command, OcrResult, Point};

const APP_ID: &str = "dev.local.gnome-ocr";

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
        .init();

    // Tokio runtime on a dedicated thread so the GTK main loop stays on the main thread.
    let rt = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(2)
        .enable_all()
        .build()
        .context("tokio runtime")?;
    let _rt_guard = rt.enter();

    // Config (in a thread-safe wrapper so GTK + tokio can both read).
    let config = Rc::new(Config::load().unwrap_or_else(|e| {
        tracing::warn!("config load failed: {e}; using defaults");
        Config::default()
    }));

    // Build channels: GTK-thread state machine ↔ tokio tasks.
    let (cmd_tx, cmd_rx) = tmpsc::channel::<Command>(64);
    let (event_tx, event_rx) = tmpsc::channel::<DaemonEvent>(64);

    // Spawn the IPC server on the tokio runtime.
    let ipc_path = socket_path().context("socket path")?;
    let ipc_tx = cmd_tx.clone();
    let ipc_handle = rt.spawn(async move {
        if let Err(e) = ipc::serve(ipc_path, ipc_tx).await {
            tracing::error!("IPC server: {e}");
        }
    });

    // Spawn qocrd + read loop.
    let daemon_tx = event_tx.clone();
    let daemon_handle: RtHandle = rt.spawn(async move {
        let mut daemon = match OcrDaemon::spawn().await {
            Ok(d) => d,
            Err(e) => {
                tracing::error!("spawn qocrd: {e}");
                return;
            }
        };
        let stdout = match daemon.take_stdout() {
            Some(s) => s,
            None => return,
        };
        if let Err(e) = read_loop(stdout, daemon_tx).await {
            tracing::error!("qocrd read loop: {e}");
        }
    });

    let app = Application::builder()
        .application_id(APP_ID)
        .flags(gtk::gio::ApplicationFlags::NON_UNIQUE)
        .build();
    let state = Arc::new(Mutex::new(RenderState::new()));
    let config_for_app = config.clone();

    // Wrap receivers in Arc<Mutex> so glib's Fn closures can borrow them mutably each tick
    // AND tokio tasks can send events across threads.
    let event_rx = Arc::new(Mutex::new(event_rx));
    let cmd_rx = Arc::new(Mutex::new(cmd_rx));

    app.connect_activate(move |app| {
        let window = overlay::build_window(app, config_for_app.clone(), state.clone());
        window.present();

        // Drain DaemonEvents and update state.
        let state_drain = state.clone();
        let event_rx_drain = event_rx.clone();
        glib::timeout_add_local(std::time::Duration::from_millis(100), move || {
            loop {
                let ev = {
                    let mut rx = event_rx_drain.lock().expect("event_rx mutex");
                    rx.try_recv()
                };
                match ev {
                    Ok(DaemonEvent::Result(result)) => {
                        let mut s = state_drain.lock().expect("state mutex");
                        let monitor = result.monitor.clone();
                        if let Some(rs) = s.regions.iter_mut().find(|r| r.monitor == monitor) {
                            rs.result = Some(result);
                        } else {
                            s.regions.push(RegionState {
                                monitor,
                                result: Some(result),
                                flash_until: None,
                            });
                        }
                    }
                    Ok(DaemonEvent::Unchanged) => continue,
                    Err(_) => break,
                }
            }
            glib::ControlFlow::Continue
        });

        // Drain Commands from IPC and dispatch.
        let state_cmd = state.clone();
        let yomitan_url = config_for_app.yomitan.api_url.clone();
        let anki_url = config_for_app.anki.anki_connect_url.clone();
        let anki_enabled = config_for_app.anki.enable;
        let anki_deck = config_for_app.anki.deck.clone();
        let anki_model = config_for_app.anki.model.clone();
        let anki_tags = config_for_app.anki.tags.clone();
        let anki_allow_dup = config_for_app.anki.allow_duplicate;
        let anki_fields = config_for_app.anki.fields.clone();
        let japanese_only = config_for_app.japanese_only;
        let cmd_rx_dispatch = cmd_rx.clone();
        let cmd_tx_dispatch = cmd_tx.clone();

        glib::timeout_add_local(std::time::Duration::from_millis(50), move || {
            loop {
                let cmd = {
                    let mut rx = cmd_rx_dispatch.lock().expect("cmd_rx mutex");
                    rx.try_recv()
                };
                match cmd {
                    Ok(cmd) => dispatch_command(
                        cmd,
                        &state_cmd,
                        cmd_tx_dispatch.clone(),
                        &yomitan_url,
                        &anki_url,
                        anki_enabled,
                        &anki_deck,
                        &anki_model,
                        &anki_tags,
                        anki_allow_dup,
                        &anki_fields,
                        japanese_only,
                    ),
                    Err(_) => break,
                }
            }
            glib::ControlFlow::Continue
        });
    });

    // Hold these so they don't drop.
    std::mem::forget(ipc_handle);
    std::mem::forget(daemon_handle);

    app.run();
    Ok(())
}

type RtHandle = tokio::task::JoinHandle<()>;

