// D-Bus overlay client (talks to the GNOME Shell extension).
// The extension must be enabled in GNOME Shell for calls to succeed;
// the client logs and keeps going if it isn't.
let overlay = match overlay_dbus::OverlayClient::new().await {
    Ok(c) => Some(std::sync::Arc::new(c)),
    Err(e) => {
        tracing::warn!("D-Bus session bus unavailable: {e}; overlay disabled");
        None
    }
};

// Channel: extension → Rust, for click events.
let (click_tx, click_rx) = tmpsc::channel::<(i32, i32)>(64);
if let Some(overlay) = overlay.clone() {
    let _ = overlay.spawn_click_listener(click_tx);
}

