input.newString:
app.connect_activate(move |app| {
    // The GTK overlay window is intentionally NOT created here. On
    // Mutter 48.8, xdg-shell fullscreen windows are force-opacified and
    // non-fullscreen windows go below other apps. The overlay surface
    // is owned by the GNOME Shell extension (a Clutter actor in
    // Main.uiGroup). Rust drives it over D-Bus.

    // Drain DaemonEvents: update state and push boxes to the extension.
    let state_drain = state.clone();
    let event_rx_drain = event_rx.clone();
    let overlay_for_results = overlay.clone();
    glib::timeout_add_local(std::time::Duration::from_millis(100), move || {
        loop {
            let ev = {
                let mut rx = event_rx_drain.lock().expect("event_rx mutex");
                rx.try_recv()
            };
            match ev {
                Ok(DaemonEvent::Result(result)) => {
                    let monitor = result.monitor.clone();
                    let boxes = overlay_dbus::boxes_from_ocr(&result, 15.0);
                    // update state
                    {
                        let mut s = state_drain.lock().expect("state mutex");
                        if let Some(rs) = s.regions.iter_mut().find(|r| r.monitor == monitor) {
                            rs.result = Some(result);
                        } else {
                            s.regions.push(RegionState {
                                monitor,
                                result: Some(result),
                                flash_until: None,
                            });
                        }
                    }
                    // push to extension
                    if let Some(overlay) = overlay_for_results.clone() {
                        tokio::spawn(async move {
                            if let Err(e) = overlay.show(boxes).await {
                                tracing::warn!("overlay.show: {e}");
                            }
                        });
                    }
                }
                Ok(DaemonEvent::Unchanged) => continue,
                Err(_) => break,
            }
        }
        glib::ControlFlow::Continue
    });

    // Drain Commands from IPC and dispatch.
    let state_cmd = state.clone();
    let yomitan_url = config_for_app.yomitan.api_url.clone();
    let anki_url = config_for_app.anki.anki_connect_url.clone();
    let anki_enabled = config_for_app.anki.enable;
    let anki_deck = config_for_app.anki.deck.clone();
    let anki_model = config_for_app.anki.model.clone();
    let anki_tags = config_for_app.anki.tags.clone();
    let anki_allow_dup = config_for_app.anki.allow_duplicate;
    let anki_fields = config_for_app.anki.fields.clone();
    let japanese_only = config_for_app.japanese_only;
    let cmd_rx_dispatch = cmd_rx.clone();
    let cmd_tx_dispatch = cmd_tx.clone();
    let overlay_for_cmds = overlay.clone();

    glib::timeout_add_local(std::time::Duration::from_millis(50), move || {
        loop {
            let cmd = {
                let mut rx = cmd_rx_dispatch.lock().expect("cmd_rx mutex");
                rx.try_recv()
            };
            match cmd {
                Ok(cmd) => {
                    // Send Clear to the extension before dispatching Clear* commands.
                    match &cmd {
                        Command::ClearAll | Command::ClearOverlay => {
                            if let Some(overlay) = overlay_for_cmds.clone() {
                                tokio::spawn(async move {
                                    let _ = overlay.clear().await;
                                });
                            }
                        }
                        _ => {}
                    }
                    dispatch_command(
                        cmd,
                        &state_cmd,
                        cmd_tx_dispatch.clone(),
                        &yomitan_url,
                        &anki_url,
                        anki_enabled,
                        &anki_deck,
                        &anki_model,
                        &anki_tags,
                        anki_allow_dup,
                        &anki_fields,
                        japanese_only,
                    );
                }
                Err(_) => break,
            }
        }
        glib::ControlFlow::Continue
    });

    // Drain click events from the extension: trigger a Yomitan lookup
    // at the clicked coordinates. The lookup result will be pushed back
    // to the extension as a popup (TODO; for v1 we just log).
    let click_rx_drain = Arc::new(Mutex::new(click_rx));
    glib::timeout_add_local(std::time::Duration::from_millis(100), move || {
        loop {
            let ev = {
                let mut rx = click_rx_drain.lock().expect("click_rx mutex");
                rx.try_recv()
            };
            match ev {
                Ok((x, y)) => {
                    tracing::info!("overlay click at ({x},{y})");
                    // TODO: lookup via yomitan + push popup to extension.
                }
                Err(_) => break,
            }
        }
        glib::ControlFlow::Continue
    });

    // Suppress the unused `app` warning — we don't need the GTK app
    // for anything visible, only its main loop.
    let _ = app;
});

