// Manual Clone impl because `Connection` doesn't implement Clone, but our
// client is just a handle to the session bus and the underlying connection
// is reference-counted. Cloning the handle is safe.
impl std::clone::Clone for OverlayClient {
    fn clone(&self) -> Self {
        // Connection is internally Rc/Arc-like. We need a different approach
        // since Connection itself isn't Clone. Use the builder instead.
        unimplemented!("use OverlayClient::cloned() instead")
    }
}

