input.newString:
// Drain click events from the extension: find the nearest OCR line
// to the click coordinates, look it up via yomitan-api, and push
// the result back to the extension as a popup.
let click_rx_drain = click_rx.clone();
let state_for_clicks = state.clone();
let yomitan_url_for_clicks = config_for_app.yomitan.api_url.clone();
let overlay_for_clicks = overlay.clone();
glib::timeout_add_local(std::time::Duration::from_millis(100), move || {
    loop {
        let ev = {
            let mut rx = click_rx_drain.lock().expect("click_rx mutex");
            rx.try_recv()
        };
        match ev {
            Ok((x, y)) => {
                // Find the OCR line whose aabb center is closest to
                // (x, y) within a 50px tolerance.
                const TOLERANCE_PX: f64 = 50.0;
                let (term, anchor_x, anchor_y) = {
                    let s = state_for_clicks.lock().expect("state mutex");
                    let mut best: Option<(f64, f64, f64, String)> = None;
                    for rs in &s.regions {
                        let Some(result) = &rs.result else { continue; };
                        for l in &result.lines {
                            let cx = l.aabb.x + l.aabb.width / 2.0;
                            let cy = l.aabb.y + l.aabb.height / 2.0;
                            let d = ((cx - x as f64).powi(2) + (cy - y as f64).powi(2)).sqrt();
                            if d > TOLERANCE_PX { continue; }
                            match &best {
                                None => best = Some((d, cx, cy, l.text.clone())),
                                Some((bd, _, _, _)) if d < *bd =>
                                    best = Some((d, cx, cy, l.text.clone())),
                                _ => {}
                            }
                        }
                    }
                    match best {
                        Some((_, cx, cy, t)) => (t, cx, cy),
                        None => {
                            tracing::info!("overlay click at ({x},{y}): no OCR text within {TOLERANCE_PX}px");
                            return;
                        }
                    }
                };
                let url = yomitan_url_for_clicks.clone();
                let overlay = overlay_for_clicks.clone();
                tracing::info!("overlay click at ({x},{y}): looking up '{term}'");
                tokio::spawn(async move {
                    let yc = yomitan::YomitanClient::new(&url);
                    let (lines, readings, definitions) =
                        match yc.lookup(&term).await {
                            Ok(yomitan::LookupReply::Multi(v)) => v.into_iter().flatten().next()
                                .map(|e| (
                                    vec![e.expression.clone()],
                                    vec![e.reading.clone()],
                                    e.glossary.iter().take(8)
                                        .enumerate()
                                        .map(|(i, g)| format!("{}. {}", i + 1, g))
                                        .collect::<Vec<_>>(),
                                ))
                                .unwrap_or_else(|| (vec![term.clone()], vec!["—".into()], vec!["(no entry)".into()])),
                            Ok(yomitan::LookupReply::Single(v)) => v.into_iter().next()
                                .map(|e| (
                                    vec![e.expression.clone()],
                                    vec![e.reading.clone()],
                                    e.glossary.iter().take(8)
                                        .enumerate()
                                        .map(|(i, g)| format!("{}. {}", i + 1, g))
                                        .collect::<Vec<_>>(),
                                ))
                                .unwrap_or_else(|| (vec![term.clone()], vec!["—".into()], vec!["(no entry)".into()])),
                            Err(e) => {
                                tracing::warn!("yomitan lookup failed: {e}");
                                (vec![term.clone()],
                                 vec!["(yomitan-api unreachable)".into()],
                                 vec![format!("{e}")])
                            }
                        };
                    if let Some(overlay) = overlay {
                        if let Err(e) = overlay.show_popup(
                            anchor_x, anchor_y,
                            lines, readings, definitions,
                        ).await {
                            tracing::warn!("overlay show_popup: {e}");
                        }
                    }
                });
            }
            Err(_) => break,
        }
    }
    glib::ControlFlow::Continue
});

