//
// Why this exists: Mutter 48.8 does NOT implement zwlr-layer-shell-v1 (Rofi
// 2.0 confirms this on GNOME Shell 48.4, Nov 2025). xdg-shell fullscreen is
// force-opacified by Mutter, and xdg-shell non-fullscreen is below other apps
// in the stack. The only way to render above all app windows on stock
// Mutter is to inject a Clutter actor into Main.uiGroup, which is what
// GNOME Shell itself does for its own UI. This requires being a GNOME
// Shell extension.
//
// D-Bus interface (dev.local.gnome_ocr.Overlay, /dev/local/gnome_ocr/Overlay):
//   - Show(json: s)  — receive a JSON list of highlight boxes
//   - Clear()        — remove all highlights
//   - Clicked(x,y)   — signal emitted when the user clicks on a highlight
//
// Rust app calls Show/Clear; receives Clicked.

import Clutter from 'gi://Clutter';
import Gio from 'gi://Gio';
import GLib from 'gi://GLib';

display.text:
// GNOME Shell extension for gnome-ocr.
//
// Why this exists: Mutter 48.8 does NOT implement zwlr-layer-shell-v1 (Rofi
// 2.0 confirms this on GNOME Shell 48.4, Nov 2025). xdg-shell fullscreen is
// force-opacified by Mutter, and xdg-shell non-fullscreen is below other apps
// in the stack. The only way to render above all app windows on stock
// Mutter is to inject a Clutter actor into Main.uiGroup, which is what
// GNOME Shell itself does for its own UI. This requires being a GNOME
// Shell extension.
//
// D-Bus interface (dev.local.gnome_ocr.Overlay, /dev/local/gnome_ocr/Overlay):
//   - Show(json: s)  — receive a JSON list of highlight boxes
//   - Clear()        — remove all highlights
//   - Clicked(x,y)   — signal emitted when the user clicks on a highlight
//
// Rust app calls Show/Clear; receives Clicked.

import Clutter from 'gi://Clutter';
import Gio from 'gi://Gio';
import GLib from 'gi://GLib';

import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';
import * as Main from 'resource:///org/gnome/shell/ui/main.js';

const DBUS_NAME = 'dev.local.gnome_ocr.Overlay';
const DBUS_PATH = '/dev/local/gnome_ocr/Overlay';

const DBusInterfaceXml = `
<node>
  <interface name="${DBUS_NAME}">
    <method name="Show">
      <arg type="s" name="json" direction="in"/>
    </method>
    <method name="Clear"/>
    <method name="ShowPopup">
      <arg type="s" name="json" direction="in"/>
    </method>
    <method name="HidePopup"/>
    <signal name="Clicked">
      <arg type="i" name="x"/>
      <arg type="i" name="y"/>
    </signal>
  </interface>
</node>`;

export default class GnomeOcrOverlayExtension extends Extension {
    enable() {
        log('[gnome-ocr-overlay] enable()');
        log(`[gnome-ocr-overlay] screen: ${global.screen_width}x${global.screen_height}`);

        this._boxes = [];
        this._clickTargets = [];

        const w = global.screen_width;
        const h = global.screen_height;

        // Root overlay actor — covers the screen, paints the boxes,
        // click-through by default.
        this._rootActor = new Clutter.Actor();
        this._rootActor.set_reactive(false);
        this._rootActor.set_size(w, h);
        this._rootActor.set_position(0, 0);

        this._canvas = new Clutter.Canvas();
        this._canvas.set_size(w, h);
        this._canvas.connect('draw', (canvas, cr) => {
            for (const box of this._boxes)
                this._drawBox(cr, box);
        });
        this._rootActor.set_content(this._canvas);

        Main.uiGroup.add_child(this._rootActor);
        log('[gnome-ocr-overlay] root actor added to uiGroup');

        // Own the well-known bus name and export the object on it.
        this._dbus = Gio.DBusExportedObject.wrapJSObject(DBusInterfaceXml, this);
        this._nameOwnerId = Gio.DBus.session.own_name(
            DBUS_NAME,
            Gio.BusNameOwnerFlags.NONE,
            (connection, name) => {
                log(`[gnome-ocr-overlay] acquired bus name ${name}`);
                this._dbus.export(connection, DBUS_PATH);
                log(`[gnome-ocr-overlay] D-Bus exported at ${DBUS_PATH}`);
            },
            (connection, name) => {
                log(`[gnome-ocr-overlay] lost bus name ${name}`);
            }
        );
    }

    disable() {
        log('[gnome-ocr-overlay] disable()');
        if (this._nameOwnerId) {
            Gio.DBus.session.unown_name(this._nameOwnerId);
            this._nameOwnerId = 0;
        }
        if (this._dbus) {
            try { this._dbus.unexport(); } catch (e) { log(`unexport: ${e}`); }
            this._dbus = null;
        }
        this._removeClickTargets();
        if (this._rootActor) {
            Main.uiGroup.remove_child(this._rootActor);
            this._rootActor.destroy();
            this._rootActor = null;
        }
        this._canvas = null;
        this._boxes = [];
    }

    // ====== D-Bus methods (called by Rust app) ======

    Show(json) {
        log(`[gnome-ocr-overlay] Show(${json.length} chars)`);
        let parsed;
        try {
            parsed = JSON.parse(json);
        } catch (e) {
            log(`[gnome-ocr-overlay] Show: JSON parse failed: ${e}`);
            return;
        }
        const boxes = Array.isArray(parsed?.boxes) ? parsed.boxes : [];
        this._setBoxes(boxes);
    }

    Clear() {
        log('[gnome-ocr-overlay] Clear()');
        this._setBoxes([]);
    }

    ShowPopup(json) {
        log(`[gnome-ocr-overlay] ShowPopup(${json.length} chars)`);
        let parsed;
        try {
            parsed = JSON.parse(json);
        } catch (e) {
            log(`[gnome-ocr-overlay] ShowPopup: JSON parse failed: ${e}`);
            return;
        }
        this._showPopup(parsed);
    }

    HidePopup() {
        this._hidePopup();
    }

    // ====== internal ======

    _setBoxes(boxes) {
        this._boxes = boxes;
        this._removeClickTargets();
        for (const box of boxes) {
            if (typeof box.x !== 'number' || typeof box.y !== 'number' ||
                typeof box.w !== 'number' || typeof box.h !== 'number')
                continue;
            const target = new Clutter.Actor();
            target.set_reactive(true);
            target.set_position(box.x, box.y);
            target.set_size(box.w, box.h);
            target.set_opacity(0); // invisible click target
            target.connect('button-release-event', (actor, event) => {
                const [x, y] = event.get_coords();
                log(`[gnome-ocr-overlay] clicked at (${x}, ${y})`);
                if (this._dbus) {
                    this._dbus.emit_signal(
                        'Clicked',
                        new GLib.Variant('(ii)', [x, y])
                    );
                }
                return Clutter.EVENT_STOP;
            });
            this._rootActor.add_child(target);
            this._clickTargets.push(target);
        }
        this._canvas.invalidate();
        log(`[gnome-ocr-overlay] drew ${boxes.length} boxes, ${this._clickTargets.length} click targets`);
    }

    _removeClickTargets() {
        for (const t of this._clickTargets) {
            this._rootActor.remove_child(t);
            t.destroy();
        }
        this._clickTargets = [];
    }

    _drawBox(cr, box) {
        // Soft green fill, sharper green border — easy to spot on any wallpaper.
        cr.setSourceRGBA(0.2, 0.8, 0.4, 0.30);
        cr.rectangle(box.x, box.y, box.w, box.h);
        cr.fill();
        cr.setSourceRGBA(0.2, 0.8, 0.4, 0.95);
        cr.setLineWidth(2);
        cr.rectangle(box.x, box.y, box.w, box.h);
        cr.stroke();
    }

    _showPopup(p) {
        // p: {x, y, lines: [str], readings: [str], definitions: [str]}
        this._hidePopup();
        if (typeof p.x !== 'number' || typeof p.y !== 'number') return;
        const x = Math.round(p.x);
        const y = Math.round(p.y);
        const lineH = 22;
        const pad = 12;
        const width = 360;
        const totalLines = (p.lines?.length || 0) + (p.readings?.length || 0) +
                          (p.definitions?.length || 0);
        const height = Math.max(80, totalLines * lineH + pad * 2);

        this._popupActor = new Clutter.Actor();
        this._popupActor.set_reactive(true);
        this._popupActor.set_position(x, y);
        this._popupActor.set_size(width, height);

        const canvas = new Clutter.Canvas();
        canvas.set_size(width, height);
        canvas.connect('draw', (cv, cr) => {
            cr.setSourceRGBA(0.07, 0.07, 0.07, 0.95);
            cr.rectangle(0, 0, width, height);
            cr.fill();
            cr.setSourceRGBA(0.34, 0.71, 0.65, 1.0);
            cr.setLineWidth(1);
            cr.rectangle(0.5, 0.5, width - 1, height - 1);
            cr.stroke();
            // v1 limitation: Cairo's Toy API in GJS doesn't reliably render
            // CJK glyphs. Pango (via PangoCairo) handles them correctly; that
            // integration is deferred. Plain ASCII lines render fine here.
            cr.setSourceRGBA(0.82, 0.82, 0.82, 1.0);
            let yy = pad;
            const sections = [
                {color: [1.0, 0.95, 0.7, 1.0], items: p.lines},
                {color: [0.4, 0.85, 0.93, 1.0], items: p.readings},
                {color: [0.82, 0.82, 0.82, 1.0], items: p.definitions},
            ];
            for (const s of sections) {
                for (const line of (s.items || [])) {
                    cr.setSourceRGBA(s.color[0], s.color[1], s.color[2], s.color[3]);
                    cr.selectFontFace('Sans', 0, 1 /* CAIRO_FONT_WEIGHT_BOLD */);
                    cr.setFontSize(14);
                    cr.moveTo(pad, yy + 10);
                    cr.showText(String(line).slice(0, 60));
                    yy += lineH;
                }
            }
        });
        this._popupCanvas = canvas;
        this._popupActor.set_content(canvas);
        canvas.invalidate();
        this._rootActor.add_child(this._popupActor);
    }

    _hidePopup() {
        if (this._popupActor) {
            this._rootActor.remove_child(this._popupActor);
            this._popupActor.destroy();
            this._popupActor = null;
            this._popupCanvas = null;
        }
    }
}

