_showPopup(p) {
    // p: {x, y, lines: [str], readings: [str], definitions: [str], mine: bool}
    this._hidePopup();
    if (typeof p.x !== 'number' || typeof p.y !== 'number') return;
    const x = Math.round(p.x);
    const y = Math.round(p.y);
    const lineH = 22;
    const pad = 12;
    const width = 360;
    const totalLines = (p.lines?.length || 0) + (p.readings?.length || 0) +
                      (p.definitions?.length || 0);
    const textHeight = Math.max(80, totalLines * lineH + pad * 2);
    const mineButtonH = (p.mine === false) ? 0 : 36;
    const height = textHeight + mineButtonH;

    this._popupTerm = (p.lines?.[0]) || '';
    this._popupActor = new Clutter.Actor();
    this._popupActor.set_reactive(true);
    this._popupActor.set_position(x, y);
    this._popupActor.set_size(width, height);

    const canvas = new Clutter.Canvas();
    canvas.set_size(width, height);
    canvas.connect('draw', (cv, cr) => {
        cr.setSourceRGBA(0.07, 0.07, 0.07, 0.95);
        cr.rectangle(0, 0, width, textHeight);
        cr.fill();
        cr.setSourceRGBA(0.34, 0.71, 0.65, 1.0);
        cr.setLineWidth(1);
        cr.rectangle(0.5, 0.5, width - 1, textHeight - 1);
        cr.stroke();
        // v1 limitation: Cairo's Toy API in GJS doesn't reliably render
        // CJK glyphs. Pango (via PangoCairo) handles them correctly; that
        // integration is deferred. Plain ASCII lines render fine here.
        cr.setSourceRGBA(0.82, 0.82, 0.82, 1.0);
        let yy = pad;
        const sections = [
            {color: [1.0, 0.95, 0.7, 1.0], items: p.lines},
            {color: [0.4, 0.85, 0.93, 1.0], items: p.readings},
            {color: [0.82, 0.82, 0.82, 1.0], items: p.definitions},
        ];
        for (const s of sections) {
            for (const line of (s.items || [])) {
                cr.setSourceRGBA(s.color[0], s.color[1], s.color[2], s.color[3]);
                cr.selectFontFace('Sans', 0, 1 /* CAIRO_FONT_WEIGHT_BOLD */);
                cr.setFontSize(14);
                cr.moveTo(pad, yy + 10);
                cr.showText(String(line).slice(0, 60));
                yy += lineH;
            }
        }
        if (mineButtonH > 0) {
            cr.setSourceRGBA(0.20, 0.50, 0.43, 1.0);
            cr.rectangle(0, textHeight, width, mineButtonH);
            cr.fill();
            cr.setSourceRGBA(0.82, 0.96, 0.92, 1.0);
            cr.selectFontFace('Sans', 0, 1);
            cr.setFontSize(14);
            cr.moveTo(pad, textHeight + 22);
            cr.showText('[ + ]  Mine to Anki');
        }
    });
    this._popupCanvas = canvas;
    this._popupActor.set_content(canvas);
    canvas.invalidate();

    if (mineButtonH > 0) {
        // Click target for the Mine button (bottom strip of the popup).
        this._mineTarget = new Clutter.Actor();
        this._mineTarget.set_reactive(true);
        this._mineTarget.set_position(0, textHeight);
        this._mineTarget.set_size(width, mineButtonH);
        this._mineTarget.set_opacity(0);
        this._mineTarget.connect('button-release-event', () => {
            if (this._dbus && this._popupTerm) {
                this._dbus.emit_signal(
                    'MineAnki',
                    new GLib.Variant('s', [this._popupTerm])
                );
                log(`[gnome-ocr-overlay] MineAnki(${this._popupTerm})`);
            }
            return Clutter.EVENT_STOP;
        });
        this._popupActor.add_child(this._mineTarget);
    }

    this._rootActor.add_child(this._popupActor);
}

