    // Drain MineAnki signals from the extension: extract the
    // {marker} placeholders from the anki config, call
    // yomitan-api /ankiFields for those markers, substitute the
    // values into the field templates, then call AnkiConnect
    // /addNote. This mirrors the qocr Quickshell flow in
    // shell/YomitanPopup.qml#addToAnki.
    let mine_rx_drain = mine_rx.clone();
    let config_for_mine = config_for_app.clone();
    glib::timeout_add_local(std::time::Duration::from_millis(100), move || {
        loop {
            let ev = {
                let mut rx = mine_rx_drain.lock().expect("mine_rx mutex");
                rx.try_recv()
            };
            let Ok(term) = ev else { break; };
            tracing::info!("mining '{term}' to Anki");
            let cfg = config_for_mine.clone();
            tokio::spawn(async move {
                let anki_cfg = cfg.anki.clone();
                if !anki_cfg.enable {
                    tracing::warn!("anki disabled in config; skipping mine");
                    return;
                }
                // Extract every {marker} used in the field templates.
                let mut markers: Vec<String> = Vec::new();
                for (_field, template) in &anki_cfg.fields {
                    let mut start = 0;
                    while let Some(open) = template[start..].find('{') {
                        let abs = start + open;
                        if let Some(close) = template[abs..].find('}') {
                            let marker = template[abs + 1..abs + close].to_string();
                            if !markers.contains(&marker) {
                                markers.push(marker);
                            }
                            start = abs + close + 1;
                        } else {
                            break;
                        }
                    }
                }
                tracing::debug!("anki markers: {markers:?}");
                let yc = yomitan::YomitanClient::new(&cfg.yomitan.api_url);
                let yomitan_resp = match yc.anki_fields(&term, &markers).await {
                    Ok(v) => v,
                    Err(e) => {
                        tracing::warn!("yomitan /ankiFields failed: {e}");
                        return;
                    }
                };
                // Build the fields map: template-substituted.
                let mut fields: std::collections::HashMap<String, String> = std::collections::HashMap::new();
                let yomitan_fields = yomitan_resp.get("fields").and_then(|x| x.as_array());
                if let Some(yfields) = yomitan_fields {
                    if let Some(first_entry) = yfields.first() {
                        if let Some(first_entry_obj) = first_entry.as_object() {
                            for (field_name, template) in &anki_cfg.fields {
                                let mut out = template.clone();
                                for (marker, val) in first_entry_obj {
                                    if let Some(s) = val.as_str() {
                                        out = out.replace(&format!("{{{marker}}}"), s);
                                    }
                                }
                                fields.insert(field_name.clone(), out);
                            }
                        }
                    }
                }
                if fields.is_empty() {
                    tracing::warn!("yomitan returned no fields for '{term}'; skipping mine");
                    return;
                }
                let ac = anki::AnkiClient::new(&anki_cfg.anki_connect_url);
                match ac.add_note(&anki_cfg.deck, &anki_cfg.model, &fields, &anki_cfg.tags, anki_cfg.allow_duplicate).await {
                    Ok(id) => tracing::info!("anki addNote OK: id={id}"),
                    Err(e) => tracing::warn!("anki addNote failed: {e}"),
                }
            });
        }
        glib::ControlFlow::Continue
    });

    // Suppress the unused `app` warning — we don't need the GTK app
    // for anything visible, only its main loop.
    let _ = app;
});

