//! PipeWire ScreenCast capture.
//!
//! Opens an xdg-desktop-portal ScreenCast session (the same path the working
//! smoke test proved on this machine), negotiates a BGRx video format, and
//! pushes each dequeued buffer into a tokio channel as
//! `(width, height, rgba_bytes)`.
//!
//! The portal dialog appears once per session; the user clicks Allow.

use std::os::fd::OwnedFd;
use std::rc::Rc;
use std::sync::{Arc, Mutex};

use anyhow::{Context, Result};
use ashpd::desktop::screencast::{
    CursorMode, Screencast, SelectSourcesOptions, SourceType,
};
use ashpd::enumflags2::BitFlags;
use pipewire as pw;
use pw::{main_loop::MainLoopRc, properties::properties, spa};
use spa::param::video::VideoInfoRaw;

/// A single captured frame in RGBA8 (the BGRx buffer is swizzled to RGBA
/// before it is handed to the caller so the image crate can encode it).
#[derive(Debug)]
pub struct Frame {
    pub width: u32,
    pub height: u32,
    pub rgba: Vec<u8>,
}

/// Request a ScreenCast session and start pumping frames into `tx`.
///
/// Returns once the portal session is established and the PipeWire stream is
/// connected. The calling thread must keep running for the capture thread to
/// keep producing frames; the channel closes when the stream errors out.
pub async fn start(tx: tokio::sync::mpsc::Sender<Frame>) -> Result<()> {
    let proxy = Screencast::new().await?;
    let session = proxy.create_session(Default::default()).await?;
    proxy
        .select_sources(
            &session,
            SelectSourcesOptions::default()
                .set_cursor_mode(CursorMode::Hidden)
                .set_sources(BitFlags::from(SourceType::Monitor))
                .set_multiple(false)
                .set_persist_mode(ashpd::desktop::PersistMode::DoNot),
        )
        .await?;
    let response = proxy
        .start(&session, None, Default::default())
        .await?
        .response()?;
    let stream = response
        .streams()
        .first()
        .context("portal returned no streams")?
        .to_owned();
    tracing::info!(
        "portal: node_id={} size={:?}",
        stream.pipe_wire_node_id(),
        stream.size()
    );
    let node_id: u32 = stream.pipe_wire_node_id();
    let fd: OwnedFd = proxy
        .open_pipe_wire_remote(&session, Default::default())
        .await?;

    let tx = Arc::new(Mutex::new(Some(tx)));
    std::thread::Builder::new()
        .name("pw-capture".into())
        .spawn(move || {
            if let Err(e) = run_pipewire(fd, node_id, &tx) {
                tracing::error!("pipewire thread: {e}");
            }
        })
        .context("spawn pw-capture thread")?;

    Ok(())
}

fn run_pipewire(
    fd: OwnedFd,
    node_id: u32,
    tx: &Arc<Mutex<Option<tokio::sync::mpsc::Sender<Frame>>>>,
) -> Result<()> {
    pw::init();
    let mainloop = MainLoopRc::new(None).context("MainLoopRc::new")?;
    let context = pw::context::ContextBox::new(mainloop.loop_(), None)
        .context("ContextBox::new")?;
    let core = context.connect_fd(fd, None).context("Context::connect_fd")?;

    let stream = pw::stream::StreamBox::new(
        &core,
        "gnome-ocr",
        properties! {
            *pw::keys::MEDIA_TYPE     => "Video",
            *pw::keys::MEDIA_CATEGORY => "Capture",
            *pw::keys::MEDIA_ROLE     => "Screen",
        },
    )?;

    let info: Arc<Mutex<VideoInfoRaw>> = Arc::new(Mutex::new(VideoInfoRaw::new()));
    let info_p = info.clone();
    let info_p2 = info.clone();
    let tx_p = tx.clone();

    let _listener = stream
        .add_local_listener_with_user_data(())
        .state_changed(move |_, _, old, new| {
            tracing::debug!("pw state: {old:?} -> {new:?}");
        })
        .param_changed(move |_, _, id, param| {
            let Some(param) = param else { return };
            if id != pw::spa::param::ParamType::Format.as_raw() {
                return;
            }
            let (mt, st) = match pw::spa::param::format_utils::parse_format(param) {
                Ok(v) => v,
                Err(_) => return,
            };
            if mt != spa::param::format::MediaType::Video
                || st != spa::param::format::MediaSubtype::Raw
            {
                return;
            }
            match info_p.lock().unwrap().parse(param) {
                Ok(()) => {
                    let g = info_p.lock().unwrap();
                    tracing::info!(
                        "negotiated format: {:?} {}x{}",
                        g.format(),
                        g.size().width,
                        g.size().height
                    );
                }
                Err(e) => tracing::error!("VideoInfoRaw parse: {e:?}"),
            }
        })
        .process(move |stream, _| {
            let Some(mut buf) = stream.dequeue_buffer() else { return };
            let Some(d) = buf.datas_mut().first_mut() else { return };
            let stride = d.chunk().stride().unsigned_abs() as usize;
            let (width, height) = {
                let g = info_p2.lock().unwrap();
                (g.size().width as u32, g.size().height as u32)
            };
            if width == 0 || height == 0 {
                return;
            }
            let Some(src) = d.data() else { return };
            let row_bytes = (width as usize * 4).min(stride);
            let mut rgba = vec![0u8; width as usize * height as usize * 4];
            for row in 0..height as usize {
                let s = row * stride;
                let dst = row * width as usize * 4;
                if s + row_bytes > src.len() {
                    break;
                }
                rgba[dst..dst + row_bytes].copy_from_slice(&src[s..s + row_bytes]);
            }
            // BGRx -> RGBA swizzle in place.
            for px in rgba.chunks_exact_mut(4) {
                px.swap(0, 2);
            }
            let guard = tx_p.lock().unwrap();
            let Some(sender) = guard.as_ref() else { return };
            // try_send so a slow OCR consumer drops frames instead of
            // stalling the PipeWire mainloop.
            let _ = sender.try_send(Frame { width, height, rgba });
        })
        .register()?;

    let obj = pw::spa::pod::object!(
        pw::spa::utils::SpaTypes::ObjectParamFormat,
        pw::spa::param::ParamType::EnumFormat,
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::MediaType,
            Id, spa::param::format::MediaType::Video),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::MediaSubtype,
            Id, spa::param::format::MediaSubtype::Raw),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::VideoFormat,
            Choice, Enum, Id,
            pw::spa::param::video::VideoFormat::BGRx,
            pw::spa::param::video::VideoFormat::BGRx,
            pw::spa::param::video::VideoFormat::RGBx,
            pw::spa::param::video::VideoFormat::RGBA,
            pw::spa::param::video::VideoFormat::RGB,
        ),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::VideoSize,
            Choice, Range, Rectangle,
            pw::spa::utils::Rectangle { width: 1920, height: 1080 },
            pw::spa::utils::Rectangle { width: 1, height: 1 },
            pw::spa::utils::Rectangle { width: 4096, height: 4096 }),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::VideoFramerate,
            Choice, Range, Fraction,
            pw::spa::utils::Fraction { num: 5, denom: 1 },
            pw::spa::utils::Fraction { num: 0,  denom: 1 },
            pw::spa::utils::Fraction { num: 30, denom: 1 }),
    );
    let values: Vec<u8> = pw::spa::pod::serialize::PodSerializer::serialize(
        std::io::Cursor::new(Vec::new()),
        &pw::spa::pod::Value::Object(obj),
    )?
    .0
    .into_inner();
    let mut params = [pw::spa::pod::Pod::from_bytes(&values).unwrap()];

    stream.connect(
        spa::utils::Direction::Input,
        Some(node_id),
        pw::stream::StreamFlags::AUTOCONNECT | pw::stream::StreamFlags::MAP_BUFFERS,
        &mut params,
    )?;
    tracing::info!("pipewire connected; running mainloop");
    mainloop.run();
    Ok(())
}

/// Keep the `Rc` import used: `MainLoopRc` is an Rc handle and the type
/// appears in this module's public signature path via `run_pipewire`.
#[allow(dead_code)]
fn _assert_rc_used(_: Rc<u8>) {}

//! PipeWire ScreenCast capture.
//!
//! Opens an xdg-desktop-portal ScreenCast session (the path proven working on
//! this machine by the original smoke test), negotiates a BGRx video format,
//! and pushes each dequeued buffer into a channel as RGBA8 bytes.
//!
//! Capture runs on its own OS thread driving the PipeWire mainloop, because
//! the PipeWire C API is not async. Frames are handed to the async side over
//! a bounded channel; if the consumer is slow, frames are dropped rather than
//! stalling the mainloop.

use std::os::fd::OwnedFd;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};

use anyhow::{Context, Result};
use ashpd::desktop::screencast::{CursorMode, Screencast, SelectSourcesOptions, SourceType};
use ashpd::enumflags2::BitFlags;
use ashpd::desktop::PersistMode;
use pipewire as pw;
use pw::{main_loop::MainLoopRc, properties::properties, spa};
use spa::param::video::VideoInfoRaw;
use tokio::sync::mpsc;

/// A single captured frame as RGBA8, ready to be encoded as PNG.
#[derive(Debug)]
pub struct Frame {
    pub width: u32,
    pub height: u32,
    pub rgba: Vec<u8>,
}

/// Handle for a running capture session. Dropping it does *not* stop capture;
/// call [`Session::stop`] to tear the PipeWire stream down.
pub struct Session {
    cancel: Arc<AtomicBool>,
}

impl Session {
    /// Ask the capture thread to unwind and close the stream.
    pub fn stop(&self) {
        self.cancel.store(true, Ordering::Relaxed);
    }
}

impl Drop for Session {
    fn drop(&mut self) {
        self.stop();
    }
}

/// Request a ScreenCast session and begin pumping frames into `tx`.
///
/// The portal shows a permission dialog once per session; the user must accept
/// it. This returns after the portal handshake, before any frame has arrived.
pub async fn start(tx: mpsc::Sender<Frame>) -> Result<Session> {
    let proxy = Screencast::new().await?;
    let session = proxy.create_session(Default::default()).await?;
    proxy
        .select_sources(
            &session,
            SelectSourcesOptions::default()
                .set_cursor_mode(CursorMode::Hidden)
                .set_sources(BitFlags::from(SourceType::Monitor))
                .set_multiple(false)
                .set_persist_mode(PersistMode::DoNot),
        )
        .await?;
    let response = proxy
        .start(&session, None, Default::default())
        .await?
        .response()?;
    let stream = response
        .streams()
        .first()
        .context("portal returned no streams")?
        .to_owned();
    tracing::info!(
        "portal granted: node_id={} size={:?}",
        stream.pipe_wire_node_id(),
        stream.size()
    );
    let node_id: u32 = stream.pipe_wire_node_id();
    let fd: OwnedFd = proxy
        .open_pipe_wire_remote(&session, Default::default())
        .await?;

    let cancel = Arc::new(AtomicBool::new(false));
    let tx = Arc::new(Mutex::new(Some(tx)));
    let thread_cancel = cancel.clone();

    std::thread::Builder::new()
        .name("gnome-ocr-capture".into())
        .spawn(move || {
            let result = run_pipewire(fd, node_id, &tx, &thread_cancel);
            if let Err(err) = result {
                tracing::error!("capture thread stopped: {err}");
            }
        })
        .context("spawn capture thread")?;

    Ok(Session { cancel })
}

fn run_pipewire(
    fd: OwnedFd,
    node_id: u32,
    tx: &Arc<Mutex<Option<mpsc::Sender<Frame>>>>,
    cancel: &Arc<AtomicBool>,
) -> Result<()> {
    pw::init();
    let mainloop = MainLoopRc::new(None).context("MainLoopRc::new")?;
    let context = pw::context::ContextBox::new(mainloop.loop_(), None)
        .context("ContextBox::new")?;
    let core = context.connect_fd(fd, None).context("connect_fd")?;

    let stream = pw::stream::StreamBox::new(
        &core,
        "gnome-ocr",
        properties! {
            *pw::keys::MEDIA_TYPE     => "Video",
            *pw::keys::MEDIA_CATEGORY => "Capture",
            *pw::keys::MEDIA_ROLE     => "Screen",
        },
    )?;

    let info: Arc<Mutex<VideoInfoRaw>> = Arc::new(Mutex::new(VideoInfoRaw::new()));
    let info_format = info.clone();
    let info_size = info.clone();
    let tx_frame = tx.clone();
    let cancel_cb = cancel.clone();

    let _listener = stream
        .add_local_listener_with_user_data(())
        .state_changed(move |_, _, old, new| {
            tracing::debug!("pipewire state: {old:?} -> {new:?}");
        })
        .param_changed(move |_, _, id, param| {
            let Some(param) = param else { return };
            if id != spa::param::ParamType::Format.as_raw() {
                return;
            }
            let Ok((media, sub)) = pw::spa::param::format_utils::parse_format(param) else {
                return;
            };
            if media != spa::param::format::MediaType::Video
                || sub != spa::param::format::MediaSubtype::Raw
            {
                return;
            }
            match info_format.lock().expect("format lock").parse(param) {
                Ok(()) => {
                    let g = info_format.lock().expect("format lock");
                    tracing::info!(
                        "negotiated {}x{} as {:?}",
                        g.size().width,
                        g.size().height,
                        g.format()
                    );
                }
                Err(err) => tracing::error!("VideoInfoRaw parse failed: {err:?}"),
            }
        })
        .process(move |stream, _| {
            if cancel_cb.load(Ordering::Relaxed) {
                return;
            }
            let Some(mut buffer) = stream.dequeue_buffer() else { return };
            let Some(datas) = buffer.datas_mut().first_mut() else {
                return;
            };
            let stride = datas.chunk().stride().unsigned_abs() as usize;
            let (width, height) = {
                let g = info_size.lock().expect("size lock");
                (g.size().width as u32, g.size().height as u32)
            };
            if width == 0 || height == 0 {
                return;
            }
            let Some(source) = datas.data() else { return };

            let row_bytes = (width as usize * 4).min(stride);
            let mut rgba = vec![0u8; width as usize * height as usize * 4];
            for (row, chunk) in rgba.chunks_mut(width as usize * 4).enumerate() {
                let src_offset = row * stride;
                let available = source.len().saturating_sub(src_offset);
                let copy = row_bytes.min(available).min(chunk.len());
                if copy == 0 {
                    break;
                }
                chunk[..copy].copy_from_slice(&source[src_offset..src_offset + copy]);
            }
            // BGRx -> RGBA, in place.
            for pixel in rgba.chunks_exact_mut(4) {
                pixel.swap(0, 2);
            }

            let guard = tx_frame.lock().expect("tx lock");
            let Some(sender) = guard.as_ref() else { return };
            // Non-blocking send: a slow consumer drops frames instead of
            // stalling the PipeWire mainloop and desynchronising the stream.
            let _ = sender.try_send(Frame {
                width,
                height,
                rgba,
            });
        })
        .register()?;

    let format_param = pw::spa::pod::object!(
        pw::spa::utils::SpaTypes::ObjectParamFormat,
        pw::spa::param::ParamType::EnumFormat,
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::MediaType,
            Id, spa::param::format::MediaType::Video),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::MediaSubtype,
            Id, spa::param::format::MediaSubtype::Raw),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::VideoFormat,
            Choice, Enum, Id,
            pw::spa::param::video::VideoFormat::BGRx,
            pw::spa::param::video::VideoFormat::BGRx,
            pw::spa::param::video::VideoFormat::RGBx,
            pw::spa::param::video::VideoFormat::RGBA,
            pw::spa::param::video::VideoFormat::RGB,
        ),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::VideoSize,
            Choice, Range, Rectangle,
            pw::spa::utils::Rectangle { width: 1920, height: 1080 },
            pw::spa::utils::Rectangle { width: 1, height: 1 },
            pw::spa::utils::Rectangle { width: 4096, height: 4096 }),
        pw::spa::pod::property!(
            pw::spa::param::format::VideoFormat::VideoFramerate,
            Choice, Range, Fraction,
            pw::spa::utils::Fraction { num: 5, denom: 1 },
            pw::spa::utils::Fraction { num: 0,  denom: 1 },
            pw::spa::utils::Fraction { num: 30, denom: 1 }),
    );
    let encoded = pw::spa::pod::serialize::PodSerializer::serialize(
        std::io::Cursor::new(Vec::new()),
        &pw::spa::pod::Value::Object(format_param),
    )?
    .0
    .into_inner();
    let mut params = [pw::spa::pod::Pod::from_bytes(&encoded)
        .context("re-parse format params")?];

    stream
        .connect(
            spa::utils::Direction::Input,
            Some(node_id),
            pw::stream::StreamFlags::AUTOCONNECT | pw::stream::StreamFlags::MAP_BUFFERS,
            &mut params,
        )
        .context("connect stream")?;
    tracing::info!("pipewire connected; entering mainloop");

    // Poll for cancellation so the thread can unwind and release the socket.
    let cancel_poll = cancel.clone();
    let quit = mainloop.clone();
    let poll_interval = std::time::Duration::from_millis(250);
    unsafe {
        pw::sys::loop_add_timer(
            mainloop.loop_(),
            libc::timespec {
                tv_sec: 0,
                tv_nsec: (poll_interval.as_nanos() as i64) as _,
            },
            &mut |_loop, _timer_data| {
                if cancel_poll.load(Ordering::Relaxed) {
                    quit.quit();
                }
                0
            },
            std::ptr::null_mut(),
        );
    }

    mainloop.run();
    tracing::info!("pipewire mainloop exited");
    Ok(())
}

