//! PipeWire ScreenCast capture.
//!
//! Opens an xdg-desktop-portal ScreenCast session (the path proven working on
//! this machine by the original smoke test), negotiates a BGRx video format,
//! and pushes each dequeued buffer into a channel as RGBA8 bytes.
//!
//! Capture runs on its own OS thread driving the PipeWire mainloop, because
//! the PipeWire C API is not async. Frames reach the async side over a bounded
//! channel; if the consumer is slow, frames are dropped rather than stalling
//! the mainloop and desynchronising the stream.

use std::os::fd::OwnedFd;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};

use anyhow::{Context, Result};
use ashpd::desktop::screencast::{CursorMode, Screencast, SelectSourcesOptions, SourceType};
use ashpd::desktop::PersistMode;
use ashpd::enumflags2::BitFlags;
use pipewire as pw;
use pw::{main_loop::MainLoopRc, properties::properties, spa};
use spa::param::video::VideoInfoRaw;
use tokio::sync::mpsc;

/// A single captured frame as RGBA8, ready to be encoded as PNG.
#[derive(Debug)]
pub struct Frame {
    pub width: u32,
    pub height: u32,
    pub rgba: Vec<u8>,
}

/// Handle for a running capture session.
///
/// Dropping the handle stops capture; the PipeWire thread unwinds on its next
/// frame and releases the socket.
pub struct Session {
    cancel: Arc<AtomicBool>,
}

impl Session {
    /// Ask the capture thread to unwind and close the stream.
    pub fn stop(&self) {
        self.cancel.store(true, Ordering::Relaxed);
    }
}

impl Drop for Session {
    fn drop(&mut self) {
        self.stop();
    }
}

/// Request a ScreenCast session and begin pumping frames into `tx`.
///
/// The portal shows a permission dialog once per session; the user must accept
/// it. Returns after the portal handshake, before any frame has arrived.
pub async fn start(tx: mpsc::Sender<Frame>) -> Result<Session> {
    let proxy = Screencast::new().await?;
    let session = proxy.create_session(Default::default()).await?;
    proxy
        .select_sources(
            &session,
            SelectSourcesOptions::default()
                .set_cursor_mode(CursorMode::Hidden)
                .set_sources(BitFlags::from(SourceType::Monitor))
                .set_multiple(false)
                .set_persist_mode(PersistMode::DoNot),
        )
        .await?;
    let response = proxy
        .start(&session, None, Default::default())
        .await?
        .response()?;
    let stream = response
        .streams()
        .first()
        .context("portal returned no streams")?
        .to_owned();
    tracing::info!(
        "portal granted: node_id={} size={:?}",
        stream.pipe_wire_node_id(),
        stream.size()
    );
    let node_id: u32 = stream.pipe_wire_node_id();
    let fd: OwnedFd = proxy
        .open_pipe_wire_remote(&session, Default::default())
        .await?;

    let cancel = Arc::new(AtomicBool::new(false));
    let tx = Arc::new(Mutex::new(Some(tx)));
    let thread_cancel = Arc::clone(&cancel);

    std::thread::Builder::new()
        .name("gnome-ocr-capture".into())
        .spawn(move || {
            if let Err(err) = run_pipewire(fd, node_id, &tx, &thread_cancel) {
                tracing::error!("capture thread stopped: {err}");
            }
        })
        .context("spawn capture thread")?;

    Ok(Session { cancel })
}

fn run_pipewire(
    fd: OwnedFd,
    node_id: u32,
    tx: &Arc<Mutex<Option<mpsc::Sender<Frame>>>>,
    cancel: &Arc<AtomicBool>,
) -> Result<()> {
    pw::init();
    let mainloop = MainLoopRc::new(None).context("MainLoopRc::new")?;
    let context = pw::context::ContextBox::new(mainloop.loop_(), None)
        .context("ContextBox::new")?;
    let core = context.connect_fd(fd, None).context("connect_fd")?;

    let stream = pw::stream::StreamBox::new(
        &core,
        "gnome-ocr",
        properties! {
            *pw::keys::MEDIA_TYPE     => "Video",
            *pw::keys::MEDIA_CATEGORY => "Capture",
            *pw::keys::MEDIA_ROLE     => "Screen",
        },
    )?;

    let info: Arc<Mutex<VideoInfoRaw>> = Arc::new(Mutex::new(VideoInfoRaw::new()));
    let info_format = Arc::clone(&info);
    let info_size = Arc::clone(&info);
    let tx_frame = Arc::clone(tx);
    let cancel_cb = Arc::clone(cancel);
    let mainloop_cb = mainloop.clone();

    let _listener = stream
        .add_local_listener_with_user_data(())
        .state_changed(move |_, _, old, new| {
            tracing::debug!("pipewire state: {old:?} -> {new:?}");
        })
        .param_changed(move |_, _, id, param| {
            let Some(param) = param else { return };
            if id != spa::param::ParamType::Format.as_raw() {
                return;
            }
            let Ok((media, sub)) = pw::spa::param::format_utils::parse_format(param) else {
                return;
            };
            if media != spa::param::format::MediaType::Video
                || sub != spa::param::format::MediaSubtype::Raw
            {
                return;
            }
            match info_format.lock().expect("format lock").parse(param) {
                Ok(()) => {
                    let g = info_format.lock().expect("format lock");
                    tracing::info!(
                        "negotiated {}x{} as {:?}",
                        g.size().width,
                        g.size().height,
                        g.format()
                    );
                }
                Err(err) => tracing::error!("VideoInfoRaw parse failed: {err:?}"),
            }
        })
        .process(move |stream, _| {
            // This callback fires once per frame, so it doubles as the
            // cancellation poll: unwind the mainloop when asked to stop.
            if cancel_cb.load(Ordering::Relaxed) {
                mainloop_cb.quit();
                return;
            }
            let Some(mut buffer) = stream.dequeue_buffer() else {
                return;
            };
            let Some(datas) = buffer.datas_mut().first_mut() else {
                return;
            };
            let stride = datas.chunk().stride().unsigned_abs() as usize;
            let (width, height) = {
                let g = info_size.lock().expect("size lock");
                (g.size().width as u32, g.size().height as u32)
            };
            if width == 0 || height == 0 {
                return;
            }
            let Some(source) = datas.data() else { return };

            let row_bytes = (width as usize * 4).min(stride);
            let row_len = width as usize * 4;
            let mut rgba = vec![0u8; row_len * height as usize];
            for (row, chunk) in rgba.chunks_mut(row_len).enumerate() {
                let src_offset = row * stride;
                let available = source.len().saturating_sub(src_offset);
                let copy = row_bytes.min(available).min(chunk.len());
                if copy == 0 {
                    break;
                }
                chunk[..copy].copy_from_slice(&source[src_offset..src_offset + copy]);
            }
            for pixel in rgba.chunks_exact_mut(4) {
                pixel.swap(0, 2);
            }

            let guard = tx_frame.lock().expect("tx lock");
            let Some(sender) = guard.as_ref() else { return };
            let _ = sender.try_send(Frame {
                width,
                height,
                rgba,
            });
        })
        .register()?;

    let format_param = pw::spa::pod::object!(
        pw::spa::utils::SpaTypes::ObjectParamFormat,
        pw::spa::param::ParamType::EnumFormat,
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::MediaType,
            Id, spa::param::format::MediaType::Video),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::MediaSubtype,
            Id, spa::param::format::MediaSubtype::Raw),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::VideoFormat,
            Choice, Enum, Id,
            pw::spa::param::video::VideoFormat::BGRx,
            pw::spa::param::video::VideoFormat::BGRx,
            pw::spa::param::video::VideoFormat::RGBx,
            pw::spa::param::video::VideoFormat::RGBA,
            pw::spa::param::video::VideoFormat::RGB,
        ),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::VideoSize,
            Choice, Range, Rectangle,
            pw::spa::utils::Rectangle { width: 1920, height: 1080 },
            pw::spa::utils::Rectangle { width: 1, height: 1 },
            pw::spa::utils::Rectangle { width: 4096, height: 4096 }),
        pw::spa::pod::property!(
            pw::spa::param::format::FormatProperties::VideoFramerate,
            Choice, Range, Fraction,
            pw::spa::utils::Fraction { num: 5, denom: 1 },
            pw::spa::utils::Fraction { num: 0,  denom: 1 },
            pw::spa::utils::Fraction { num: 30, denom: 1 }),
    );
    let encoded = pw::spa::pod::serialize::PodSerializer::serialize(
        std::io::Cursor::new(Vec::new()),
        &pw::spa::pod::Value::Object(format_param),
    )?
    .0
    .into_inner();
    let mut params =
        [pw::spa::pod::Pod::from_bytes(&encoded).context("re-parse format params")?];

    stream
        .connect(
            spa::utils::Direction::Input,
            Some(node_id),
            pw::stream::StreamFlags::AUTOCONNECT | pw::stream::StreamFlags::MAP_BUFFERS,
            &mut params,
        )
        .context("connect stream")?;
    tracing::info!("pipewire connected; entering mainloop");

    mainloop.run();
    tracing::info!("pipewire mainloop exited");
    Ok(())
}

//! OCR engine: wraps the `qocrd` daemon over stdio and turns frames into text.
//!
//! Frame -> PNG -> temp file -> `qocrd scanfile` -> newline-delimited JSON ->
//! text lines. The engine keeps the qocrd child alive between scans and
//! restarts it automatically if it dies, so the UI never has to care.

use std::io::Write;
use std::path::PathBuf;
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

use anyhow::{anyhow, Context, Result};
use image::{ImageBuffer, ImageFormat, Rgba};
use serde::Deserialize;

/// Where the qocrd wrapper lives. Checked in order; first that exists wins.
const QOCRD_CANDIDATES: &[&str] = &[
    "/home/camel/.local/bin/qocrd",
    "/home/camel/Downloads/qocr/.venv/bin/qocrd",
    "qocrd",
];

/// Temporary file the engine writes PNGs to before asking qocrd to read them.
///
/// Reused across scans so a long session does not litter /tmp.
fn scratch_path() -> PathBuf {
    std::env::temp_dir().join("gnome-ocr-frame.png")
}

#[derive(Debug, Deserialize)]
struct ScanFileResponse {
    #[serde(default)]
    text: String,
    #[serde(default)]
    lines: Vec<ScanLine>,
}

#[derive(Debug, Deserialize)]
struct ScanLine {
    #[serde(default)]
    text: String,
}

/// Result of scanning one frame.
#[derive(Debug, Default, Clone)]
pub struct ScanResult {
    /// Non-empty text lines, in reading order.
    pub lines: Vec<String>,
}

impl ScanResult {
    /// All recognised text joined by newlines.
    pub fn joined(&self) -> String {
        self.lines.join("\n")
    }
}

/// A running qocrd child process.
pub struct Engine {
    child: Child,
    stdin: ChildStdin,
    stdout: ChildStdout,
    japanese_only: bool,
}

impl Engine {
    /// Spawn qocrd, resolving the binary from the candidate list.
    pub fn spawn(japanese_only: bool) -> Result<Self> {
        let program = QOCRD_CANDIDATES
            .iter()
            .find(|path| {
                if *path == "qocrd" {
                    which(path).is_some()
                } else {
                    PathBuf::from(path).is_file()
                }
            })
            .context("could not find qocrd; tried ~/.local/bin/qocrd, the qocr venv, and PATH")?;

        tracing::info!("starting qocrd from {program}");
        let mut child = Command::new(program)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()
            .with_context(|| format!("spawn qocrd at {program}"))?;

        let stdin = child.stdin.take().context("qocrd stdin")?;
        let stdout = child.stdout.take().context("qocrd stdout")?;
        Ok(Self {
            child,
            stdin,
            stdout,
            japanese_only,
        })
    }

    /// Scan one RGBA frame and return the recognised lines.
    ///
    /// On any protocol error the qocrd child is replaced before returning, so
    /// the next scan starts from a clean daemon.
    pub fn scan(&mut self, rgba: &[u8], width: u32, height: u32) -> Result<ScanResult> {
        let path = scratch_path();
        write_png(&path, rgba, width, height)?;

        let command = format!(
            "scanfile {} {}\n",
            if self.japanese_only { "true" } else { "false" },
            path.display()
        );

        match self.exchange(&command) {
            Ok(lines) => {
                let _ = std::fs::remove_file(&path);
                Ok(ScanResult { lines })
            }
            Err(err) => {
                tracing::warn!("qocrd scan failed ({err}); restarting daemon");
                self.restart()?;
                let _ = std::fs::remove_file(&path);
                Err(err)
            }
        }
    }

    fn exchange(&mut self, command: &str) -> Result<Vec<String>> {
        self.stdin
            .write_all(command.as_bytes())
            .context("write command to qocrd")?;
        self.stdin.flush().context("flush qocrd stdin")?;

        let mut out = serde_json::Deserializer::from_reader(&mut self.stdout).into_iter::<ScanFileResponse>();
        let response = out
            .next()
            .ok_or_else(|| anyhow!("qocrd closed stdout"))?
            .context("parse qocrd response")?;

        let mut lines: Vec<String> = Vec::new();
        if !response.text.trim().is_empty() {
            lines.extend(
                response
                    .text
                    .lines()
                    .map(str::trim)
                    .filter(|l| !l.is_empty())
                    .map(ToOwned::to_owned),
            );
        }
        for line in response.lines {
            let text = line.text.trim();
            if !text.is_empty() {
                lines.push(text.to_owned());
            }
        }
        // qocrd may repeat the same content in both `text` and `lines`;
        // de-duplicate while preserving order.
        let mut seen = std::collections::HashSet::new();
        lines.retain(|l| seen.insert(l.clone()));
        Ok(lines)
    }

    fn restart(&mut self) -> Result<()> {
        let _ = self.child.kill();
        let _ = self.child.wait();
        let fresh = Self::spawn(self.japanese_only)?;
        self.child = fresh.child;
        self.stdin = fresh.stdin;
        self.stdout = fresh.stdout;
        Ok(())
    }
}

impl Drop for Engine {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
        let _ = std::fs::remove_file(scratch_path());
    }
}

fn write_png(path: &PathBuf, rgba: &[u8], width: u32, height: u32) -> Result<()> {
    let buffer = ImageBuffer::<Rgba<u8>, _>::from_raw(width, height, rgba.to_vec())
        .context("build image buffer")?;
    let mut file = std::fs::File::create(path).context("create scratch png")?;
    buffer
        .write_to(&mut std::io::BufWriter::new(&mut file), ImageFormat::Png)
        .context("encode png")?;
    Ok(())
}

fn which(binary: &str) -> Option<PathBuf> {
    std::env::var_os("PATH").and_then(|paths| {
        std::env::split_paths(&paths)
            .map(|dir| dir.join(binary))
            .find(|candidate| candidate.is_file())
    })
}

