        Ok(rt) => rt,
        Err(e) => { emit Failed; return; }
    };
    let (frame_tx, frame_rx) = std::sync::mpsc::sync_channel::<Frame>(2);

    let session = match rt.block_on(capture::start(frame_tx)) {
        Ok(s) => s,
        Err(e) => { emit Failed(format!("...")); return; }
    };
    emit Started;

    let mut engine = match engine::Engine::spawn(japanese_only) {
