//! GTK4 user interface.
//!
//! A single window: a toolbar with Start/Stop, an auto-copy switch, Copy all
//! and Clear; a status line; and a scrollable monospace text view that fills
//! with recognised text as the pipeline reports it.

use std::cell::RefCell;
use std::collections::HashSet;
use std::rc::Rc;

use async_channel::Receiver;
use gtk::gdk;
use gtk::glib;
use gtk::prelude::*;
use gtk::{gio, glib as gtk_glib};

use crate::pipeline::{Event, Pipeline};

const APP_ID: &str = "dev.local.gnome_ocr";

pub fn run(japanese_only: bool) -> glib::ExitCode {
    let app = gtk::Application::builder()
        .application_id(APP_ID)
        .flags(gio::ApplicationFlags::NON_UNIQUE)
        .build();

    app.connect_activate(move |app| {
        Window::new(app, japanese_only);
    });

    app.run()
}

struct Window {
    root: gtk::ApplicationWindow,
    start_button: gtk::Button,
    stop_button: gtk::Button,
    copy_button: gtk::Button,
    clear_button: gtk::Button,
    auto_copy: gtk::Switch,
    status: gtk::Label,
    buffer: gtk::TextBuffer,
    pipeline: RefCell<Option<Pipeline>>,
    japanese_only: bool,
    seen: RefCell<HashSet<String>>,
    lines: RefCell<Vec<String>>,
}

impl Window {
    fn new(app: &gtk::Application, japanese_only: bool) -> Self {
        let root = gtk::ApplicationWindow::builder()
            .application(app)
            .title("GNOME OCR")
            .default_width(760)
            .default_height(620)
            .build();
        root.add_css_class("gnome-ocr");

        let start_button = gtk::Button::with_label("Start OCR");
        start_button.add_css_class("suggested-action");
        start_button.add_css_class("pill");

        let stop_button = gtk::Button::with_label("Stop");
        stop_button.add_css_class("destructive-action");
        stop_button.add_css_class("pill");
        stop_button.set_sensitive(false);

        let copy_button = gtk::Button::with_label("Copy all");
        copy_button.add_css_class("pill");

        let clear_button = gtk::Button::with_label("Clear");
        clear_button.add_css_class("pill");

        let auto_copy = gtk::Switch::builder()
            .valign(gtk::Align::Center)
            .active(true)
            .build();

        let auto_copy_label = gtk::Label::new(Some("Auto-copy new text"));

        let toolbar = gtk::Box::new(gtk::Orientation::Horizontal, 8);
        toolbar.set_margin_top(12);
        toolbar.set_margin_bottom(8);
        toolbar.set_margin_start(12);
        toolbar.set_margin_end(12);
        toolbar.append(&start_button);
        toolbar.append(&stop_button);
        toolbar.append(&gtk::Separator::new(gtk::Orientation::Vertical));
        toolbar.append(&auto_copy_label);
        toolbar.append(&auto_copy);
        toolbar.append(&gtk::Separator::new(gtk::Orientation::Vertical));
        toolbar.append(&copy_button);
        toolbar.append(&clear_button);

        let status = gtk::Label::new(Some("Idle — press Start OCR to begin."));
        status.set_xalign(0.0);
        status.add_css_class("dim-label");
        status.set_margin_start(14);
        status.set_margin_end(14);
        status.set_margin_bottom(8);

        let text_view = gtk::TextView::new();
        text_view.set_editable(false);
        text_view.set_cursor_visible(true);
        text_view.set_monospace(true);
        text_view.set_wrap_mode(gtk::WrapMode::WordChar);
        text_view.set_left_margin(12);
        text_view.set_right_margin(12);
        text_view.set_top_margin(8);
        text_view.set_bottom_margin(8);
        text_view.add_css_class("card");

        let buffer = text_view.buffer();

        let scroller = gtk::ScrolledWindow::builder()
            .hexpand(true)
            .vexpand(true)
            .child(&text_view)
            .build();
        scroller.set_margin_start(12);
        scroller.set_margin_end(12);
        scroller.set_margin_bottom(12);
        scroller.set_has_frame(true);

        let layout = gtk::Box::new(gtk::Orientation::Vertical, 0);
        layout.append(&toolbar);
        layout.append(&status);
        layout.append(&scroller);
        root.set_child(Some(&layout));

        let (sender, receiver) = glib::MainContext::default().channel::<Event>(64);

        let this = Self {
            root,
            start_button,
            stop_button,
            copy_button,
            clear_button,
            auto_copy,
            status,
            buffer,
            pipeline: RefCell::new(None),
            japanese_only,
            seen: RefCell::new(HashSet::new()),
            lines: RefCell::new(Vec::new()),
        };

        this.wire(&sender);
        this.consume(receiver);
        this.root.present();
        this
    }

    fn wire(&self, sender: &async_channel::Sender<Event>) {
        let owner = Rc::new(());

        let click_owner = Rc::clone(&owner);
        let click_sender = sender.clone();
        self.start_button.connect_clicked(move |_| {
            click_owner.start_pipeline(&click_sender);
        });

        let stop_owner = Rc::clone(&owner);
        self.stop_button.connect_clicked(move |_| {
