        self.clear_button.connect_clicked(move |_| clear_owner.clear());

        let toggle_owner = Rc::clone(&owner);
        self.auto_copy.connect_active_notify(move |switch| {
            let state = if switch.is_active() { "on" } else { "off" };
            toggle_owner.set_status(&format!("Auto-copy is {state}."));
        });
    }

    fn consume(self: Rc<Self>, receiver: Receiver<Event>) {
        glib::spawn_future_local(async move {
            let owner = Rc::clone(&self);
