        self.stop_button.set_sensitive(true);
        self.set_status("Waiting for screen-capture permission…");

        let pipeline = Pipeline::start(sender.clone(), self.japanese_only);
        *self.pipeline.borrow_mut() = Some(pipeline);
    }

    fn handle(self: &Rc<Self>, event: Event) {
        match event {
            Event::Started => {
                self.start_button.set_sensitive(false);
                self.stop_button.set_sensitive(true);
                self.set_status("Capturing — showing new text as it appears.");
            }
            Event::Fresh { lines, total } => {
                let joined = lines.join("\n");
                self.append(&format!("{joined}\n"));
                if self.auto_copy.is_active() {
                    self.root.clipboard().set_text(&joined);
                }
                self.set_status(&format!("{total} line(s) captured."));
            }
            Event::Failed(err) => {
                self.set_status(&format!("Problem: {err}"));
                self.start_button.set_sensitive(true);
                self.stop_button.set_sensitive(false);
            }
            Event::Stopped => {
                *self.pipeline.borrow_mut() = None;
                self.start_button.set_sensitive(true);
                self.stop_button.set_sensitive(false);
            }
        }
    }

    fn append(&self, text: &str) {
        self.lines.borrow_mut().push(text.to_owned());
        let all = self.lines.borrow().concat();
        self.buffer.set_text(&all);
        self.scroll_to_end();
    }

    fn copy_all(&self) {
        let all = self.lines.borrow().concat();
        if all.is_empty() {
            self.set_status("Nothing to copy yet.");
            return;
        }
        self.root.clipboard().set_text(all.trim_end());
        self.set_status("Copied everything to the clipboard.");
    }

    fn clear(&self) {
        self.lines.borrow_mut().clear();
        self.seen.borrow_mut().clear();
        self.buffer.set_text("");
        self.set_status("Cleared.");
    }

    fn set_status(&self, text: &str) {
        self.status.set_text(text);
    }

    fn scroll_to_end(&self) {
        let Some(view) = self.buffer.end_iter() else {
            return;
        };
        if let Some(view) = view.upcast::<gtk::TextView>() {
            view.scroll_to_iter(&view.buffer().end_iter(), 0.0, false, 0.0, 0.0);
        }
    }
}

impl std::ops::Deref for Window {
    type Target = gtk::ApplicationWindow;

    fn deref(&self) -> &Self::Target {
        &self.root
    }
}

