/// Converts a mapped PipeWire frame into RGBA8.
fn convert_frame(
    source: &[u8],
    width: u32,
    height: u32,
    stride: usize,
    pixel_size: usize,
    format: VideoFormat,
) -> Option<Vec<u8>> {
    let row_bytes = width as usize * pixel_size;
    if source.len() < stride.saturating_mul(height as usize) {
        return None;
    }
