/// Crops the frame to the region, in fractions of the frame.
fn crop(rgba: &[u8], width: u32, height: u32, region: Region) -> Option<(Vec<u8>, u32, u32)> {
    if region.is_empty() { return None; }
    let x0 = (region.x * width as f64).round().clamp(0.0, width as f64) as u32;
    let y0 = (region.y * height as f64).round().clamp(0.0, height as f64) as u32;
    let x1 = ((region.x + region.width) * width as f64).round().clamp(0.0, width as f64) as u32;
    let y1 = ((region.y + region.height) * height as f64).round().clamp(0.0, height as f64) as u32;
    let w = x1.saturating_sub(x0);
    let h = y1.saturating_sub(y0);
    if w == 0 || h == 0 { return None; }
    let mut out = Vec::with_capacity((w * h * 4) as usize);
    for y in y0..y1 {
        let start = ((y as usize * width as usize) + x0 as usize) * 4;
        let end = start + (w as usize * 4);
        out.extend_from_slice(rgba.get(start..end)?);
    }
    Some((out, w, h))
