        out.extend_from_slice(rgba.get(start..end)?);
    }
    Some((out, cropped_width, cropped_height))
}
"""
s = s.replace("/// Each engine needs its own scratch file",
              helper + "\n/// Each engine needs its own scratch file")
p.write_text(s)
print("engine: region cropping applied")
