}

impl Preview {
    fn new() -> Self {
        Self {
            surface: RefCell::new(None),
            crop: RefCell::new(None),
            drag: RefCell::new(None),
        }
    }

    /// The size of the captured frame in pixels.
    fn size(&self) -> (f64, f64) {
        match self.surface.borrow().as_ref() {
