//! Prints the coordinate spaces GTK uses, so the crop mapping can be checked.
//!
//! Run with GDK_BACKEND=x11 and drive the pointer with xdotool.

use gtk::prelude::*;

fn main() -> gtk::glib::ExitCode {
    let app = gtk::Application::builder()
        .application_id("dev.local.gnome-ocr.coordtest")
        .build();

    app.connect_activate(|app| {
        let window = gtk::ApplicationWindow::builder()
            .application(app)
            .title("coordtest")
            .default_size(600, 400)
            .build();

        let area = gtk::DrawingArea::builder()
            .hexpand(true)
            .vexpand(true)
            .build();
        area.add_css_class("card");

        let outer = gtk::Box::new(gtk::Orientation::Vertical, 0);
        outer.set_margin_top(37);
        outer.set_margin_start(53);
        outer.append(&area);
        window.set_child(Some(&outer));

        area.set_draw_func(|_area, context, width, height| {
            context.set_source_rgb(0.15, 0.15, 0.15);
            let _ = context.paint();
            context.set_source_rgb(0.9, 0.2, 0.2);
            context.rectangle(0.0, 0.0, 100.0, 100.0);
            let _ = context.fill();
            context.set_source_rgb(0.2, 0.9, 0.3);
            context.rectangle(0.0, 0.0, width as f64, 20.0);
            let _ = context.fill();
        });

        let drag_area = area.clone();
        let drag = gtk::GestureDrag::new();
        drag.connect_drag_begin(move |_gesture, x, y| {
            let allocation = drag_area.allocation();
            println!(
                "DRAG  x={x:.1} y={y:.1}  alloc=({},{}) {}x{}",
                allocation.x(),
                allocation.y(),
                allocation.width(),
                allocation.height()
            );
        });
        area.add_controller(drag);

        let motion_area = area.clone();
        let motion = gtk::EventControllerMotion::new();
        motion.connect_motion(move |_controller, x, y| {
            let allocation = motion_area.allocation();
            println!(
                "MOTION x={x:.1} y={y:.1}  alloc=({},{}) {}x{}",
                allocation.x(),
                allocation.y(),
                allocation.width(),
                allocation.height()
            );
        });
        area.add_controller(motion);

        window.present();
    });

    app.run()
}

