//! Checks what GtkGestureDrag reports, so the crop mapping can be trusted.
//!
//! Run with GDK_BACKEND=x11 and drive it with xdotool.

use gtk::prelude::*;

fn main() -> gtk::glib::ExitCode {
    let app = gtk::Application::builder()
        .application_id("dev.local.gnome-ocr.dragprobe")
        .build();

    app.connect_activate(|app| {
        let window = gtk::ApplicationWindow::builder()
            .application(app)
            .title("dragprobe")
            .build();
        window.set_default_size(600, 400);

        let area = gtk::DrawingArea::builder()
            .hexpand(true)
            .vexpand(true)
            .build();
        window.set_child(Some(&area));

        area.set_draw_func(|_area, context, width, height| {
            context.set_source_rgb(0.15, 0.15, 0.15);
            let _ = context.paint();
            context.set_source_rgb(0.9, 0.2, 0.2);
            context.rectangle(0.0, 0.0, 100.0, 100.0);
            let _ = context.fill();
        });

        let accumulated = std::rc::Rc::new(std::cell::Cell::new((0.0f64, 0.0f64)));

        let begin_area = area.clone();
        let drag = gtk::GestureDrag::new();
        drag.connect_drag_begin(move |_gesture, x, y| {
            println!("BEGIN   abs=({x:.1},{y:.1})");
            begin_area.queue_draw();
        });
        area.add_controller(drag);

        let update_area = area.clone();
        let acc = std::rc::Rc::clone(&accumulated);
        drag.connect_drag_update(move |_gesture, dx, dy| {
            let (x, y) = acc.get();
            let (x, y) = (x + dx, y + dy);
            acc.set((x, y));
            println!("UPDATE   delta=({dx:.1},{dy:.1})  accumulated=({x:.1},{y:.1})");
            update_area.queue_draw();
        });
        area.add_controller(drag);

        window.present();
    });

    app.run()
}

