```rust
fn scaled_surface(&self, width: i32, height: i32) -> Option<cairo::ImageSurface> {
    let mut cached = self.scaled.borrow_mut();
    if let Some((surface, w, h)) = cached.as_ref() && *w == width && *h == height {
        return Some(surface.clone());   // ← returns the FIRST frame, forever
    }
```

