/// The heading the text belongs under.
fn section_of(layout: &crate::layout::Layout, blocks: &[crate::layout::Block]) -> Option<String> {
    let sections = layout.sections();
    for block in blocks {
        for section in &sections {
            match block {
                crate::layout::Block::Heading { text, .. } => {
                    if section.heading.as_ref().is_some_and(|h| &h.text == text) {
                        return Some(text.clone());
