fn detect_lists(lines: &[&Line], median_height: f64) -> Vec<ListGroup> {
    let mut groups: Vec<ListGroup> = Vec::new();
    let mut run: Vec<&Line> = Vec::new();

    let flush = |run: &mut Vec<&Line>, groups: &mut Vec<ListGroup>| {
