fn detect_lists(lines: &[&Line], median_height: f64) -> Vec<ListGroup> {
    let mut groups = Vec::new();
    let mut start = 0;
    while start < lines.len() {
        // Extend the run while the lines are short, aligned and evenly spaced.
        let mut end = start + 1;
        while end < lines.len() && belongs_with(lines, end - 1, end, median_height) {
            end += 1;
        }
        if end - start >= MIN_LIST_ITEMS {
            groups.push(make_list(&lines[start..end]));
            start = end;
        } else {
            start += 1;
        }
    }
    groups
}

/// Whether the line after `previous` looks like another item of the same list.
fn belongs_with(lines: &[&Line], previous: usize, next: usize, median_height: f64) -> bool {
    let previous = lines[previous];
    let next = lines[next];
    if next.text.chars().count() > MAX_ITEM_CHARS {
