import pathlib
p = pathlib.Path("src/layout.rs")
s = p.read_text()

# The list detection now works on the blocks of a band, and uses the measured
# spacing rather than a fixed multiple of the text height.
old_start = s.index("/// Finds the runs of lines that are a list: short entries that line up and")
old_end = s.index("/// Keeps a run of lines if it is long enough to be a list.")
new = '''/// Finds the runs of blocks that are a list.
///
/// The entries of a menu are separate blocks that share a left edge and sit
/// an even distance apart, and the distance that sets a list apart from the
/// rest of the page is larger. Which distance is larger is worked out from
/// the gaps themselves, by splitting them into a lower and an upper group
/// with Otsu's method, so no threshold is chosen by hand.
fn detect_lists(lines: &[&Line], median_height: f64) -> Vec<Vec<usize>> {
    let mut groups: Vec<Vec<usize>> = Vec::new();
    for band in align_bands(lines, median_height) {
        detect_runs(&band, lines, median_height, &mut groups);
    }
    groups
}

/// Puts the lines into bands that share a left edge.
///
/// A column of text, and the entries of a menu, all line up on the left. The
/// entries of two columns sit at the same height as one another, so the bands
/// are what keep the two apart.
fn align_bands(lines: &[&Line], median_height: f64) -> Vec<Vec<usize>> {
    let mut by_edge: Vec<usize> = (0..lines.len()).collect();
    by_edge.sort_by(|a, b| {
        lines[*a]
            .bounds
            .x
            .partial_cmp(&lines[*b].bounds.x)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    let mut bands: Vec<Vec<usize>> = Vec::new();
    let mut band: Vec<usize> = Vec::new();

    for index in by_edge {
        let edge = lines[index].bounds.x;
        let same_band = match band.first() {
            Some(first) => {
                (edge - lines[*first].bounds.x).abs() <= ITEM_ALIGNMENT * median_height
            }
            None => true,
        };
        if same_band {
            band.push(index);
        } else {
            bands.push(std::mem::take(&mut band));
            band.push(index);
        }
    }
    if !band.is_empty() {
        bands.push(band);
    }

    bands
}

/// Finds the evenly spaced runs within one band of aligned lines.
fn detect_runs(
    band: &[usize],
    lines: &[&Line],
    median_height: f64,
    groups: &mut Vec<Vec<usize>>,
) {
    let mut ordered: Vec<usize> = band.to_vec();
    ordered.sort_by(|a, b| {
        lines[*a]
            .bounds
            .y
            .partial_cmp(&lines[*b].bounds.y)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    let gaps = gaps_between(&ordered, lines);
    let threshold = otsu_threshold(&gaps);

    let mut run: Vec<usize> = Vec::new();
    for (position, index) in ordered.iter().enumerate() {
        let line = lines[*index];
        if line.text.chars().count() > MAX_ITEM_CHARS {
            push_group(&mut run, groups);
            continue;
        }
        if let Some(threshold) = threshold
            && position > 0
        {
            let gap = gaps[position - 1];
            if gap > threshold {
                push_group(&mut run, groups);
            }
        }
        run.push(*index);
    }
    push_group(&mut run, groups);
}

/// The vertical gaps between the lines of a run, in order.
fn gaps_between(ordered: &[usize], lines: &[&Line]) -> Vec<f64> {
    ordered
        .windows(2)
        .map(|pair| {
            let upper = lines[pair[0]].bounds.bottom();
            let lower = lines[pair[1]].bounds.y;
            (lower - upper).max(0.0)
        })
        .collect()
}

'''
s = s[:old_start] + new + s[old_end:]
p.write_text(s)
print("list detection uses the measured gaps")
