import pathlib
p = pathlib.Path("src/layout.rs")
s = p.read_text()
old = """//! Working out the order and the structure of recognised text.
//!
//! The OCR engine reports where each line was found but not the order they
//! should be read in. That is worked out from the geometry, using the approach
//! the document analysis literature settled on: group the lines into paragraphs,
//! then cut the page recursively at the widest run of whitespace to recover
//! the reading order and the structure at the same time.
//!
//! Vertical runs, which is how Japanese is often written, are kept apart and
//! read from the right."""
new = """//! Working out the order and the structure of recognised text.
//!
//! The OCR engine reports where each line was found but not the order they
//! should be read in. That is worked out from the geometry, using the approach
//! the document analysis literature settled on: group the lines into paragraphs,
//! then cut the page recursively at the widest run of whitespace to recover
//! the reading order and the structure at the same time.
//!
//! Vertical runs, which is how Japanese is often written, are kept apart and
//! read from the right.
//!
//! # How the thresholds are worked out
//!
//! Every threshold here is a ratio of something measured from the page, and
//! never an absolute size, which is the point of the document spectrum: the
//! tolerances are multipliers of the spacings that the page itself shows.
//!
//! - The size of the ordinary text comes from the height that most of the
//!   lines share.
//! - Where one block ends and the next begins comes from the gaps between
//!   the lines, split into a lower and an upper group by Otsu's method, which
//!   is the same thresholding an image histogram uses.
//! - The measure of the text, which says how wide a line of running text
//!   reaches, is the width of the widest line on the page.
//!
//! The only number that is not a ratio is how many entries make a list,
//! which is a definition rather than a tolerance: the list detection work
//! says a list is three or more records."""
assert old in s
s = s.replace(old, new)
p.write_text(s)
print("module documented")
