        let mut fresh = Vec::new();
        for block in &layout.blocks {
            let detection = crate::dedupe::Detection {
                text: block.text().to_owned(),
                bounds: crate::dedupe::Box {
                    x: block.bounds().x,
                    y: block.bounds().y,
                    width: block.bounds().width,
                    height: block.bounds().height,
                },
            };
            if history.is_new(&detection) {
                fresh.push(block.clone());
            }
        }
        total += fresh.len();
        // The picture is only made when there is new text, so
        // the frames that carried nothing are not kept.
        let image = if fresh.is_empty() {
            None
        } else {
            scan.scanned.and_then(|scanned| {
                crate::preview::preview_png(
                    &scanned.rgba,
                    scanned.width,
                    scanned.height,
                    320,
                )
            })
        };
        emit(
            &events,
            Event::Scanned {
                fresh,
                total,
                image,
                lines: scan.lines,
                layout,
            },
        );

