//! Asking Yomitan what the text means.

/// The address the API is served on.
const API: &str = "http://127.0.0.1:19633";

/// A word the API found in the text.
pub struct Segment { pub text: String, pub reading: String, ... }

/// Posts to the API and returns the answer.
fn post(path: &str, body: &serde_json::Value) -> Result<serde_json::Value>;

/// Splits the text into the words it is made of, with their readings.
pub fn tokenize(text: &str) -> Result<Vec<Segment>>;

/// The dictionary entries for a word.
pub fn entries(term: &str) -> Result<Vec<Entry>>;

/// The text of the answer with the readings marked: 人気（にんき）のおかず
pub fn with_readings(text: &str, segments: &[Segment]) -> String;
```

